/// Default per-xite size limit, in MB. The Epix python client raised its
/// `--size-limit` default from EpixNet's 10 to 1000; a growing xite stops
/// syncing at this cap until the user raises it, so the old 10 broke any
/// xite past 10 MB out of the box.
pub const DEFAULT_SIZE_LIMIT_MB: i64 = 1000;

/// Disk donated to the encrypted-shard cache by default.
///
/// Non-zero on desktop because a volunteer cache with no volunteers is not a
/// cache: the shards a publisher's private content is split into have to
/// live SOMEWHERE other than the publisher, or the content dies with them
/// and the publisher is the one peer holding it all. What a volunteer holds
/// is ciphertext addressed by hash, with no record tying it to any xite, so
/// donating is cheap in every sense except disk.
///
/// Zero on phones: storage is small, and a background hold competes with the
/// user's own data plan and battery for no benefit they can see.
#[cfg(any(target_os = "android", target_os = "ios"))]
pub const DEFAULT_VOLUNTEER_QUOTA: &str = "0";
#[cfg(not(any(target_os = "android", target_os = "ios")))]
pub const DEFAULT_VOLUNTEER_QUOTA: &str = "2147483648"; // 2 GiB

/// What a boot-time registration pass actually did
/// ([`AppState::edx_register_all_loaded`]).
///
/// Counts OBJECTS, not just xites. A pass that walks every xite and stores
/// nothing is the failure mode worth seeing - it means the node is serving
/// none of that content to peers - and a xite count cannot distinguish it
/// from a healthy pass.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RegisterTally {
    /// Xites whose manifest could be read and walked.
    pub xites: usize,
    /// Objects now in the store because of this pass (or already there).
    pub registered: usize,
    /// Declared files that could not be registered: missing locally, or on
    /// disk but no longer matching their declared hash.
    pub skipped: usize,
    /// Xites whose content.json could not be loaded at all.
    pub unreadable: usize,
    /// Xites skipped by activation because their verified index could not be
    /// rebuilt (corrupt or unverifiable manifest on disk). Their files stay
    /// on disk and re-register on the next activation once repaired; nothing
    /// is served for them meanwhile.
    pub quarantined: usize,
}

impl std::fmt::Display for RegisterTally {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{} object(s) from {} xite(s)", self.registered, self.xites)?;
        if self.skipped > 0 {
            write!(f, ", {} file(s) skipped", self.skipped)?;
        }
        if self.unreadable > 0 {
            write!(f, ", {} xite(s) unreadable", self.unreadable)?;
        }
        if self.quarantined > 0 {
            write!(f, ", {} xite(s) quarantined (verification failed)", self.quarantined)?;
        }
        // The case that hid a real problem: xites walked, nothing stored.
        // Almost always pre-EDX manifests that have not been re-signed, and
        // it means none of those files can be served.
        if self.registered == 0 && self.xites > 0 {
            write!(f, " - nothing to serve yet (manifests carry no b3; re-sign to publish over EDX)")?;
        }
        Ok(())
    }
}

/// Resolves + clones a `.epix` host that isn't served yet, so the browser can
/// open any name by typing it. Implemented by the node (which has the chain
/// resolver + download worker); the UI server calls it via
/// [`AppState::ensure_xite`]. Kept as a trait so `epix-ui` has no dependency on
/// the chain/worker crates.
#[async_trait::async_trait]
pub trait OnDemandResolver: Send + Sync {
    /// Resolve + clone `host` and add it as a served xite. `Ok(())` once served.
    async fn ensure(&self, host: &str) -> Result<(), String>;

    /// Resolve `host` (a `.epix` name or an address) to a xite address WITHOUT
    /// cloning: the on-disk cache first, the chain on a miss. Used so a
    /// locked-down node can still follow an xID to a xite it already serves.
    async fn resolve(&self, host: &str) -> Option<String>;
}

/// Extra peer discovery beyond the trackers - the runtime installs a DHT
/// lookup here so announces and on-demand clones can find peers for rare
/// xites when the trackers come up short. Kept as a trait so `epix-ui` has
/// no dependency on the DHT crates.
#[async_trait::async_trait]
pub trait PeerFinder: Send + Sync {
    /// Find peers hosting the xite at `address` (bech32).
    async fn find(&self, address: &str) -> Vec<PeerAddr>;
}

/// Fetch a xite's included / per-user content (user_contents xites keep their
/// data - topics, posts - outside the root's file list). Implemented by the
/// node (it has the chain resolver for user xIDs); the resync loop calls it so
/// existing xites pick up new and backfilled user content.
#[async_trait::async_trait]
pub trait ContentSyncer: Send + Sync {
    /// Sync `address`'s included/user content; returns bytes downloaded and
    /// the inner paths of the files that arrived (for `file_done` events).
    async fn sync_user_content(&self, address: &str) -> (u64, Vec<String>);
}

/// Largest immutable record delta accepted from a live update source.
pub const MAX_MERGE_DELTA_OBJECT_BYTES: u64 = 8 * 1024 * 1024;

/// One immutable merge-delta object named by the transport. Runtime decodes
/// its private wire envelope into this neutral reference. State does not fetch
/// it until the verified child manifest authorizes the exact merge path.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct EdxObjectRef {
    pub id: epix_blob::ObjId,
    pub size: u64,
}

/// The data carried by one live publish push.
///
/// Regular files use line diffs. Signed CRDT merge files use small record
/// deltas, so a post/comment/reaction travels with its content.json bump and
/// does not depend on the receiver being able to dial back to the publisher.
/// Merge deltas are keyed by path relative to the governing content.json and
/// are verified record-by-record before they are written or re-broadcast.
#[derive(Clone, Debug, Default)]
pub struct UpdatePayload {
    pub diffs: HashMap<String, Vec<epix_content::DiffAction>>,
    /// Per merge path, ONE of three shapes (never two for the same path -
    /// [`Self::validate_disjoint_paths`] is the shared enforcement):
    /// a non-empty value here is an inline record container; an EMPTY value
    /// is the legacy full-file pull marker ("fetch the whole file yourself");
    /// a path present in `merge_objects` instead names an immutable object
    /// to stream. Producing an empty value by accident silently means "pull",
    /// so construction sites must never emit one for a real delta.
    pub merge_deltas: HashMap<String, Vec<u8>>,
    pub merge_objects: HashMap<String, EdxObjectRef>,
    /// The sending session advertised INLINE_MERGE, so an `Ok` reply is a
    /// delivery receipt, not merely a manifest receipt. Runtime-only. This is
    /// derived from the authenticated Hello and is never serialized itself.
    pub require_merge_delivery: bool,
    /// Runtime-only, set by the clone's child-manifest pass: verify and stage
    /// the manifest but do NOT pull its required files inline. The caller
    /// batches every deferred child's files in one fetch over the clone's
    /// proven peers instead of paying a per-child session each. A deferral is
    /// then a normal outcome ([`InboundUpdate::Deferred`]), not an error.
    /// Never set on live pushes: their availability receipts stay honest.
    pub defer_required_fetch: bool,
}

impl UpdatePayload {
    /// Whether an acceptance only counts as delivery once the receiver has
    /// explicitly handled the payload. The single definition of the rule:
    /// inline merge deltas need a payload-aware ACK before a merge snapshot
    /// may be retired; everything else is delivered when the manifest lands.
    fn requires_payload_ack(&self) -> bool {
        !self.merge_deltas.is_empty()
    }

    /// Wire-shape rule shared by every inbound consumer: one path may ride as
    /// EITHER an inline delta or an object marker, never both. The single
    /// definition — the child-staging, current-version-merge, and inbound
    /// entry paths all enforce the same rule through here.
    fn validate_disjoint_paths(&self) -> Result<(), String> {
        if self
            .merge_deltas
            .keys()
            .any(|path| self.merge_objects.contains_key(path))
        {
            return Err("Merge payload repeats a path".into());
        }
        Ok(())
    }

    /// The payload a RELAY may forward, built so session-scoped state is
    /// structurally unable to survive the hop: the connection-derived
    /// require_merge_delivery flag is never carried, and object markers this
    /// node cannot serve are dropped. Every re-broadcast builds its payload
    /// through here instead of hand-clearing fields at each site.
    fn relay_form(&self) -> UpdatePayload {
        UpdatePayload {
            diffs: self.diffs.clone(),
            merge_deltas: self.merge_deltas.clone(),
            merge_objects: HashMap::new(),
            require_merge_delivery: false,
            defer_required_fetch: false,
        }
    }

    /// [`Self::validate_disjoint_paths`] plus the declared-path rule applied
    /// once a governing manifest is at hand: every payload path must be a
    /// merge file that manifest declares.
    fn validate_against_declared(&self, declared: &[String]) -> Result<(), String> {
        self.validate_disjoint_paths()?;
        if self
            .merge_deltas
            .keys()
            .chain(self.merge_objects.keys())
            .any(|path| !declared.iter().any(|candidate| candidate == path))
        {
            return Err("Merge payload names an undeclared path".into());
        }
        Ok(())
    }
}

/// Fetches a file's bytes over the EDX verified-streaming path (installed by
/// the node, which owns the EDX client stack). Kept behind a trait so the UI
/// crate stays free of the transport/swarm dependency, like the resolvers.
#[async_trait::async_trait]
pub trait EdxFetcher: Send + Sync {
    /// Fetch `inner_path` of `address` from EDX peers, verify it against its
    /// `b3` root, and write it into the xite's storage. `Ok(true)` when the
    /// file is present afterward; `Err` when the EDX fetch could not complete
    /// (the caller may fall back to the legacy path).
    ///
    /// This is the INTERACTIVE entry: something (usually the open page) is
    /// waiting on these bytes right now, so an implementation may race slow
    /// peers at a tight deadline.
    async fn fetch_file(&self, address: &str, inner_path: &str) -> Result<bool, String>;

    /// [`Self::fetch_file`] for work nothing is waiting on - the retention
    /// completion pass, the optional-file retry loop. Same contract; an
    /// implementation should fetch patiently rather than race slow peers
    /// (over an onion circuit a tight deadline abandons transfers that were
    /// making progress, and background work should never pay that). The
    /// default just delegates, which is fine for mocks.
    async fn fetch_file_background(&self, address: &str, inner_path: &str) -> Result<bool, String> {
        self.fetch_file(address, inner_path).await
    }

    /// [`Self::fetch_file_background`] for one file of a bulk WORKER POOL:
    /// same patient fetch, plus `fetched` fires the moment the network phase
    /// ends (object complete in the store), letting the pool reassign the
    /// slot while this call finishes the materialize copy off-pool. The
    /// default delegates and signals only on return, which is correct (if
    /// slotless) for mocks and simple implementations.
    async fn fetch_file_pooled(
        &self,
        address: &str,
        inner_path: &str,
        fetched: EdxFetchedHook,
    ) -> Result<bool, String> {
        let done = self.fetch_file_background(address, inner_path).await;
        fetched();
        done
    }

    /// Fetch a signed inner_path (content.json - the manifest, or a child
    /// content.json) of `address` from a single `peer` over an EDX link, via
    /// `GetSigned`. This is the EDX manifest channel that replaces the msgpack
    /// `getFile` for content.json: it works for any xite (the signed bytes are
    /// served independent of per-file `b3`). `Ok(Some(bytes))` on success,
    /// `Ok(None)` if the peer served no such content, `Err` on dial/link
    /// failure so the caller can score the peer and try another.
    async fn fetch_signed(
        &self,
        peer: PeerAddr,
        address: &str,
        inner_path: &str,
    ) -> Result<Option<Vec<u8>>, String>;

    /// Fetch many signed inner_paths (the child/user content.json files a
    /// user_contents xite declares) in ONE session: dial `peers` once and
    /// `GetSigned` each path over the reused links. Returns the paths that were
    /// served, mapped to their signed bytes; a path no peer had is simply
    /// absent. The EDX analog of the msgpack `fetch_files_raw` for manifests,
    /// without its per-file redial. `on_item` (if any) fires per served path
    /// the moment it lands, before the pass finishes.
    async fn fetch_signed_many(
        &self,
        address: &str,
        paths: Vec<String>,
        peers: Vec<PeerAddr>,
        on_item: Option<EdxSignedProgress>,
    ) -> HashMap<String, Vec<u8>>;

    /// Fetch just the byte range `[start, start+len)` of `inner_path` over
    /// EDX and return the verified bytes, without materializing the whole
    /// file (media seek). May return FEWER than `len` bytes: when only a
    /// contiguous prefix of the window could be fetched, that prefix is
    /// returned (the HTTP layer serves it as a shorter 206 and the browser
    /// re-requests the rest). `Ok(None)` when the file has no EDX entry;
    /// `Err` when not even the first byte of the range is available.
    async fn fetch_range(
        &self,
        address: &str,
        inner_path: &str,
        start: u64,
        len: u64,
    ) -> Result<Option<Vec<u8>>, String>;

    /// Push a signed update to a single `peer` over EDX (the `Req::Update`
    /// message: the content.json `signed` body, `modified` version, per-file
    /// update `payload` (regular-file diffs plus inline merge-record deltas),
    /// and the publisher's dial-back `sender_peers`). `Ok(payload_aware)` when
    /// the peer accepted it (newly applied or already-known); the boolean is
    /// true only when the peer advertised and handled the fast inline-payload
    /// capability. `Err` distinguishes an unreachable peer from one that
    /// answered but refused, so the caller can score reputation correctly.
    /// The impl records link and reverse-transfer activity in `progress`, so an
    /// outer UI deadline can distinguish an unreachable peer, a handshake-only
    /// stall, and a receiver that is still pulling required data.
    async fn push_update(
        &self,
        peer: PeerAddr,
        address: &str,
        inner_path: &str,
        signed: Arc<Vec<u8>>,
        modified: f64,
        payload: Arc<UpdatePayload>,
        sender_peers: Arc<Vec<String>>,
        progress: Arc<EdxPushProgress>,
    ) -> Result<bool, EdxPushError>;

    /// Fetch many files of `address` over EDX in ONE session: dial the given
    /// `peers` once and reuse the links across every file (the EDX analog of
    /// the msgpack worker pool, without its per-file redial). Returns which
    /// files landed (verified, on disk) and which EDX could not get - the
    /// exact set for the caller to hand to the msgpack worker fallback. A file
    /// with no `b3` (undeclared for EDX) comes back in `missed`.
    ///
    /// `staged` is a content.json that is verified but not yet committed to
    /// disk, and it is where the shard entries and the `order_policy` tiering
    /// are read from. A FRESH clone stages the root content.json for the whole
    /// download (it commits only once the core set is complete), so without it
    /// the fetcher finds nothing on disk and treats every file as untiered -
    /// making first-paint ordering inert on exactly the load that needs it.
    async fn fetch_files(
        &self,
        address: &str,
        want: Vec<EdxWant>,
        peers: Vec<PeerAddr>,
        staged: Option<Value>,
        on_file: Option<EdxBatchProgress>,
    ) -> EdxBatch;

    /// `listModified` over EDX (`Req::ListSigned`): the signed files of
    /// `address` changed since `since` (unix seconds), as
    /// `(inner_path, modified, size)`. Same error split as `fetch_signed`:
    /// `Err` on dial/link failure (score the peer, try another), `Ok(None)`
    /// when the peer is alive but served no list.
    async fn list_signed(
        &self,
        peer: PeerAddr,
        address: &str,
        since: u64,
    ) -> Result<Option<Vec<(String, u64, u64)>>, String>;

    /// Peer exchange over EDX (`Req::Pex`): send the peers we already know
    /// of `address`, get back up to `need` we lack plus the peer's own
    /// reachable overlay addresses.
    async fn pex(
        &self,
        peer: PeerAddr,
        address: &str,
        need: u32,
        have: Vec<PeerAddr>,
    ) -> Result<Vec<PeerAddr>, String>;

    /// The peer's working tracker set over EDX (`Req::GetTrackers`), the
    /// Beacon gossip source.
    async fn get_trackers(&self, peer: PeerAddr) -> Result<Vec<String>, String>;

    /// One Kademlia RPC over EDX (`Req::Kad`). The payload is opaque here -
    /// `epix-dht-net` owns both encode and decode.
    async fn kad(&self, peer: PeerAddr, payload: Vec<u8>) -> Result<Vec<u8>, String>;

    /// One tracker announce over EDX (`Req::Announce`). The payload is
    /// opaque here - `epix-discovery` owns both encode and decode.
    async fn announce(&self, peer: PeerAddr, payload: Vec<u8>) -> Result<Vec<u8>, String>;

    /// Store-and-forward hints after the `after` cursor over EDX
    /// (`Req::UpdatesSince`): `(xite, modified)` pairs plus the peer's current
    /// head, which the caller keeps as its next cursor.
    async fn updates_since(
        &self,
        peer: PeerAddr,
        after: u64,
    ) -> Result<(Vec<(String, i64)>, u64), String>;

    /// Live transfer telemetry for one file: which peers are serving it,
    /// at what rate, what is in flight and what failed. `Value::Null` when
    /// the file has no EDX entry or nothing has been fetched for it in this
    /// node's lifetime. Read-only and cheap - it is polled by a player's
    /// stats panel about once a second.
    ///
    /// `offset`, when given, is where the caller is reading from (a play
    /// head); the reply then also carries how many contiguous bytes past it
    /// the node already holds.
    async fn transfer_stats(
        &self,
        _address: &str,
        _inner_path: &str,
        _offset: Option<u64>,
    ) -> Value {
        Value::Null
    }
}

/// Carries tracker announces over EDX. `epix-discovery` owns the announce
/// payload but no link, so it takes this seam; the fetcher is captured for the
/// whole announce round rather than re-read per tracker.
struct EdxAnnounceSender {
    fetcher: Arc<dyn EdxFetcher>,
}

#[async_trait::async_trait]
impl epix_discovery::AnnounceSender for EdxAnnounceSender {
    async fn send(&self, tracker: &PeerAddr, payload: Vec<u8>) -> Result<Vec<u8>, String> {
        self.fetcher.announce(tracker.clone(), payload).await
    }
}

/// One file to fetch in a batch. `id`/`size`, when set, let a caller that has
/// already resolved the object pass it directly - notably a resync, whose new
/// content.json is staged but not yet committed, so the committed manifest
/// would resolve the OLD `b3`. When absent they resolve from the committed
/// content.json (root or governing child).
#[derive(Clone)]
pub struct EdxMaterializeAuthority {
    inner_path: String,
    id: epix_blob::ObjId,
    lease: Arc<ManifestLease>,
}

impl EdxMaterializeAuthority {
    fn staged(transaction: &ManifestTransaction, inner_path: &str, id: epix_blob::ObjId) -> Self {
        Self {
            inner_path: inner_path.to_string(),
        id,
            lease: transaction.lease.clone(),
        }
    }

    fn matches(
        &self, storage: &XiteStorage, inner_path: &str, id: epix_blob::ObjId) -> bool {
        self.lease.storage_root == storage.root() && self.inner_path == inner_path && self.id == id
    }
}

struct ManifestLease {
    canonical: String,
    storage_root: PathBuf,
    governing: String,
    modified: f64,
    digest: epix_blob::ObjId,
    signed: Arc<Vec<u8>>,
    content: Value,
    mode: ManifestTransactionMode,
    stage_root: PathBuf,
    cleanup: std::sync::Mutex<ManifestCleanup>,
    guard: std::sync::Mutex<Option<ManifestGuard>>,
}

/// Global Store-activation read authority plus the per-manifest mutex. The
/// activation guard is outermost, so Store exposure can take the write side
/// and observe a quiescent, complete xite registry and filesystem snapshot.
struct ManifestGuard {
    _activation: Option<tokio::sync::OwnedRwLockReadGuard<()>>,
    _manifest: Option<tokio::sync::OwnedMutexGuard<()>>,
}

/// Owned activation authority transferred to a detached completion task.
/// Dropping the caller's JoinHandle must not release the barrier while a
/// blocking Store mutation is still running.
enum StoreActivationGuard {
    Read(tokio::sync::OwnedRwLockReadGuard<()>),
    Write(tokio::sync::OwnedRwLockWriteGuard<()>),
}

impl StoreActivationGuard {
    fn assert_held(&self) {
        match self {
            Self::Read(guard) => {
                let _ = &**guard;
            }
            Self::Write(guard) => {
                let _ = &**guard;
            }
        }
    }
}

#[cfg(test)]
impl From<tokio::sync::OwnedMutexGuard<()>> for ManifestGuard {
    fn from(manifest: tokio::sync::OwnedMutexGuard<()>) -> Self {
        Self {
            _activation: None,
            _manifest: Some(manifest),
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ManifestTransactionMode {
    /// A newer root or child. Its required bytes remain private until the
    /// whole signed unit can replace the committed one atomically.
    CandidateStaged,
    /// The signed unit is already committed. Missing-file repair may write the
    /// final declared path while this lease owns its manifest transaction.
    CommittedRepair,
    /// A clone with no committed root has no previous bytes to preserve. It
    /// stays direct so the node clone loop can observe `files_needed()`.
    FreshClone,
}

#[derive(Clone)]
struct StagedMaterialization {
    inner_path: String,
    staged_inner: String,
    staged_path: PathBuf,
    object: Option<(Arc<epix_blob::store::Store>, epix_blob::ObjId)>,
    /// Exact bytes expected for a locally staged file that is not an EDX
    /// object. This also gives crash recovery an authenticated candidate
    /// digest for auxiliary files, such as a bigfile piecemap.
    recovery_id: Option<epix_blob::ObjId>,
    merge_records: bool,
}

