        let address = epix_crypt::privatekey_to_address(privatekey).unwrap();
        let mut parent = json!({
            "address": address,
            "inner_path": "data/users/content.json",
            "modified": 1.0,
            "files": {},
            "user_contents": { "permissions": {}, "cert_signers": {} },
        });
