    #[tokio::test]
    async fn recovery_signer_resolution_failure_retains_authority_state() {
        let dir = tempdir().unwrap();
        let root_key = epix_crypt::new_seed();
        let child_key = epix_crypt::new_seed();
        let canonical = epix_crypt::privatekey_to_address(&root_key).unwrap();
        let storage = XiteStorage::new(dir.path().join("data").join(&canonical));
        let governing = "child/content.json";
        let mut child = json!({
            "address": canonical,
            "inner_path": governing,
            "modified": 2.0,
            "files": {},
        });
        epix_content::sign(&mut child, &child_key).unwrap();
        let child_bytes = serde_json::to_vec(&child).unwrap();
        let mut root = json!({
            "address": canonical,
            "files": {},
            "includes": {
                governing: { "signers": ["recovery-outage.epix"] },
            },
        });
        epix_content::sign(&mut root, &root_key).unwrap();
        let old_manifest_backup = dir.path().join("old-content.backup");
        std::fs::write(&old_manifest_backup, &child_bytes).unwrap();
        let plan = PromotionRecoveryPlan {
            stage_root: dir.path().join("stage"),
            journal_path: dir.path().join("promotion.json"),
            old_manifest_backup,
            governing: governing.to_string(),
            governing_path: storage.path(governing).unwrap(),
            phase: PromotionJournalPhase::Prepared,
            candidate_digest: epix_blob::ObjId::of(b"candidate"),
            old_manifest_digest: Some(epix_blob::ObjId::of(&child_bytes)),
            files: Vec::new(),
            archives: Vec::new(),
            archive_prune_dirs: Vec::new(),
        };
        let verified = HashMap::from([("content.json".to_string(), root)]);
        *PROMOTION_RECOVERY_XID_FAIL_ONCE
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) =
            Some("recovery-outage.epix".to_string());

        let error = verified_parent_still_authorizes(
            &canonical,
            &storage,
            &plan,
            &verified,
            Some(&child_bytes),
        )
        .await
        .err()
        .expect("checked resolution failed");
        assert!(error.contains("injected recovery signer resolution failure"), "{error}");
    }

    #[tokio::test]
    async fn later_parent_removal_does_not_resurrect_committed_child_journal() {
        for (keep_child_manifest, leave_unknown_child) in
            [(false, false), (true, false), (true, true)]
        {
        let dir = tempdir().unwrap();
        let private_key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&private_key).unwrap();
        let storage = XiteStorage::new(dir.path().join("data").join(&address));
        let mut root_v1 = json!({
            "address": address,
            "modified": 1.0,
            "files": {},
            "includes": { "child/content.json": {} },
        });
        epix_content::sign(&mut root_v1, &private_key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root_v1).unwrap())
            .unwrap();
        let old_file = b"old child".to_vec();
        let new_file = b"new child".to_vec();
        let mut child_v1 = json!({
            "address": address,
            "modified": 2.0,
            "files": { "asset.bin": {
                "size": old_file.len(),
                "sha512": XiteStorage::hash_bytes(&old_file),
            } },
        });
        epix_content::sign(&mut child_v1, &private_key).unwrap();
        let mut child_v2 = json!({
            "address": address,
            "modified": 3.0,
            "files": { "asset.bin": {
                "size": new_file.len(),
                "sha512": XiteStorage::hash_bytes(&new_file),
            } },
        });
        epix_content::sign(&mut child_v2, &private_key).unwrap();
        storage.write("child/asset.bin", &old_file).unwrap();
        storage
            .write("child/content.json", &serde_json::to_vec(&child_v1).unwrap())
            .unwrap();
        let staging_state = AppState::new("test");
        let guard = staging_state
            .acquire_manifest_guard(&address, "child/content.json")
            .await
            .unwrap();
        let child_v2_bytes = serde_json::to_vec(&child_v2).unwrap();
        let transaction = AppState::bind_manifest_transaction(
            &storage,
            &address,
            "child/content.json",
            &child_v2_bytes,
            guard,
        )
        .unwrap();
        let staged_inner = transaction
            .lease
            .register_staged(&storage, "child/asset.bin", None)
            .unwrap();
        XiteStorage::new(transaction.lease.stage_root.clone())
            .write(&staged_inner, &new_file)
            .unwrap();
        let mut promotion = AppState::begin_staged_promotion(
            &storage,
            &transaction,
            &[],
            &[],
            None,
        )
        .unwrap();
        promotion.apply().unwrap();
        storage
            .write_atomic("child/content.json", &child_v2_bytes)
            .unwrap();
        promotion
            .mark_manifest_committed(&storage.path("child/content.json").unwrap())
            .unwrap();
        let journal_path = promotion.journal_path.clone();
        transaction.lease.disarm_cleanup();
        drop(promotion);
        drop(transaction);

        let mut root_v3 = json!({
            "address": address,
            "modified": 4.0,
            "files": {},
        });
        if !leave_unknown_child {
            root_v3["user_contents"] = json!({
                "permissions": { "child": { "max_size": 1 } },
                "archived_before": 2.0,
            });
        }
        epix_content::sign(&mut root_v3, &private_key).unwrap();
        storage
            .write_atomic("content.json", &serde_json::to_vec(&root_v3).unwrap())
            .unwrap();
        if !keep_child_manifest {
            storage.delete("child/content.json").unwrap();
        } else if leave_unknown_child {
            let mut unknown = json!({
                "address": address,
                "modified": 5.0,
                "files": {},
            });
            epix_content::sign(&mut unknown, &private_key).unwrap();
            storage
                .write_atomic("child/content.json", &serde_json::to_vec(&unknown).unwrap())
                .unwrap();
        }
        storage.delete("child/asset.bin").unwrap();
        let expected_child = keep_child_manifest.then(|| {
            storage.read("child/content.json").unwrap()
        });

        let state = AppState::new("test");
        state
            .add_xite(
                &address,
                XiteEntry {
                    storage: storage.clone(),
                    content: Some(root_v3),
                },
            )
            .await;
        assert!(state.has_xite(&address).await);
        assert_eq!(storage.read("child/content.json").ok(), expected_child);
        assert!(!storage.exists("child/asset.bin"));
        assert!(journal_path.is_file());
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                dir.path().join("store"),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().join("data")),
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        state.set_edx_store(store).await.unwrap();
        assert_eq!(storage.read("child/content.json").ok(), expected_child);
        assert!(!storage.exists("child/asset.bin"));
        assert!(!journal_path.exists());
        }
    }

