    #[tokio::test]
    async fn rollback_sync_failure_retains_recovery_metadata() {
        let dir = tempdir().unwrap();
        let key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&key).unwrap();
        let storage = XiteStorage::new(dir.path().join("data").join(&address));
        let mut old = json!({ "address": address, "modified": 1.0, "files": {} });
        epix_content::sign(&mut old, &key).unwrap();
        let old_bytes = serde_json::to_vec(&old).unwrap();
        storage.write("content.json", &old_bytes).unwrap();
        let mut candidate = json!({ "address": address, "modified": 2.0, "files": {} });
        epix_content::sign(&mut candidate, &key).unwrap();
        let candidate_bytes = serde_json::to_vec(&candidate).unwrap();
        let state = AppState::new("test");
        let guard = state
            .acquire_manifest_guard(&address, "content.json")
            .await
            .unwrap();
        let transaction = AppState::bind_manifest_transaction(
            &storage,
            &address,
            "content.json",
            &candidate_bytes,
            guard,
        )
        .unwrap();
        let mut promotion =
            AppState::begin_staged_promotion(&storage, &transaction, &[], &[], None).unwrap();
        promotion.apply().unwrap();
        storage.write_atomic("content.json", &candidate_bytes).unwrap();
        let governing_path = storage.path("content.json").unwrap();
        *PROMOTION_ROLLBACK_SYNC_FAIL_ONCE
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(governing_path);
        let error = promotion.rollback(&storage, "content.json").unwrap_err();
        assert!(error.contains("injected rollback manifest sync failure"), "{error}");
        assert_eq!(storage.read("content.json").unwrap(), old_bytes);
        assert!(promotion.old_manifest_backup.is_file());
        assert!(promotion.journal_path.is_file());
    }

    #[tokio::test]
    async fn cleanup_failure_retains_journal_and_recovery_retries_it() {
        let dir = tempdir().unwrap();
        let private_key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&private_key).unwrap();
        let storage = XiteStorage::new(dir.path().join("data").join(&address));
        let old_bytes = b"cleanup old".to_vec();
        let new_bytes = b"cleanup new".to_vec();
        let (_, old_signed) = signed_recovery_root(&address, &private_key, 1.0, &old_bytes);
        let (new_content, new_signed) =
            signed_recovery_root(&address, &private_key, 2.0, &new_bytes);
        storage.write("asset.bin", &old_bytes).unwrap();
        storage.write("content.json", &old_signed).unwrap();
        let staging_state = AppState::new("test");
        let guard = staging_state
            .acquire_manifest_guard(&address, "content.json")
            .await
            .unwrap();
        let transaction = AppState::bind_manifest_transaction(
            &storage,
            &address,
            "content.json",
            &new_signed,
            guard,
        )
        .unwrap();
        let staged_inner = transaction
            .lease
            .register_staged(&storage, "asset.bin", None)
            .unwrap();
        XiteStorage::new(transaction.lease.stage_root.clone())
            .write(&staged_inner, &new_bytes)
            .unwrap();
        let mut promotion = AppState::begin_staged_promotion(
            &storage,
            &transaction,
            &[],
            &[],
            None,
        )
        .unwrap();
        promotion.apply().unwrap();
        storage.write_atomic("content.json", &new_signed).unwrap();
        promotion
            .mark_manifest_committed(&storage.path("content.json").unwrap())
            .unwrap();
        let backup_path = promotion.files[0].backup_path.clone();
        let journal_path = promotion.journal_path.clone();
        *PROMOTION_CLEANUP_FAIL_ONCE
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(backup_path.clone());
        let (_, warnings, _) = promotion.finish(&transaction);
        assert!(!warnings.is_empty());
        assert!(backup_path.is_file());
        assert!(journal_path.is_file());
        drop(promotion);
        drop(transaction);

        let state = AppState::new("test");
        state
            .add_xite(
                &address,
                XiteEntry {
                    storage: storage.clone(),
                    content: Some(new_content),
                },
            )
            .await;
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                dir.path().join("store"),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().join("data")),
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        state.set_edx_store(store).await.unwrap();
        assert_eq!(storage.read("asset.bin").unwrap(), new_bytes);
        assert!(!backup_path.exists());
        assert!(!journal_path.exists());
    }

    #[tokio::test]
    async fn retry_pending_updates_commits_once_files_land() {
        // A deferred update converges: once its missing file appears on disk,
        // the retry tick commits it without needing peers or a transport.
        let dir = tempdir().unwrap();
        let key = epix_crypt::new_seed();
        let addr = epix_crypt::privatekey_to_address(&key).unwrap();
        let storage = XiteStorage::new(dir.path());

        let mut v1_content =
            json!({ "address": addr, "modified": 100.0, "title": "V1", "files": {} });
        epix_content::sign(&mut v1_content, &key).unwrap();
        let v1 = serde_json::to_vec(&v1_content).unwrap();
        storage.write("content.json", &v1).unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                &addr,
                XiteEntry {
                    storage: storage.clone(),
                    content: Some(v1_content),
                },
            )
            .await;

        let body = b"hello";
        let mut v2_content = json!({
            "address": addr, "modified": 200.0, "title": "V2",
            "files": { "a.txt": {
                "size": body.len(),
                "sha512": XiteStorage::hash_bytes(body),
            } },
        });
        epix_content::sign(&mut v2_content, &key).unwrap();
        let v2 = serde_json::to_vec(&v2_content).unwrap();
        let keys = vec![addr.clone()];
        let guard = state.merge_path_lock(&addr, "content.json").lock_owned().await;
        let transaction =
            AppState::bind_manifest_transaction(&storage, &addr, "content.json", &v2, guard)
                .unwrap();
        assert!(
            !state
                .finalize_root_update(RootFinalize {
                    keys: &keys,
                    canonical: &addr,
                    storage: &storage,
                    content: v2_content,
                    bytes: &v2,
                    failed: &["a.txt".into()],
                    transaction: &transaction,
                })
                .await
        );
        drop(transaction);
        assert_eq!(storage.read("content.json").unwrap(), v1);

        // Nothing on disk yet: the retry can't fetch (no transport) and the
        // update stays pending, still serving v1.
        state.retry_pending_updates().await;
        assert_eq!(storage.read("content.json").unwrap(), v1);
        assert_eq!(state.xite_info(&addr).await["content"]["title"], "V1");

        // The file lands (a later push, another peer, any path): the next
        // retry pass verifies the set is complete and commits.
        storage.write("a.txt", body).unwrap();
        state.retry_pending_updates().await;
        assert_eq!(storage.read("content.json").unwrap(), v2);
        assert_eq!(state.xite_info(&addr).await["content"]["title"], "V2");

        // Committed pending entries are gone: another pass is a no-op.
        state.retry_pending_updates().await;
        assert_eq!(storage.read("content.json").unwrap(), v2);
    }

    #[tokio::test]
    async fn staged_root_update_with_changed_db_input_commits() {
        // A resync stages a changed .json data file (a database input) in the
        // transaction's stage root; the live tree still holds the previous
        // version until the promotion. The commit's db snapshot must read the
        // staged copy - reading the live file failed its size check against
        // the new manifest and the update re-failed on every retry (the
        // "cannot download the new blog post" wedge).
        let dir = tempdir().unwrap();
        let key = epix_crypt::new_seed();
        let addr = epix_crypt::privatekey_to_address(&key).unwrap();
        let storage = XiteStorage::new(dir.path());

        let old_data = br#"{"post":[]}"#.to_vec();
        let new_data = br#"{"post":[{"post_id":1,"title":"new"}]}"#.to_vec();
        assert_ne!(old_data.len(), new_data.len());
        let mut v1_content = json!({
            "address": addr, "modified": 100.0, "title": "V1",
            "files": { "data/data.json": {
                "size": old_data.len(),
                "sha512": XiteStorage::hash_bytes(&old_data),
            } },
        });
        epix_content::sign(&mut v1_content, &key).unwrap();
        let v1 = serde_json::to_vec(&v1_content).unwrap();
        storage.write("content.json", &v1).unwrap();
        storage.write("data/data.json", &old_data).unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                &addr,
                XiteEntry {
                    storage: storage.clone(),
                    content: Some(v1_content),
                },
            )
            .await;

        let mut v2_content = json!({
            "address": addr, "modified": 200.0, "title": "V2",
            "files": { "data/data.json": {
                "size": new_data.len(),
                "sha512": XiteStorage::hash_bytes(&new_data),
            } },
        });
        epix_content::sign(&mut v2_content, &key).unwrap();
        let v2 = serde_json::to_vec(&v2_content).unwrap();
        let keys = vec![addr.clone()];
        let guard = state.merge_path_lock(&addr, "content.json").lock_owned().await;
        let transaction =
            AppState::bind_manifest_transaction(&storage, &addr, "content.json", &v2, guard)
                .unwrap();
        let staged_inner = transaction
            .lease
            .register_staged(&storage, "data/data.json", None)
            .unwrap();
        XiteStorage::new(transaction.lease.stage_root.clone())
            .write(&staged_inner, &new_data)
            .unwrap();

        assert!(
            state
                .finalize_root_update(RootFinalize {
                    keys: &keys,
                    canonical: &addr,
                    storage: &storage,
                    content: v2_content,
                    bytes: &v2,
                    failed: &[],
                    transaction: &transaction,
                })
                .await
        );
        drop(transaction);
        assert_eq!(storage.read("content.json").unwrap(), v2);
        assert_eq!(storage.read("data/data.json").unwrap(), new_data);
        assert_eq!(state.xite_info(&addr).await["content"]["title"], "V2");
    }

    #[tokio::test]
    async fn stale_cloned_root_retry_cannot_commit_after_guarded_newer_version() {
        let dir = tempdir().unwrap();
        let key = epix_crypt::new_seed();
        let addr = epix_crypt::privatekey_to_address(&key).unwrap();
        let storage = XiteStorage::new(dir.path());
        let mut v1_content = json!({ "address": addr, "modified": 100.0, "files": {} });
        epix_content::sign(&mut v1_content, &key).unwrap();
        let v1 = serde_json::to_vec(&v1_content).unwrap();
        storage.write("content.json", &v1).unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                &addr,
                XiteEntry {
                    storage: storage.clone(),
                    content: Some(v1_content),
                },
            )
            .await;

        let keys = vec![addr.clone()];
        let mut v2_content = json!({ "address": addr, "modified": 200.0, "files": {} });
        epix_content::sign(&mut v2_content, &key).unwrap();
        let v2 = serde_json::to_vec(&v2_content).unwrap();
        {
            let guard = state.merge_path_lock(&addr, "content.json").lock_owned().await;
            let transaction =
                AppState::bind_manifest_transaction(&storage, &addr, "content.json", &v2, guard)
                    .unwrap();
            assert!(
                !state
                    .finalize_root_update(RootFinalize {
                        keys: &keys,
                        canonical: &addr,
                        storage: &storage,
                        content: v2_content.clone(),
                        bytes: &v2,
                        failed: &["missing.bin".to_string()],
                        transaction: &transaction,
                    })
                    .await
            );
        }

        // Model a retry clone taken before a live v3 transaction. It must wait
        // on the same canonical guard rather than materializing v2 alongside
        // that transaction.
        let guard = state
            .merge_path_lock(&addr, "content.json")
            .lock_owned()
            .await;
        let retry_state = state.clone();
        let retry_keys = keys.clone();
        let retry_v2 = v2.clone();
        let retry_addr = addr.clone();
        let mut retry = tokio::spawn(async move {
            retry_state
                .retry_pending_update(&retry_keys, &retry_addr, v2_content, &retry_v2)
                .await
        });
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(25), &mut retry)
                .await
                .is_err(),
            "pending retry bypassed the live update guard"
        );

        let mut v3_content = json!({ "address": addr, "modified": 300.0, "files": {} });
        epix_content::sign(&mut v3_content, &key).unwrap();
        let v3 = serde_json::to_vec(&v3_content).unwrap();
        let transaction =
            AppState::bind_manifest_transaction(&storage, &addr, "content.json", &v3, guard)
                .unwrap();
        assert!(
            state
                .commit_root_update(&keys, &addr, &storage, v3_content, &v3, &transaction)
                .await
        );
        drop(transaction);

        assert!(!retry.await.unwrap(), "stale cloned retry must be discarded");
        assert_eq!(storage.read("content.json").unwrap(), v3);
        assert_eq!(state.xite_info(&addr).await["content"]["modified"], 300.0);
    }

    #[tokio::test]
    async fn newer_pending_root_blocks_older_and_equal_equivocating_commits() {
        let dir = tempdir().unwrap();
        let key = epix_crypt::new_seed();
        let addr = epix_crypt::privatekey_to_address(&key).unwrap();
        let storage = XiteStorage::new(dir.path());
        let mut v1_content = json!({ "address": addr, "modified": 100.0, "files": {} });
        epix_content::sign(&mut v1_content, &key).unwrap();
        let v1 = serde_json::to_vec(&v1_content).unwrap();
        storage.write("content.json", &v1).unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                &addr,
                XiteEntry { storage: storage.clone(), content: Some(v1_content) },
            )
            .await;
        let keys = vec![addr.clone()];

        let mut v3_content = json!({
            "address": addr, "modified": 300.0, "title": "first", "files": {}
        });
        epix_content::sign(&mut v3_content, &key).unwrap();
        let v3 = serde_json::to_vec(&v3_content).unwrap();
        {
            let guard = state.merge_path_lock(&addr, "content.json").lock_owned().await;
            let transaction =
                AppState::bind_manifest_transaction(&storage, &addr, "content.json", &v3, guard)
                    .unwrap();
            assert!(
                !state
                    .finalize_root_update(RootFinalize {
                        keys: &keys,
                        canonical: &addr,
                        storage: &storage,
                        content: v3_content.clone(),
                        bytes: &v3,
                        failed: &["future.bin".to_string()],
                        transaction: &transaction,
                    })
                    .await
            );
        }

        // Same modified time but different signed bytes is equivocation. The
        // first verified pending candidate stays the barrier.
        let mut v3_other_content = json!({
            "address": addr, "modified": 300.0, "title": "other", "files": {}
        });
        epix_content::sign(&mut v3_other_content, &key).unwrap();
        let v3_other = serde_json::to_vec(&v3_other_content).unwrap();
        {
            let guard = state.merge_path_lock(&addr, "content.json").lock_owned().await;
            let transaction = AppState::bind_manifest_transaction(
                &storage,
                &addr,
                "content.json",
                &v3_other,
                guard,
            )
            .unwrap();
            assert!(
                !state
                    .finalize_root_update(RootFinalize {
                        keys: &keys,
                        canonical: &addr,
                        storage: &storage,
                        content: v3_other_content,
                        bytes: &v3_other,
                        failed: &["other.bin".to_string()],
                        transaction: &transaction,
                    })
                    .await
            );
        }
        assert_eq!(state.pending_updates.lock().unwrap().get(&addr).unwrap().bytes, v3);

        let mut v2_content = json!({ "address": addr, "modified": 200.0, "files": {} });
        epix_content::sign(&mut v2_content, &key).unwrap();
        let v2 = serde_json::to_vec(&v2_content).unwrap();
        {
            let guard = state.merge_path_lock(&addr, "content.json").lock_owned().await;
            let transaction =
                AppState::bind_manifest_transaction(&storage, &addr, "content.json", &v2, guard)
                    .unwrap();
            assert!(
                !state
                    .commit_root_update(
                        &keys,
                        &addr,
                        &storage,
                        v2_content,
                        &v2,
                        &transaction,
                    )
                    .await
            );
        }
        assert_eq!(storage.read("content.json").unwrap(), v1);
        assert_eq!(state.pending_updates.lock().unwrap().get(&addr).unwrap().bytes, v3);

        let guard = state.merge_path_lock(&addr, "content.json").lock_owned().await;
        let transaction =
            AppState::bind_manifest_transaction(&storage, &addr, "content.json", &v3, guard)
                .unwrap();
        assert!(
            state
                .commit_root_update(&keys, &addr, &storage, v3_content, &v3, &transaction)
                .await
        );
        assert_eq!(storage.read("content.json").unwrap(), v3);
        assert!(!state.pending_updates.lock().unwrap().contains_key(&addr));
    }

    #[tokio::test]
    async fn stale_resync_waiting_on_root_guard_cannot_replace_a_newer_push() {
        let dir = tempdir().unwrap();
        let key = epix_crypt::new_seed();
        let addr = epix_crypt::privatekey_to_address(&key).unwrap();
        let storage = XiteStorage::new(dir.path());
        let mut v1_content = json!({
            "address": addr.clone(), "modified": 100.0, "title": "V1", "files": {}
        });
        epix_content::sign(&mut v1_content, &key).unwrap();
        let v1 = serde_json::to_vec(&v1_content).unwrap();
        storage.write("content.json", &v1).unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                &addr,
                XiteEntry { storage: storage.clone(), content: Some(v1_content),
                },
            )
            .await;

        let mut v2_content = json!({
            "address": addr.clone(), "modified": 200.0, "title": "V2", "files": {}
        });
        epix_content::sign(&mut v2_content, &key).unwrap();
        let v2 = serde_json::to_vec(&v2_content).unwrap();

        // Model the root transaction held by a live v3 push. A resync that
        // selected v2 earlier must wait at the same guard, then compare again
        // after the v3 transaction has made its candidate stale.
        let guard = state
            .merge_path_lock(&addr, "content.json")
            .lock_owned()
            .await;
        let resync_state = state.clone();
        let resync_addr = addr.clone();
        let resync_storage = storage.clone();
        let mut resync = tokio::spawn(async move {
            resync_state
                .resync_apply_newer(
                    &resync_addr,
                    &resync_addr,
                    &resync_storage,
                    v2,
                    Vec::new())
                .await
        });
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(25), &mut resync)
                .await
                .is_err(),
            "resync bypassed the canonical root transaction"
        );

        let marker = b"v3 file";
        storage.write("marker.bin", marker).unwrap();
        let mut v3_content = json!({
            "address": addr.clone(),
            "modified": 300.0,
            "title": "V3",
            "files": {
                "marker.bin": {
                    "size": marker.len(),
                    "sha512": XiteStorage::hash_bytes(marker),
                }
            },
        });
        epix_content::sign(&mut v3_content, &key).unwrap();
        let v3 = serde_json::to_vec(&v3_content).unwrap();
        let transaction =
            AppState::bind_manifest_transaction(&storage, &addr, "content.json", &v3, guard)
                .unwrap();
        assert!(
            state
                .commit_root_update(
                    &[addr.clone()],
                    &addr,
                    &storage,
                    v3_content,
                    &v3,
                    &transaction,
                )
                .await
        );
        drop(transaction);

        assert_eq!(resync.await.unwrap(), Ok(false));
        assert_eq!(storage.read("content.json").unwrap(), v3);
        assert_eq!(storage.read("marker.bin").unwrap(), marker);
        assert_eq!(state.xite_info(&addr).await["content"]["title"], "V3");
    }

    #[tokio::test]
    async fn xite_info_is_real_not_stubbed() {
        let dir = tempdir().unwrap();
        let addr = "1HeLLo4uzjaLetFx6NH3PMwFP3qbRbTf3D";
        let state = AppState::new("test");
        state
            .add_xite(addr, XiteEntry { storage: XiteStorage::new(dir.path()), content: Some(sample_content()),
                },
            )
            .await;

        let info = state.xite_info(addr).await;

        // Real address hash = sha256(address).
        assert_eq!(
            info["address_hash"].as_str().unwrap(),
            hex::encode(Sha256::digest(addr.as_bytes()))
        );
        // Real derived identity.
        assert!(info["auth_address"].as_str().unwrap().starts_with("epix1"));
        // No cert selected: the user directory is the bare auth address
        // (EpixNet's getUserDirectory; an xid cert would make it <name>.epix).
        assert_eq!(info["xid_directory"], info["auth_address"]);

        // Real stats from content.json.
        assert_eq!(info["settings"]["size"], 350);
        assert_eq!(info["settings"]["size_optional"], 9000);
        assert_eq!(info["content_updated"], 1777992697.0);
        // A freshly served xite holds no permissions until the user grants one.
        assert!(info["settings"]["permissions"].as_array().unwrap().is_empty());

        // content.json summarized: counts, signs stripped, title kept.
        assert_eq!(info["content"]["files"], 2);
        assert_eq!(info["content"]["files_optional"], 1);
        assert_eq!(info["content"]["includes"], 1);
        assert_eq!(info["content"]["title"], "Test Xite");
        assert!(info["content"].get("sign").is_none());
        assert!(info["content"].get("signs").is_none());

        // The default limit matches the python client's --size-limit (1000 MB,
        // not EpixNet's old 10) - a growing xite must not stall at 10 MB.
        assert_eq!(info["size_limit"], DEFAULT_SIZE_LIMIT_MB);
        assert_eq!(info["next_size_limit"], 10);
    }

    #[tokio::test]
    async fn xite_list_returns_one_entry_per_xite_collapsing_aliases() {
        let dir = tempdir().unwrap();
        let state = AppState::new("test");
        // Same signed content served under a raw address and a `.epix` alias.
        let content = json!({ "address": "1HeLLo", "modified": 1.0, "files": {}, "signs": {"1HeLLo": "x"} });
        state
            .add_xite("1HeLLo", XiteEntry { storage: XiteStorage::new(dir.path().join("hello")), content: Some(content.clone()),
                },
            )
            .await;
        state
            .add_xite("hello.epix", XiteEntry { storage: XiteStorage::new(dir.path().join("hello")), content: Some(content),
                },
            )
            .await;
        // A second, distinct xite. It needs its own storage root: two
        // different xites sharing one root are refused (only aliases of the
        // same xite may share).
        let other = json!({ "address": "1Other", "modified": 1.0, "files": {}, "signs": {"1Other": "x"} });
        state
            .add_xite("1Other", XiteEntry { storage: XiteStorage::new(dir.path().join("other")), content: Some(other),
                },
            )
            .await;

        let list = state.xite_list().await;
        assert_eq!(list.len(), 2, "alias collapses; two distinct sites remain");
        let addrs: std::collections::HashSet<_> =
            list.iter().map(|s| s["content"]["address"].as_str().unwrap()).collect();
        assert!(addrs.contains("1HeLLo"));
        assert!(addrs.contains("1Other"));
    }

    #[tokio::test]
    async fn db_directory_is_relative_to_the_db_file_dir() {
        // A user_contents-style layout: db under data/users/, per-user data at
        // data/users/<name>/data.json. json.directory must be `<name>`, not
        // `data/users/<name>` (EpixNet computes it relative to the db file).
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        storage
            .write(
                "dbschema.json",
                br#"{ "db_name":"Talk","db_file":"data/users/talk.db","version":2,
                     "maps": { ".+/data.json": { "to_table": [{"node":"topic","table":"topic"}] } },
                     "tables": { "topic": { "cols": [["topic_id","INTEGER"],["title","TEXT"],["json_id","INTEGER"]] } } }"#,
            )
            .unwrap();
        storage
            .write(
                "data/users/dice.epix/data.json",
                br#"{ "topic": [ {"topic_id":1,"title":"Hi"} ] }"#,
            )
            .unwrap();
        let key = epix_crypt::new_seed();
        let addr = epix_crypt::privatekey_to_address(&key).unwrap();
        let schema = storage.read("dbschema.json").unwrap();
        let data = storage.read("data/users/dice.epix/data.json").unwrap();
        let mut content = json!({
            "address": addr,
            "modified": 1.0,
            "files": {
                "dbschema.json": {
                    "size": schema.len(), "sha512": XiteStorage::hash_bytes(&schema)
                },
                "data/users/dice.epix/data.json": {
                    "size": data.len(), "sha512": XiteStorage::hash_bytes(&data)
                }
            }
        });
        epix_content::sign(&mut content, &key).unwrap();
        storage
            .write("content.json", epix_content::dumps_content(&content).as_bytes())
            .unwrap();
        let state = AppState::new("test");
        state.add_xite(&addr, XiteEntry { storage, content: Some(content),
                },
            ).await;

        let rows = state
            .db_query(&addr, "SELECT directory FROM json", &Value::Null)
            .await
            .unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0]["directory"], "dice.epix", "directory relative to db file dir");

        // The topic still populated (path matched relative to the db dir).
        let topics = state
            .db_query(&addr, "SELECT title FROM topic", &Value::Null)
            .await
            .unwrap();
        assert_eq!(topics[0]["title"], "Hi");
    }

    #[tokio::test]
    async fn db_query_returns_real_rows_from_the_xite_db() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        storage
            .write(
                "dbschema.json",
                br#"{ "db_name":"Blog","db_file":"db.db","version":2,
                     "maps": { "data/.*/data.json": { "to_table": [{"node":"posts","table":"post"}] } },
                     "tables": { "post": { "cols": [["post_id","INTEGER"],["title","TEXT"],["json_id","INTEGER"]] } } }"#,
            )
            .unwrap();
        storage
            .write(
                "data/alice/data.json",
                br#"{ "posts": [ {"post_id":1,"title":"Hello"}, {"post_id":2,"title":"World"} ] }"#,
            )
            .unwrap();

        let key = epix_crypt::new_seed();
        let addr = epix_crypt::privatekey_to_address(&key).unwrap();
        let schema = storage.read("dbschema.json").unwrap();
        let data = storage.read("data/alice/data.json").unwrap();
        let mut content = json!({
            "address": addr,
            "modified": 1.0,
            "files": {
                "dbschema.json": {
                    "size": schema.len(), "sha512": XiteStorage::hash_bytes(&schema)
                },
                "data/alice/data.json": {
                    "size": data.len(), "sha512": XiteStorage::hash_bytes(&data)
                }
            }
        });
        epix_content::sign(&mut content, &key).unwrap();
        storage
            .write("content.json", epix_content::dumps_content(&content).as_bytes())
            .unwrap();
        let state = AppState::new("test");
        state.add_xite(&addr, XiteEntry { storage, content: Some(content),
                },
            ).await;

        let rows = state
            .db_query(&addr, "SELECT post_id, title FROM post ORDER BY post_id", &Value::Null,
            )
            .await
            .unwrap();
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0]["title"], "Hello");
        assert_eq!(rows[1]["post_id"], 2);

        // Named params bind.
        let one = state
            .db_query(&addr, "SELECT title FROM post WHERE post_id = :id", &json!({"id": 2}),
            )
            .await
            .unwrap();
        assert_eq!(one[0]["title"], "World");
    }

    #[tokio::test]
    async fn rebuild_xite_db_excludes_rows_from_a_revoked_stale_child() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&key).unwrap();
        let schema = br#"{ "db_name":"Blog","db_file":"db.db","version":2,
            "maps": { "data/users/.+/data.json": {
                "to_table": [{"node":"posts","table":"post"}] } },
            "tables": { "post": { "cols": [
                ["post_id","INTEGER"],["title","TEXT"],["json_id","INTEGER"]] } } }"#;
        let data = br#"{ "posts": [ {"post_id":1,"title":"revoked"} ] }"#;
        let child_path = "data/users/alice/content.json";
        storage.write("dbschema.json", schema).unwrap();
        storage.write("data/users/alice/data.json", data).unwrap();
        let mut child = json!({
            "address": address,
            "inner_path": child_path,
            "modified": 1.0,
            "files": { "data.json": {
                "size": data.len(),
                "sha512": XiteStorage::hash_bytes(data),
            } }
        });
        epix_content::sign(&mut child, &key).unwrap();
        storage
            .write(child_path, epix_content::dumps_content(&child).as_bytes())
            .unwrap();
        let schema_entry = json!({
            "size": schema.len(),
            "sha512": XiteStorage::hash_bytes(schema),
        });
        let mut root_v1 = json!({
            "address": address,
            "modified": 1.0,
            "files": { "dbschema.json": schema_entry.clone() },
            "includes": { (child_path): {
                "signers": [address], "signers_required": 1
            } }
        });
        epix_content::sign(&mut root_v1, &key).unwrap();
        storage
            .write("content.json", epix_content::dumps_content(&root_v1).as_bytes())
            .unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                &address,
                XiteEntry {
                    storage: storage.clone(),
                    content: Some(root_v1),
                },
            )
            .await;
        let rows = state
            .db_query(&address, "SELECT title FROM post", &Value::Null)
            .await
            .unwrap();
        assert_eq!(rows.len(), 1);

        let mut root_v2 = json!({
            "address": address,
            "modified": 2.0,
            "files": { "dbschema.json": schema_entry },
        });
        epix_content::sign(&mut root_v2, &key).unwrap();
        storage
            .write("content.json", epix_content::dumps_content(&root_v2).as_bytes())
            .unwrap();
        state.update_content(&address, Some(root_v2)).await;
        assert!(storage.exists(child_path));
        assert!(storage.exists("data/users/alice/data.json"));
        assert!(state.rebuild_xite_db(&address).await);

        let rows = state
            .db_query(&address, "SELECT title FROM post", &Value::Null)
            .await
            .unwrap();
        assert!(rows.is_empty(), "revoked child rows survived the verified rebuild");
        state
            .ingest_file_from(&address, "data/users/alice/data.json", None)
            .await;
        let rows = state
            .db_query(&address, "SELECT title FROM post", &Value::Null)
            .await
            .unwrap();
        assert!(rows.is_empty(), "stale ingest reinserted a revoked child row");
    }

