    #[tokio::test]
    async fn store_barrier_never_registers_a_corrupt_child_manifest() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path().join("xite"));
        let owner_key = epix_crypt::new_seed();
        let wrong_key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&owner_key).unwrap();
        let payload = vec![0x45; 200 * 1024];
        let id = epix_blob::ObjId::of(&payload);
        storage.write("child/payload.bin", &payload).unwrap();
        let mut root = json!({
            "address": address,
            "modified": 1.0,
            "files": {},
            "includes": { "child/content.json": {} },
        });
        epix_content::sign(&mut root, &owner_key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root).unwrap())
            .unwrap();
        let mut corrupt_child = json!({
            "address": address,
            "inner_path": "child/content.json",
            "modified": 2.0,
            "files": {
                "payload.bin": {
                    "size": payload.len(),
                    "sha512": XiteStorage::hash_bytes(&payload),
                    "b3": id.to_string(),
                }
            },
        });
        epix_content::sign(&mut corrupt_child, &wrong_key).unwrap();
        storage
            .write(
                "child/content.json",
                &serde_json::to_vec(&corrupt_child).unwrap(),
            )
            .unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                address.clone(),
                XiteEntry { storage: storage.clone(), content: Some(root) },
            )
            .await;
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                dir.path().join("store"),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().to_path_buf()),
                    ..Default::default()
                },
            )
            .unwrap(),
        );

        let tally = state.set_edx_store(store.clone()).await.unwrap();
        assert_eq!(tally.xites, 1);
        assert!(
            !store.contains(id).unwrap(),
            "parseable bytes from an unverified child entered the Store"
        );
        assert!(state.edx_object_path(&id).is_none());
    }

    #[tokio::test]
    async fn store_barrier_reconciles_a_dangling_extern_then_registers_live_owner() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path().join("xite"));
        let owner_key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&owner_key).unwrap();
        let payload = vec![0x58; 200 * 1024];
        let id = epix_blob::ObjId::of(&payload);
        storage.write("live.bin", &payload).unwrap();
        storage.write("stale.bin", &payload).unwrap();
        let mut root = json!({
            "address": address,
            "modified": 1.0,
            "files": {
                "live.bin": {
                    "size": payload.len(),
                    "sha512": XiteStorage::hash_bytes(&payload),
                    "b3": id.to_string(),
                }
            },
        });
        epix_content::sign(&mut root, &owner_key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root).unwrap())
            .unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                address.clone(),
                XiteEntry { storage: storage.clone(), content: Some(root) },
            )
            .await;
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                dir.path().join("store"),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().to_path_buf()),
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        let stale = storage.path("stale.bin").unwrap();
        store
            .adopt_extern(id, epix_blob::Ns::Plain, &stale, 1)
            .unwrap();
        storage.delete("stale.bin").unwrap();

        let tally = state.set_edx_store(store.clone()).await.unwrap();
        assert_eq!(tally.registered, 1);
        assert!(store.is_complete(id).unwrap());
        let entries = store.extern_entries().unwrap();
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].path, storage.path("live.bin").unwrap());
        assert_eq!(store.ref_delta(id, 0).unwrap(), 1, "live declarations stay pinned");
    }

    #[tokio::test]
    async fn store_barrier_retires_an_extern_from_an_unloaded_xite() {
        let dir = tempdir().unwrap();
        let stale = dir.path().join("data/stale/file.bin");
        std::fs::create_dir_all(stale.parent().unwrap()).unwrap();
        let bytes = vec![0x31; 200 * 1024];
        std::fs::write(&stale, &bytes).unwrap();
        let id = epix_blob::ObjId::of(&bytes);
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                dir.path().join("store"),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().join("data")),
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        store
            .adopt_extern(id, epix_blob::Ns::Plain, &stale, 1)
            .unwrap();
        let state = AppState::new("test");

        let tally = state.set_edx_store(store.clone()).await.unwrap();
        assert_eq!(tally.xites, 0);
        assert!(!store.contains(id).unwrap());
        assert!(stale.exists(), "Store retirement deleted caller-owned xite bytes");
    }

    #[tokio::test]
    async fn corrupt_xite_is_quarantined_without_blocking_store_exposure() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path().join("xite"));
        let owner_key = epix_crypt::new_seed();
        let wrong_key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&owner_key).unwrap();
        let mut corrupt_root = json!({
            "address": address,
            "modified": 1.0,
            "files": {},
        });
        epix_content::sign(&mut corrupt_root, &wrong_key).unwrap();
        storage
            .write(
                "content.json",
                &serde_json::to_vec(&corrupt_root).unwrap(),
            )
            .unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                address.clone(),
                XiteEntry { storage, content: Some(corrupt_root) },
            )
            .await;
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                dir.path().join("store"),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().to_path_buf()),
                    ..Default::default()
                },
            )
            .unwrap(),
        );

        // A single unverifiable xite must not take Store activation (and with
        // it every other xite's serving and all local mutation) down: it is
        // QUARANTINED instead - counted, unregistered, and left with no
        // verified indexes so nothing serves for it - while the Store is
        // still exposed. (A store-wide failure still fails closed.)
        let tally = state.set_edx_store(store.clone()).await.unwrap();
        assert_eq!(tally.quarantined, 1);
        assert_eq!(tally.xites, 0, "the quarantined xite is not verified or registered");
        assert_eq!(tally.registered, 0);
        assert!(
            state
                .edx_store()
                .await
                .as_ref()
                .is_some_and(|current| Arc::ptr_eq(current, &store)),
            "activation with a quarantined xite still exposes the Store"
        );
        assert!(
            state
                .verified_manifest_contents
                .read()
                .unwrap()
                .get(&address)
                .is_none(),
            "no verified authority remains installed for the quarantined xite"
        );
    }

    #[tokio::test]
    async fn store_barrier_serializes_a_xite_added_after_activation_starts() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path().join("xite"));
        let key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&key).unwrap();
        let bytes = vec![0x56; 64 * 1024];
        let id = epix_blob::ObjId::of(&bytes);
        storage.write("asset.bin", &bytes).unwrap();
        let mut content = json!({
            "address": address,
            "modified": 1.0,
            "files": { "asset.bin": {
                "size": bytes.len(),
                "sha512": XiteStorage::hash_bytes(&bytes),
                "b3": id.to_string(),
            } },
        });
        epix_content::sign(&mut content, &key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&content).unwrap())
            .unwrap();
        let state = AppState::new("test");
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                dir.path().join("store"),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().to_path_buf()),
                    ..Default::default()
                },
            )
            .unwrap(),
        );

        let initial_reader = state.xite_activation_gate.clone().read_owned().await;
        let barrier_state = state.clone();
        let barrier_store = store.clone();
        let barrier = tokio::spawn(async move {
            barrier_state.set_edx_store(barrier_store).await
        });
        tokio::task::yield_now().await;
        let add_state = state.clone();
        let add_address = address.clone();
        let add_storage = storage.clone();
        let add_content = content.clone();
        let add = tokio::spawn(async move {
            add_state
                .add_xite(
                    &add_address,
                    XiteEntry {
                        storage: add_storage,
                        content: Some(add_content),
                    },
                )
                .await;
        });
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        assert!(!barrier.is_finished(), "barrier bypassed the active reader");
        assert!(!add.is_finished(), "xite addition bypassed the queued barrier writer");
        drop(initial_reader);

        barrier.await.unwrap().unwrap();
        add.await.unwrap();
        assert!(store.contains(id).unwrap());
        assert!(store.is_complete(id).unwrap());
        assert_eq!(
            state.edx_object_path(&id),
            Some((address, "asset.bin".to_string()))
        );
    }

    #[tokio::test]
    async fn store_barrier_serializes_a_root_sign_and_registers_its_new_object() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path().join("xite"));
        let key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&key).unwrap();
        let bytes = vec![0x44; 64 * 1024];
        let id = epix_blob::ObjId::of(&bytes);
        storage.write("asset.bin", &bytes).unwrap();
        let mut content = json!({
            "address": address,
            "modified": 1.0,
            "files": { "asset.bin": {
                "size": bytes.len(),
                "sha512": XiteStorage::hash_bytes(&bytes),
            } },
        });
        epix_content::sign(&mut content, &key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&content).unwrap())
            .unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                &address,
                XiteEntry {
                    storage: storage.clone(),
                    content: Some(content),
                },
            )
            .await;
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                dir.path().join("store"),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().to_path_buf()),
                    ..Default::default()
                },
            )
            .unwrap(),
        );

        let initial_reader = state.xite_activation_gate.clone().read_owned().await;
        let barrier_state = state.clone();
        let barrier_store = store.clone();
        let barrier = tokio::spawn(async move {
            barrier_state.set_edx_store(barrier_store).await
        });
        tokio::task::yield_now().await;
        let sign_state = state.clone();
        let sign_address = address.clone();
        let sign_key = key.clone();
        let sign = tokio::spawn(async move {
            sign_state.sign_xite(&sign_address, &sign_key).await
        });
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        assert!(!barrier.is_finished(), "barrier bypassed the active reader");
        assert!(!sign.is_finished(), "root sign bypassed the queued barrier writer");
        drop(initial_reader);

        barrier.await.unwrap().unwrap();
        sign.await.unwrap().unwrap();
        assert!(store.contains(id).unwrap());
        assert!(store.is_complete(id).unwrap());
        assert!(
            state
                .edx_paths
                .read()
                .unwrap()
                .get(&id)
                .is_some_and(|entries| entries.iter().any(|entry| {
                    entry.accounting_key == address && entry.inner_path == "asset.bin"
                })),
            "newly signed file declaration was not indexed"
        );
    }

