    #[tokio::test]
    async fn cancelled_bigfile_finish_still_adopts_the_committed_root() {
        let fixture = shared_extern_fixture(true, true).await;
        fixture.state.bigfile_uploads.lock().unwrap().insert(
            "cancelled-finish".to_string(),
            BigfileUpload {
                address: fixture.address_a.clone(),
                canonical: fixture.address_a.clone(),
                storage_root: fixture.storage_a.root().to_path_buf(),
                membership_generation: fixture.membership_generation_a,
                inner_path: "shared.bin".to_string(),
                size: 11,
                piece_size: 1024 * 1024,
                piecemap_inner_path: "shared.bin.piecemap.msgpack".to_string(),
            },
        );
        let entered = Arc::new(tokio::sync::Notify::new());
        let release = Arc::new(tokio::sync::Semaphore::new(0));
        *BIGFILE_AFTER_MANIFEST_COMMIT_PAUSE
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some((
            fixture.storage_a.path("content.json").unwrap(),
            entered.clone(),
            release.clone(),
        ));
        let entered_wait = entered.notified();
        tokio::pin!(entered_wait);
        let replacement = random_upload_bytes(11);
        let state = fixture.state.clone();
        let upload = replacement.clone();
        let finish = tokio::spawn(async move {
            state
                .bigfile_upload_finish("cancelled-finish", &upload)
                .await
        });
        entered_wait.await;
        finish.abort();
        let _ = finish.await;
        release.add_permits(1);
        *BIGFILE_AFTER_MANIFEST_COMMIT_PAUSE
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;

        let expected = epix_xite::hash_bigfile(&replacement, 1024 * 1024).merkle_root;
        tokio::time::timeout(std::time::Duration::from_secs(5), async {
            loop {
                let disk = fixture
                    .storage_a
                    .read("content.json")
                    .ok()
                    .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok());
                let managed = fixture.state.content(&fixture.address_a).await;
                let disk_hash = disk
                    .as_ref()
                    .and_then(|root| root.get("files_optional"))
                    .and_then(|files| files.get("shared.bin"))
                    .and_then(|entry| entry.get("sha512"))
                    .and_then(Value::as_str);
                let managed_hash = managed
                    .as_ref()
                    .and_then(|root| root.get("files_optional"))
                    .and_then(|files| files.get("shared.bin"))
                    .and_then(|entry| entry.get("sha512"))
                    .and_then(Value::as_str);
                if disk_hash == Some(expected.as_str())
                    && managed_hash == Some(expected.as_str())
                    && fixture.store.extern_entries().unwrap().iter().any(|entry| {
                        entry.id == fixture.id
                            && entry.path == fixture.storage_b.path("shared.bin").unwrap()
                    })
                {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("detached bigfile completion did not adopt and settle its committed draft");
        assert_eq!(fixture.storage_a.read("shared.bin").unwrap(), replacement);
        assert_shared_extern_rehomed(&fixture);
    }

