    #[tokio::test]
    async fn load_content_from_disk_waits_for_the_activation_barrier() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path().join("xite"));
        let key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&key).unwrap();
        let mut content = json!({ "address": address, "modified": 1.0, "files": {} });
        epix_content::sign(&mut content, &key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&content).unwrap())
            .unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                &address,
                XiteEntry { storage, content: None },
            )
            .await;
        let barrier = state.xite_activation_gate.clone().write_owned().await;
        let load_state = state.clone();
        let load_address = address.clone();
        let load = tokio::spawn(async move {
            load_state.load_content_from_disk(&load_address).await
        });
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        assert!(!load.is_finished());
        assert!(state.xites.read().await[&address].content.is_none());
        drop(barrier);

        assert!(load.await.unwrap());
        assert!(state.xites.read().await[&address].content.is_some());
    }

    /// A re-signed manifest that starts declaring `b3` for files whose BYTES
    /// never changed must become servable immediately, not at the next
    /// restart.
    ///
    /// This is the pre-EDX -> EDX re-sign, and it is invisible to every other
    /// path: nothing needs downloading (the files are already correct on
    /// disk), so no fetch registers them, and registration otherwise only
    /// runs at boot. Measured on a real node, 8 xites went from 0 to 507 b3
    /// entries on a re-sign and none of their large files could be served
    /// until someone restarted it.
    #[tokio::test]
    async fn a_resigned_manifest_registers_its_objects_without_a_restart() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let privatekey = epix_crypt::new_seed();
        let addr = &epix_crypt::privatekey_to_address(&privatekey).unwrap();
        // A file big enough to be an extern object, already on disk.
        let big = vec![b'x'; 200 * 1024];
        storage.write("assets/big.js", &big).unwrap();
        let b3 = epix_blob::ObjId::of(&big);

        // The OLD manifest is pre-EDX: it declares the file with no b3, so
        // registration has nothing to store for it.
        let mut pre_edx = json!({
            "address": addr, "modified": 1.0,
            "files": { "assets/big.js": {
                "size": big.len(), "sha512": XiteStorage::hash_bytes(&big) } },
        });
        epix_content::sign(&mut pre_edx, &privatekey).unwrap();
        storage.write("content.json", &serde_json::to_vec(&pre_edx).unwrap()).unwrap();

        let state = AppState::new("test");
        let store_dir = tempdir().unwrap();
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                store_dir.path(),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().parent().unwrap().to_path_buf()),
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        state.set_edx_store(store.clone()).await.unwrap();
        state
            .add_xite(addr, XiteEntry { storage: storage.clone(), content: Some(pre_edx),
                },
            )
            .await;
        assert!(!store.contains(b3).unwrap(), "pre-EDX manifest registers nothing");
        store
            .ensure_sparse(b3, epix_blob::Ns::Plain, big.len() as u64, 1)
            .unwrap();
        assert!(store.contains(b3).unwrap(), "the interrupted sparse row exists");
        assert!(
            !store.is_complete(b3).unwrap(),
            "the interrupted sparse row is not yet servable"
        );

        // The re-signed manifest lands: same bytes on disk, now with a b3.
        let mut edx = json!({
            "address": addr, "modified": 2.0, "edx": 1,
            "files": { "assets/big.js": {
                "size": big.len(),
                "sha512": XiteStorage::hash_bytes(&big),
                "b3": b3.to_string() } },
        });
        epix_content::sign(&mut edx, &privatekey).unwrap();
        let bytes = serde_json::to_vec(&edx).unwrap();
        let guard = state.merge_path_lock(addr, "content.json").lock_owned().await;
        let transaction =
            AppState::bind_manifest_transaction(&storage, addr, "content.json", &bytes, guard)
                .unwrap();
        state
            .commit_root_update(&[addr.to_string()], addr, &storage, edx, &bytes, &transaction,
            )
            .await;

        // Servable now, with no restart - and adopted in place, so the bytes
        // are still the one copy in the xite tree.
        assert!(store.contains(b3).unwrap(), "the re-signed manifest's object registered");
        assert!(store.is_extern(b3).unwrap(), "adopted in place, not copied into the store");
        assert!(
            !store_dir.path().join("sparse").join(b3.to_string()).exists(),
            "no second copy of the bytes"
        );
    }

    #[tokio::test]
    async fn inbound_root_commit_refreshes_pool_rule_and_admission_gate_together() {
        use crate::pool::{
            PoolAdmission, PoolAdmissionBatch, PoolAdmissionRecord, PoolAdmissionRefresh,
        };

        struct ObservedRefresh(std::sync::atomic::AtomicBool);

        impl PoolAdmission for ObservedRefresh {
            fn refresh_address(
                &self,
                _: &str,
                content: Option<&Value>,
                retained: &mut dyn FnMut() -> Result<Vec<PoolAdmissionRecord>, String>,
            ) -> PoolAdmissionRefresh {
                assert!(retained().unwrap().is_empty());
                self.0.store(
                    content
                        .and_then(|root| root.pointer("/pool/channels/rln_required"))
                        .and_then(Value::as_bool)
                        == Some(true),
                    Ordering::Release,
                );
                PoolAdmissionRefresh::default()
            }

            fn admit_records(&self, _: &str, _: &[PoolAdmissionRecord]) -> PoolAdmissionBatch {
                PoolAdmissionBatch::default()
            }

            fn allow_rescan_records(&self, _: &str, records: &[PoolAdmissionRecord]) -> Vec<bool> {
                vec![true; records.len()]
            }
        }

        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let privatekey = epix_crypt::new_seed();
        let addr = epix_crypt::privatekey_to_address(&privatekey).unwrap();
        let descriptor = |modified: f64, rln_required: bool| {
            let mut root = json!({
                "address": addr,
                "modified": modified,
                "files": {},
                "pool": { "channels": {
                    "dir": "pool", "class": "epix-pool-1", "since_week": 0,
                    "fanout": 2, "pow_bits": 0, "pad_buckets": [64],
                    "max_record_bytes": 4096, "max_shard_bytes": 1_000_000,
                    "rln_required": rln_required
                }}
            });
            epix_content::sign(&mut root, &privatekey).unwrap();
            root
        };
        let old = descriptor(1.0, false);
        storage
            .write("content.json", &serde_json::to_vec(&old).unwrap())
            .unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                &addr,
                XiteEntry {
                    storage: storage.clone(),
                    content: Some(old),
                },
            )
            .await;
        assert!(!state.pool_rules_for(&addr).await[0].rln_required);
        let observed = Arc::new(ObservedRefresh(std::sync::atomic::AtomicBool::new(false)));
        state.set_pool_admission(observed.clone()).await;

        let inbound = descriptor(2.0, true);
        let bytes = serde_json::to_vec(&inbound).unwrap();
        let manifest = state
            .acquire_manifest_guard(&addr, "content.json")
            .await
            .unwrap();
        let transaction = AppState::bind_manifest_transaction(
            &storage,
            &addr,
            "content.json",
            &bytes,
            manifest,
        )
        .unwrap();
        assert!(
            state
                .finalize_root_update(RootFinalize {
                    keys: &[addr.clone()],
                    canonical: &addr,
                    storage: &storage,
                    content: inbound,
                    bytes: &bytes,
                    failed: &[],
                    transaction: &transaction,
                })
                .await
        );
        assert!(state.pool_rules_for(&addr).await[0].rln_required);
        assert!(observed.0.load(Ordering::Acquire));
    }

    #[tokio::test]
    async fn cancelled_root_commit_registers_a_newly_accepted_stored_child() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path().join("xite"));
        let privatekey = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&privatekey).unwrap();
        let child_bytes = vec![b'c'; 200 * 1024];
        let child_id = epix_blob::ObjId::of(&child_bytes);
        storage.write("child/asset.bin", &child_bytes).unwrap();
        let mut child = json!({
            "address": address,
            "inner_path": "child/content.json",
            "modified": 1.0,
            "files": {
                "asset.bin": {
                    "size": child_bytes.len(),
                    "sha512": XiteStorage::hash_bytes(&child_bytes),
                    "b3": child_id.to_string(),
                }
            },
        });
        epix_content::sign(&mut child, &privatekey).unwrap();
        storage
            .write("child/content.json", &serde_json::to_vec(&child).unwrap())
            .unwrap();

        let mut root_v1 = json!({
            "address": address,
            "modified": 1.0,
            "files": {},
        });
        epix_content::sign(&mut root_v1, &privatekey).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root_v1).unwrap())
            .unwrap();
        let state = AppState::new("test");
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                dir.path().join("store"),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().to_path_buf()),
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        state.set_edx_store(store.clone()).await.unwrap();
        state
            .add_xite(
                &address,
                XiteEntry { storage: storage.clone(), content: Some(root_v1) },
            )
            .await;
        assert!(
            !store.contains(child_id).unwrap(),
            "an unaccepted child is not registered"
        );

        let mut root_v2 = json!({
            "address": address,
            "modified": 2.0,
            "files": {},
            "includes": { "child/content.json": {} },
        });
        epix_content::sign(&mut root_v2, &privatekey).unwrap();
        let root_v2_bytes = serde_json::to_vec(&root_v2).unwrap();
        let manifest = state
            .acquire_manifest_guard(&address, "content.json")
            .await
            .unwrap();
        let transaction = AppState::bind_manifest_transaction(
            &storage,
            &address,
            "content.json",
            &root_v2_bytes,
            manifest,
        )
        .unwrap();
        let tree = state.tree_mutation_lock(&address).lock_owned().await;
        let commit_state = state.clone();
        let commit_address = address.clone();
        let commit_storage = storage.clone();
        let commit = tokio::spawn(async move {
            commit_state
                .commit_root_update(
                    &[commit_address.clone()],
                    &commit_address,
                    &commit_storage,
                    root_v2,
                    &root_v2_bytes,
                    &transaction,
                )
                .await
        });
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        assert!(
            state.xite_activation_gate.clone().try_write_owned().is_err(),
            "the root transaction did not acquire activation authority"
        );
        commit.abort();
        let _ = commit.await;
        assert!(
            state.xite_activation_gate.clone().try_write_owned().is_err(),
            "caller cancellation released the root transaction authority"
        );
        drop(tree);

        tokio::time::timeout(std::time::Duration::from_secs(5), async {
            loop {
                if store.is_complete(child_id).unwrap_or(false)
                    && state.edx_object_path(&child_id).is_some()
                {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("detached root completion did not register the accepted child object");
        assert!(store.is_extern(child_id).unwrap());
        store.claim_feed(child_id).unwrap();
        assert_eq!(store.ref_delta(child_id, 0).unwrap(), 2);

        let mut root_v3 = json!({
            "address": address,
            "modified": 3.0,
            "files": {},
        });
        epix_content::sign(&mut root_v3, &privatekey).unwrap();
        let root_v3_bytes = serde_json::to_vec(&root_v3).unwrap();
        let manifest = state
            .acquire_manifest_guard(&address, "content.json")
            .await
            .unwrap();
        let transaction = AppState::bind_manifest_transaction(
            &storage,
            &address,
            "content.json",
            &root_v3_bytes,
            manifest,
        )
        .unwrap();
        assert!(
            state
                .commit_root_update(
                    &[address.clone()],
                    &address,
                    &storage,
                    root_v3,
                    &root_v3_bytes,
                    &transaction,
                )
                .await
        );
        assert!(storage.exists("child/content.json"), "revoked child bytes remain stale");
        assert!(state.edx_object_path(&child_id).is_none());
        assert!(
            store
                .complete_extern_owner_at(&storage.path("child/asset.bin").unwrap())
                .unwrap()
                .is_none(),
            "revoked child path retained an extern owner"
        );
        assert!(store.is_complete(child_id).unwrap());
        assert!(!store.is_extern(child_id).unwrap());
        assert_eq!(
            store.ref_delta(child_id, 0).unwrap(),
            1,
            "revoking the manifest dropped the independent feed reference"
        );
        store.release_feed(child_id).unwrap();
        assert_eq!(store.ref_delta(child_id, 0).unwrap(), 0);
    }

    #[tokio::test]
    async fn child_resign_registers_an_unchanged_file_that_gains_b3() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path().join("xite"));
        let privatekey = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&privatekey).unwrap();
        let child_path = "child/content.json";
        let payload = vec![b'd'; 200 * 1024];
        let id = epix_blob::ObjId::of(&payload);
        storage.write("child/asset.bin", &payload).unwrap();
        let mut root = json!({
            "address": address,
            "modified": 1.0,
            "files": {},
            "includes": { child_path: {} },
        });
        epix_content::sign(&mut root, &privatekey).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root).unwrap())
            .unwrap();
        let mut child_v1 = json!({
            "address": address,
            "inner_path": child_path,
            "modified": 1.0,
            "files": {
                "asset.bin": {
                    "size": payload.len(),
                    "sha512": XiteStorage::hash_bytes(&payload),
                }
            },
        });
        epix_content::sign(&mut child_v1, &privatekey).unwrap();
        storage
            .write(child_path, &serde_json::to_vec(&child_v1).unwrap())
            .unwrap();

        let state = AppState::new("test");
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                dir.path().join("store"),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().to_path_buf()),
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        state.set_edx_store(store.clone()).await.unwrap();
        state
            .add_xite(
                &address,
                XiteEntry { storage: storage.clone(), content: Some(root) },
            )
            .await;
        assert!(!store.contains(id).unwrap(), "the SHA-only child registers no object");

        let mut child_v2 = child_v1;
        child_v2["modified"] = json!(2.0);
        child_v2["files"]["asset.bin"]["b3"] = json!(id.to_string());
        child_v2.as_object_mut().unwrap().remove("sign");
        child_v2.as_object_mut().unwrap().remove("signs");
        epix_content::sign(&mut child_v2, &privatekey).unwrap();
        let child_v2_bytes = serde_json::to_vec(&child_v2).unwrap();
        let applied = state
            .apply_inbound_update(
                &address,
                child_path,
                Some(child_v2_bytes.clone()),
                Some(2.0),
                None,
                None,
                UpdatePayload::default(),
                Vec::new(),
            )
            .await
            .unwrap();
        assert_eq!(applied, InboundUpdate::Applied);
        assert_eq!(storage.read(child_path).unwrap(), child_v2_bytes);
        assert!(store.is_complete(id).unwrap());
        assert!(store.is_extern(id).unwrap());
        assert!(state.edx_object_path(&id).is_some());

        let mut child_v3 = child_v2;
        child_v3["modified"] = json!(3.0);
        child_v3["files"] = json!({});
        child_v3.as_object_mut().unwrap().remove("sign");
        child_v3.as_object_mut().unwrap().remove("signs");
        epix_content::sign(&mut child_v3, &privatekey).unwrap();
        let applied = state
            .apply_inbound_update(
                &address,
                child_path,
                Some(serde_json::to_vec(&child_v3).unwrap()),
                Some(3.0),
                None,
                None,
                UpdatePayload::default(),
                Vec::new(),
            )
            .await
            .unwrap();
        assert_eq!(applied, InboundUpdate::Applied);
        assert!(state.edx_object_path(&id).is_none());
        assert!(
            store
                .complete_extern_owner_at(&storage.path("child/asset.bin").unwrap())
                .unwrap()
                .is_none(),
            "removed child declaration retained its extern owner"
        );
        assert!(
            !store.contains(id).unwrap() || store.ref_delta(id, 0).unwrap() == 0,
            "removed child declaration retained its last manifest pin"
        );
    }

    /// An ordinary update that declares nothing new must preserve the
    /// existing Store registration.
    #[tokio::test]
    async fn an_update_declaring_nothing_new_preserves_existing_registration() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        let body = vec![b'y'; 200 * 1024];
        storage.write("assets/big.js", &body).unwrap();
        let b3 = epix_blob::ObjId::of(&body);
        let content = json!({
            "address": addr, "modified": 1.0, "edx": 1,
            "files": { "assets/big.js": {
                "size": body.len(),
                "sha512": XiteStorage::hash_bytes(&body),
                "b3": b3.to_string() } },
        });

        let state = AppState::new("test");
        let store_dir = tempdir().unwrap();
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                store_dir.path(),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().parent().unwrap().to_path_buf()),
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        state.set_edx_store(store.clone()).await.unwrap();
        state
            .add_xite(addr, XiteEntry { storage: storage.clone(), content: Some(content.clone()),
                },
            )
            .await;
        // Already held (the boot pass, or the fetch that brought it).
        store.adopt_extern(b3, epix_blob::Ns::Plain, &storage.path("assets/big.js").unwrap(), 1,
            ).unwrap();
        assert!(store.is_extern(b3).unwrap());

        // Landing the same manifest again is a no-op, and must not disturb it.
        let bytes = serde_json::to_vec(&content).unwrap();
        let guard = state.merge_path_lock(addr, "content.json").lock_owned().await;
        let transaction =
            AppState::bind_manifest_transaction(&storage, addr, "content.json", &bytes, guard)
                .unwrap();
        state
            .commit_root_update(&[addr.to_string()], addr, &storage, content, &bytes, &transaction,
            )
            .await;
        assert!(store.is_extern(b3).unwrap(), "still extern, untouched");
    }

    #[tokio::test]
    async fn package_unit_completes_after_first_paint_within_the_size_limit() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        // First paint is already on disk; the rest of the package is not.
        let shell: &[u8] = b"<html>shell</html>";
        storage.write("index.html", shell).unwrap();
        let content = json!({
            "address": addr, "modified": 1.0,
            "distribution": {
                "default": {"unit": "package", "retention": "complete"},
                "paths": { "data/feed/": {"unit": "feed", "retention": "partial"} }
            },
            "files": {
                "index.html": { "size": shell.len(), "sha512": XiteStorage::hash_bytes(shell) },
                "js/app.js": { "size": 2 * 1024 * 1024, "sha512": "aa" },
            },
            "files_optional": {
                "data/feed/seg7.bin": { "size": 900 * 1024 * 1024, "sha512": "bb" },
            },
        });
        let state = AppState::new("test");
        state.config_set("download_optional_default", Value::from("false")).await;
        state.config_set("autodownloadoptional_default", Value::from("false")).await;
        state.add_xite(addr, XiteEntry { storage, content: Some(content),
                },
            ).await;

        // The default size limit (DEFAULT_SIZE_LIMIT_MB = 1000 MB) covers the
        // 2 MB remainder -> completes quietly. index.html verifies on disk, so
        // first paint is NOT in the plan: streaming already delivered it,
        // completion is only the rest.
        let plan = state.retention_completion_plan(addr).await;
        assert_eq!(plan.paths, vec!["js/app.js".to_string()], "only the missing complete-unit file");
        assert!(!plan.paths.contains(&"index.html".to_string()), "first paint is not re-fetched");
        assert!(
            !plan.paths.contains(&"data/feed/seg7.bin".to_string()),
            "retention:partial feed stays fetch-what-you-view"
        );
        assert_eq!(plan.bytes, 2 * 1024 * 1024);
        assert!(!plan.needs_consent, "under the size limit -> completes quietly");

        // Drop the limit below the remainder: the same plan now needs the
        // existing optional-download consent, which this xite has not given.
        state.set_size_limit(addr, 1).await;
        let gated = state.retention_completion_plan(addr).await;
        assert_eq!(gated.paths, vec!["js/app.js".to_string()]);
        assert!(gated.needs_consent, "over the size limit -> consent gate");
        assert!(!state.optional_fetch_allowed(addr).await, "no standing consent");

        // Granting the standing consent (the familiar toggle) clears the gate.
        assert!(state.set_autodownloadoptional(addr, true).await);
        assert!(state.optional_fetch_allowed(addr).await);

        // A xite declaring no distribution policy is still replicated whole:
        // completing is the default, so the reader ends up with the same
        // package the publisher has rather than only the parts they opened.
        let bare_dir = tempdir().unwrap();
        let bare = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        state
            .add_xite(
                bare,
                XiteEntry {
                    storage: XiteStorage::new(bare_dir.path()),
                    content: Some(json!({
                        "address": bare, "modified": 1.0,
                        "files": { "big.bin": { "size": 99, "sha512": "cc" } }
                    })),
                },
            )
            .await;
        assert_eq!(
            state.retention_completion_plan(bare).await.paths,
            vec!["big.bin".to_string()],
            "no declared policy -> the default completes the package"
        );
    }

    /// An over-budget completion is NOT authorized by "Download files I open".
    ///
    /// That toggle defaults to ON and means only "fetch the file this page
    /// asked for". Accepting it as standing consent is what let a xite pull
    /// 430 files / 3.75 GB against a 1000 MB limit with no prompt. Consent for
    /// a whole-xite download is the broad toggle, or a recorded yes.
    #[tokio::test]
    async fn completing_a_xite_needs_more_than_the_on_demand_toggle() {
        let dir = tempdir().unwrap();
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                addr,
                XiteEntry {
                    storage: XiteStorage::new(dir.path()),
                    content: Some(json!({
                        "address": addr, "modified": 1.0,
                        "files_optional": { "video/big.webm": { "size": 4_000_000_000u64, "sha512": "aa" } }
                    })),
                },
            )
            .await;
        // The shipped defaults: on-demand ON, pre-download everything OFF.
        state.set_download_optional(addr, true, false).await;
        assert!(state.optional_fetch_allowed(addr).await, "on-demand fetching is allowed");
        assert!(
            !state.retention_fetch_allowed(addr).await,
            "...but that is NOT consent to complete the whole xite"
        );
        assert!(
            state.retention_completion_plan(addr).await.needs_consent,
            "4 GB against the default 1000 MB limit needs consent"
        );

        // The broad toggle IS that consent, on its own.
        assert!(state.set_autodownloadoptional(addr, true).await);
        assert!(state.retention_fetch_allowed(addr).await, "'Pre-download everything' grants it");

        // So is an accepted prompt, recorded explicitly - and it is paired
        // with the on-demand toggle, so unticking EITHER box still stops a
        // pass in flight.
        assert!(state.set_autodownloadoptional(addr, false).await);
        state.retention_consents.lock().unwrap().insert(addr.to_string());
        assert!(state.retention_fetch_allowed(addr).await, "an accepted prompt grants it");
        state.set_download_optional(addr, false, false).await;
        assert!(
            !state.retention_fetch_allowed(addr).await,
            "unticking 'Download files I open' revokes it"
        );
        // ...and revokes it for good: re-ticking must ask again rather than
        // silently reviving the earlier yes.
        state.set_download_optional(addr, true, false).await;
        assert!(
            !state.retention_fetch_allowed(addr).await,
            "switching off revoked the consent; re-enabling re-asks"
        );
    }

    /// A publisher's `autodownloadoptional_default: false` vetoes completion at
    /// ANY size - the under-budget path completes silently, so a veto that only
    /// applied above the limit would not be a veto at all. A deliberate user
    /// opt-in still overrides it: the author sets a default, not a prohibition.
    #[tokio::test]
    async fn an_author_opt_out_vetoes_completion_until_the_user_overrides() {
        let dir = tempdir().unwrap();
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                addr,
                XiteEntry {
                    storage: XiteStorage::new(dir.path()),
                    content: Some(json!({
                        "address": addr, "modified": 1.0,
                        "autodownloadoptional_default": false,
                        "files_optional": { "video/big.webm": { "size": 500_000_000u64, "sha512": "aa" } }
                    })),
                },
            )
            .await;
        assert!(state.author_opts_out_of_prefetch(addr).await);
        // Well under the 1000 MB limit, so this is the path that would
        // otherwise complete with no prompt at all.
        assert!(!state.retention_completion_plan(addr).await.needs_consent);
        assert!(
            state.retention_author_veto_holds(addr, false).await,
            "the author's opt-out blocks the quiet path too"
        );

        // The user asking for everything, per xite or globally, overrides it.
        assert!(state.set_autodownloadoptional(addr, true).await);
        assert!(
            !state.retention_author_veto_holds(addr, false).await,
            "'Pre-download everything' is a deliberate override"
        );
        assert!(state.set_autodownloadoptional(addr, false).await);
        assert!(
            !state.retention_author_veto_holds(addr, true).await,
            "the global 'keep a full copy' setting is too"
        );

        // A xite that says nothing is unaffected: no veto, business as usual.
        let quiet_dir = tempdir().unwrap();
        let quiet = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        state
            .add_xite(
                quiet,
                XiteEntry {
                    storage: XiteStorage::new(quiet_dir.path()),
                    content: Some(json!({ "address": quiet, "modified": 1.0 })),
                },
            )
            .await;
        assert!(!state.retention_author_veto_holds(quiet, false).await);
    }

    /// The global `full_retention` setting makes a reader replicate every xite
    /// fully: the plan covers ALL missing declared files, including the
    /// owner's `retention:partial` carve-outs and xites that declared no
    /// distribution policy at all. The size-limit consent gate is unchanged -
    /// the override widens what completes, not who decides.
    #[tokio::test]
    async fn full_retention_setting_plans_every_missing_path() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        let content = json!({
            "address": addr, "modified": 1.0,
            "distribution": {
                "default": {"unit": "package", "retention": "complete"},
                "paths": { "data/feed/": {"unit": "feed", "retention": "partial"} }
            },
            "files": {
                "js/app.js": { "size": 2 * 1024 * 1024, "sha512": "aa" },
            },
            "files_optional": {
                "data/feed/seg7.bin": { "size": 3 * 1024 * 1024, "sha512": "bb" },
            },
        });
        let state = AppState::new("test");
        state.config_set("download_optional_default", Value::from("false")).await;
        state.config_set("autodownloadoptional_default", Value::from("false")).await;
        state.add_xite(addr, XiteEntry { storage, content: Some(content),
                },
            ).await;

        // Owner policy alone: the partial feed stays out of the plan.
        let owner = state.retention_completion_plan(addr).await;
        assert_eq!(owner.paths, vec!["js/app.js".to_string()]);

        // Override on: the feed carve-out is planned too, well under the
        // default limit (DEFAULT_SIZE_LIMIT_MB = 1000 MB) -> still quiet.
        state.config_set("full_retention", Value::from("true")).await;
        let full = state.retention_completion_plan(addr).await;
        assert_eq!(
            full.paths,
            vec!["data/feed/seg7.bin".to_string(), "js/app.js".to_string()],
            "every missing declared file is planned"
        );
        assert_eq!(full.bytes, 5 * 1024 * 1024);
        assert!(!full.needs_consent, "under the size limit -> completes quietly");

        // The consent gate still holds when the plan outgrows the limit.
        state.set_size_limit(addr, 1).await;
        assert!(state.retention_completion_plan(addr).await.needs_consent);

        // A bare xite (no distribution declared) is also fully replicated.
        let bare_dir = tempdir().unwrap();
        let bare = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        state
            .add_xite(
                bare,
                XiteEntry {
                    storage: XiteStorage::new(bare_dir.path()),
                    content: Some(json!({
                        "address": bare, "modified": 1.0,
                        "files": { "big.bin": { "size": 99, "sha512": "cc" } }
                    })),
                },
            )
            .await;
        assert_eq!(
            state.retention_completion_plan(bare).await.paths,
            vec!["big.bin".to_string()],
            "undeclared xites are fully replicated under the override"
        );

        // Off again: back to the owner's declaration.
        state.config_set("full_retention", Value::from("false")).await;
        assert_eq!(state.retention_completion_plan(addr).await.paths, vec!["js/app.js".to_string()]);
    }

    /// The schema default for `full_retention` must be OFF. The Config page
    /// renders an unset bool from this schema row and persists every bool on
    /// any save, so a drifted default would silently enroll fresh installs in
    /// whole-network replication. `config_bool` call sites must mirror it
    /// (their doc says so); this pins the schema side.
    #[test]
    fn full_retention_schema_default_is_off() {
        let row = CONFIG_SCHEMA
            .iter()
            .find(|(_, key, ..)| *key == "full_retention")
            .expect("full_retention must be in CONFIG_SCHEMA");
        assert_eq!(row.3, "false", "full replication must be opt-in");
        assert_eq!(row.4, "bool");
    }

    /// A volunteer cache with no volunteers holds nothing, so desktop nodes
    /// donate disk by default. Phones do not: small storage, metered data.
    #[tokio::test]
    async fn desktop_donates_shard_disk_by_default() {
        let row = CONFIG_SCHEMA
            .iter()
            .find(|(_, key, ..)| *key == "volunteer_quota_bytes")
            .expect("volunteer_quota_bytes must be in CONFIG_SCHEMA");
        assert_eq!(row.3, DEFAULT_VOLUNTEER_QUOTA, "the schema and the reader must agree");

        // The accessor's fallback has to match the schema, or the Config page
        // would show one number while the node used another.
        let state = AppState::new("test");
        let expected: u64 = DEFAULT_VOLUNTEER_QUOTA.parse().unwrap();
        assert_eq!(state.volunteer_quota_bytes().await, expected);
        if cfg!(any(target_os = "android", target_os = "ios")) {
            assert_eq!(expected, 0, "phones donate nothing");
        } else {
            assert!(expected > 0, "desktop volunteers by default");
        }

        // And it stays operator-controlled.
        state.config_set("volunteer_quota_bytes", Value::from("0")).await;
        assert_eq!(state.volunteer_quota_bytes().await, 0);
    }

    /// A peer's age is the durability signal peer selection breaks ties on,
    /// so it has to survive a restart. It used to be reset to `now` on every
    /// boot, which made every peer permanently look brand new.
    #[test]
    fn a_peers_age_survives_a_restart() {
        // Past 40 days, so the age being tested is actually positive.
        let now = 100_000_000i64;
        let mut peer = Peer::new(PeerAddr::parse("1.2.3.4:26552").unwrap(), now - 40 * 86_400);
        peer.reputation = 3;
        peer.time_response = now - 100;

        let entry = AppState::persisted_peer(&peer, now);
        assert_eq!(entry["found"], json!(now - 40 * 86_400), "first-seen is written");

        // Restoring reads it back rather than stamping a fresh `now`.
        let restored = entry["found"].as_i64().unwrap().clamp(0, now);
        assert_eq!(restored, now - 40 * 86_400);

        // A future stamp (clock skew, a hand-edited file) cannot mint an
        // unbeatably old peer.
        let mut future = peer.clone();
        future.time_found = now + 86_400;
        let skewed = AppState::persisted_peer(&future, now)["found"].as_i64().unwrap().clamp(0, now);
        assert_eq!(skewed, now, "clamped to the present");
    }

    /// The consent gate charges bytes ALREADY held against the size limit:
    /// a plan that fits the limit on its own but would push the xite past it
    /// must prompt. Regression: the gate used to compare only the increment,
    /// so a xite could quietly grow to nearly twice its consented cap.
    #[tokio::test]
    async fn completion_consent_counts_bytes_already_on_disk() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        // 700 KB already on disk (verifies against its declared hash), 500 KB
        // missing, and a 1 MB size limit: the missing 500 KB fits the limit
        // alone but not on top of what is held.
        let held = vec![0xEEu8; 700 * 1024];
        storage.write("held.bin", &held).unwrap();
        let content = json!({
            "address": addr, "modified": 1.0,
            "distribution": { "default": {"unit": "package", "retention": "complete"} },
            "files": {
                "held.bin": { "size": held.len(), "sha512": XiteStorage::hash_bytes(&held) },
                "missing.bin": { "size": 500 * 1024, "sha512": "aa" },
            },
        });
        let state = AppState::new("test");
        state.config_set("download_optional_default", Value::from("false")).await;
        state.config_set("autodownloadoptional_default", Value::from("false")).await;
        state.add_xite(addr, XiteEntry { storage, content: Some(content),
                },
            ).await;
        state.set_size_limit(addr, 1).await;

        let plan = state.retention_completion_plan(addr).await;
        assert_eq!(plan.paths, vec!["missing.bin".to_string()]);
        assert_eq!(plan.bytes, 500 * 1024);
        assert!(
            plan.needs_consent,
            "500 KB fits 1 MB alone, but not on top of the 700 KB already held"
        );

        // With room for both (2 MB limit), it completes quietly again.
        state.set_size_limit(addr, 2).await;
        assert!(!state.retention_completion_plan(addr).await.needs_consent);
    }

    /// `full_retention_watch` is the set the retry loop drives the global
    /// promise over: serving, not own, and no whole-xite optional promise of
    /// its own. A directory-scoped optionalHelp commitment does NOT exclude a
    /// xite - the rest of its files still need the retention pass. Empty when
    /// the setting is off.
    #[tokio::test]
    async fn full_retention_watch_covers_only_unpromised_xites() {
        let state = AppState::new("test");
        state.config_set("download_optional_default", Value::from("false")).await;
        state.config_set("autodownloadoptional_default", Value::from("false")).await;
        let mut addrs = Vec::new();
        for _ in 0..4 {
            let dir = tempdir().unwrap();
            let addr = epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
            let content = json!({ "address": addr, "modified": 1.0, "files": {} });
            state
                .add_xite(
                    &addr,
                    XiteEntry { storage: XiteStorage::new(dir.path()), content: Some(content),
                    },
                )
                .await;
            addrs.push(addr);
        }
        {
            let mut xites = state.xites.write().await;
            // [0] plain -> watched. [1] has its own whole-xite promise.
            xites.get_mut(&addrs[1]).unwrap().settings.download_optional = true;
            // [2] own xite. [3] dir-scoped help only -> still watched.
            xites.get_mut(&addrs[2]).unwrap().settings.own = true;
            xites
                .get_mut(&addrs[3])
                .unwrap()
                .settings
                .optional_help
                .insert("data/media/".to_string(), Value::from("help"));
        }

        assert!(
            state.full_retention_watch().await.is_empty(),
            "setting off -> nothing watched"
        );

        state.config_set("full_retention", Value::from("true")).await;
        let mut expected = vec![addrs[0].clone(), addrs[3].clone()];
        expected.sort();
        assert_eq!(state.full_retention_watch().await, expected);
    }

    /// Bytes held in CHILD content.json units count against the consent
    /// budget. Regression: `present` used to come from the settings stats,
    /// which are root-only and reset on every root update, so a hub xite
    /// (per-user child units holding most bytes) fell back to the
    /// increment-only comparison and quietly overshot its size limit.
    #[tokio::test]
    async fn completion_consent_counts_child_unit_bytes() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        // A child unit declares 700 KB of optional media, present on disk.
        let media = vec![0xEEu8; 700 * 1024];
        storage.write("data/users/u1/big.bin", &media).unwrap();
        let child = json!({
            "files_optional": { "big.bin": { "size": media.len(), "sha512": "dd" } }
        });
        storage
            .write("data/users/u1/content.json", child.to_string().as_bytes())
            .unwrap();
        // The root declares 500 KB still missing; the limit is 1 MB.
        let content = json!({
            "address": addr, "modified": 1.0,
            "distribution": { "default": {"unit": "package", "retention": "complete"} },
            "files": { "missing.bin": { "size": 500 * 1024, "sha512": "aa" } },
        });
        let state = AppState::new("test");
        state.config_set("download_optional_default", Value::from("false")).await;
        state.config_set("autodownloadoptional_default", Value::from("false")).await;
        state.add_xite(addr, XiteEntry { storage, content: Some(content),
                },
            ).await;
        state.set_size_limit(addr, 1).await;

        let plan = state.retention_completion_plan(addr).await;
        assert_eq!(plan.paths, vec!["missing.bin".to_string()]);
        assert!(
            plan.needs_consent,
            "500 KB fits 1 MB alone, but not on top of 700 KB held in a child unit"
        );
        // The budget does not depend on the root-only settings stats: zeroing
        // them (what a root update used to do to the old arithmetic) changes
        // nothing, because present bytes come from the declared-file walk.
        {
            let mut xites = state.xites.write().await;
            let settings = &mut xites.get_mut(addr).unwrap().settings;
            settings.size = 0;
            settings.size_optional = 0;
        }
        assert!(state.retention_completion_plan(addr).await.needs_consent);
    }

    /// Child-unit REQUIRED `files` (per-user data.json - the dominant bytes
    /// on a hub xite) take part in the inventory on both sides: held ones are
    /// charged against the consent budget, and missing ones are planned under
    /// the override. Regression: the optional-only child walk saw neither, so
    /// a hub could quietly overshoot its cap and "keep a full copy" silently
    /// skipped user content.
    #[tokio::test]
    async fn child_required_files_are_charged_and_planned() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        // One child unit holds 700 KB of required user data on disk; another
        // declares 300 KB that is absent.
        let held = vec![0xEEu8; 700 * 1024];
        storage.write("data/users/u1/data.json", &held).unwrap();
        let child_held = json!({ "files": { "data.json": { "size": held.len(), "sha512": "dd" } } });
        storage.write("data/users/u1/content.json", child_held.to_string().as_bytes(),
            ).unwrap();
        let child_missing =
            json!({ "files": { "data.json": { "size": 300 * 1024, "sha512": "ee" } } });
        storage.write("data/users/u2/content.json", child_missing.to_string().as_bytes(),
            ).unwrap();
        let content = json!({
            "address": addr, "modified": 1.0,
            "distribution": { "default": {"unit": "package", "retention": "complete"} },
            "files": { "missing.bin": { "size": 500 * 1024, "sha512": "aa" } },
        });
        let state = AppState::new("test");
        state.config_set("download_optional_default", Value::from("false")).await;
        state.config_set("autodownloadoptional_default", Value::from("false")).await;
        state.add_xite(addr, XiteEntry { storage, content: Some(content),
                },
            ).await;
        state.set_size_limit(addr, 1).await;

        let plan = state.retention_completion_plan(addr).await;
        // Both missing files are planned - including the child-required one.
        assert_eq!(
            plan.paths,
            vec!["data/users/u2/data.json".to_string(), "missing.bin".to_string()],
            "child-required user data is part of the plan"
        );
        // And the held child bytes are charged: 800 KB planned fits 1 MB
        // alone, but not on top of the 700 KB held in the child unit.
        assert!(plan.needs_consent, "held child-required bytes count against the budget");
    }

    /// The retention prompt never burns its once-per-session slot without a
    /// viewer: at boot the retry loop reaches an over-budget xite before any
    /// wrapper binds, and a slot consumed by an unseen, timed-out confirm
    /// would silence both this prompt and the page's own optional prompt for
    /// the session.
    #[tokio::test(start_paused = true)]
    async fn retention_prompt_needs_a_viewer_to_consume_the_slot() {
        let state = AppState::new("test");
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        state.prompt_retention_completion(addr, 3, 5 * 1024 * 1024).await;
        assert!(
            !state.optional_prompts.lock().unwrap().contains(addr.as_str()),
            "no viewer -> slot untouched, a later pass may still ask"
        );

        // With a wrapper bound, the prompt fires and consumes the slot (the
        // unanswered confirm times out under paused time; consumption is the
        // once-per-session contract).
        state.register_bound_conn(addr, 42);
        state.prompt_retention_completion(addr, 3, 5 * 1024 * 1024).await;
        assert!(state.optional_prompts.lock().unwrap().contains(addr.as_str()));
    }

    /// An in-flight retention pass loses its mandate when the xite stops
    /// serving, when a reader-driven pass's global setting is turned off, or
    /// when needed consent is withdrawn - checked between files so a
    /// xite-sized pass stops mid-way, mirroring the bulk optional pass.
    #[tokio::test]
    async fn retention_pass_mandate_follows_serving_setting_and_consent() {
        let dir = tempdir().unwrap();
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        let state = AppState::new("test");
        state.config_set("download_optional_default", Value::from("false")).await;
        state.config_set("autodownloadoptional_default", Value::from("false")).await;
        state
            .add_xite(
                addr,
                XiteEntry {
                    storage: XiteStorage::new(dir.path()),
                    content: Some(json!({ "address": addr, "modified": 1.0, "files": {} })),
                },
            )
            .await;

        // Unknown xite -> no mandate.
        assert!(!state.retention_pass_should_continue("unknown", false, false).await);
        // Served, no further conditions -> mandate holds.
        assert!(state.retention_pass_should_continue(addr, false, false).await);
        // Reader-driven while the global setting is off -> stops.
        assert!(!state.retention_pass_should_continue(addr, true, false).await);
        state.config_set("full_retention", Value::from("true")).await;
        assert!(state.retention_pass_should_continue(addr, true, false).await);
        // A consented plan stops once consent is withdrawn.
        assert!(!state.retention_pass_should_continue(addr, true, true).await);
        // The on-demand toggle alone is NOT that consent: it means "fetch the
        // file this page asked for", and reading it as a mandate to complete a
        // whole xite is the bug this pairing exists to prevent.
        assert!(state.set_download_optional(addr, true, false).await);
        assert!(!state.retention_pass_should_continue(addr, true, true).await);
        // The broad toggle is.
        assert!(state.set_autodownloadoptional(addr, true).await);
        assert!(state.retention_pass_should_continue(addr, true, true).await);
        // Pausing withdraws every mandate.
        assert!(state.set_serving(addr, false).await);
        assert!(!state.retention_pass_should_continue(addr, false, false).await);
    }

    /// The pass BODY consults the mandate between files - not just the
    /// predicate in isolation. A pass whose mandate is gone attempts nothing;
    /// one whose mandate holds attempts every path (fetch failures do not
    /// stop the walk).
    #[tokio::test]
    async fn retention_pass_body_stops_when_the_mandate_is_withdrawn() {
        let dir = tempdir().unwrap();
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                addr,
                XiteEntry {
                    storage: XiteStorage::new(dir.path()),
                    content: Some(json!({ "address": addr, "modified": 1.0, "files": {} })),
                },
            )
            .await;
        let paths = vec!["a.bin".to_string(), "b.bin".to_string()];

        // Mandate holds: both paths are attempted (the fetches fail - no
        // peers - but failure must not stop the walk).
        assert_eq!(state.run_retention_pass(addr, paths.clone(), false, false).await, 2);
        // Reader-driven pass with the setting off: nothing is attempted.
        assert_eq!(state.run_retention_pass(addr, paths.clone(), true, false).await, 0);
        // Paused xite: nothing is attempted.
        assert!(state.set_serving(addr, false).await);
        assert_eq!(state.run_retention_pass(addr, paths, false, false).await, 0);
    }

    #[tokio::test]
    async fn optional_optin_gate_and_disk_recount() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        let video: &[u8] = b"video-bytes";
        storage.write("video.webm", video).unwrap();
        // A child-declared optional file on disk counts (and is advertised) too.
        let avatar: &[u8] = b"png";
        storage.write("data/users/alice/avatar.png", avatar).unwrap();
        storage
            .write(
                "data/users/alice/content.json",
                &serde_json::to_vec(&json!({
                    "files_optional": {
                        "avatar.png": { "size": avatar.len(), "sha512": XiteStorage::hash_bytes(avatar) }
                    }
                }))
                .unwrap(),
            )
            .unwrap();
        let content = json!({
            "address": addr, "modified": 1.0, "files": {},
            "files_optional": {
                "video.webm": { "size": video.len(), "sha512": XiteStorage::hash_bytes(video) },
                "missing.bin": { "size": 99, "sha512": "ab" },
            },
        });
        let state = AppState::new("test");
        // The node-wide defaults are ON; this test exercises the opt-in gate,
        // so run it as a node whose operator turned the defaults off.
        state.config_set("download_optional_default", Value::from("false")).await;
        state.config_set("autodownloadoptional_default", Value::from("false")).await;
        state.add_xite(addr, XiteEntry { storage, content: Some(content),
                },
            ).await;
        {
            let xites = state.xites.read().await;
            let x = xites.get(addr.as_str()).unwrap();
            assert_eq!(
                x.settings.optional_downloaded,
                (video.len() + avatar.len()) as i64,
                "counter recomputed from disk, root + child files"
            );
            assert!(
                x.hashfield.has_hash(&XiteStorage::hash_bytes(avatar)),
                "child optional file advertised in the hashfield"
            );
        }

        assert!(!state.optional_fetch_allowed(addr).await, "opt-in: off (defaults disabled)");
        // No transport in the test, so the triggered fetch is a clean no-op.
        assert!(state.set_download_optional(addr, true, true).await);
        assert!(state.optional_fetch_allowed(addr).await);
        assert!(state.set_download_optional(addr, false, false).await);
        assert!(!state.optional_fetch_allowed(addr).await);
        assert!(state.set_autodownloadoptional(addr, true).await);
        assert!(state.optional_fetch_allowed(addr).await, "help-distribute implies downloads");
    }

    /// The Files tab's data contract: optionalFileList carries the per-file
    /// counters the dashboard renders (uploaded/ratio dots, seeder count,
    /// "Finished") and honors the UI's orderby/limit params.
    #[tokio::test]
    async fn optional_file_list_reports_counters_and_orders() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        storage.write("a.bin", b"aaaa").unwrap();
        storage.write("b.bin", b"bbbbbbbb").unwrap();
        // A per-user (child content.json) optional file - a hub's avatars
        // live here, and a root-only walk left the Files tab empty for them.
        storage.write("data/users/alice/avatar.png", b"png").unwrap();
        storage
            .write(
                "data/users/alice/content.json",
                &serde_json::to_vec(&json!({
                    "files_optional": {
                        "avatar.png": { "size": 3, "sha512": XiteStorage::hash_bytes(b"png") }
                    }
                }))
                .unwrap(),
            )
            .unwrap();
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        let content = json!({
            "address": addr, "modified": 1.0, "files": {},
            "files_optional": {
                "a.bin": { "size": 4, "sha512": XiteStorage::hash_bytes(b"aaaa") },
                "b.bin": { "size": 8, "sha512": XiteStorage::hash_bytes(b"bbbbbbbb") },
            },
        });
        let state = AppState::new("test");
        state.add_xite(addr, XiteEntry { storage, content: Some(content),
                },
            ).await;
        // a.bin has served 12 bytes and finished at t=1000.
        {
            let mut xites = state.xites.write().await;
            let stat = xites
                .get_mut(addr.as_str())
                .unwrap()
                .settings
                .cache
                .optional_stats
                .entry("a.bin".into())
                .or_default();
            stat.uploaded = 12;
            stat.time_downloaded = 1000;
        }

        let list =
            state.optional_file_list(addr, "downloaded", "uploaded DESC", 0).await.unwrap();
        assert_eq!(list.len(), 3, "root files AND the child-declared avatar list");
        assert_eq!(list[0]["inner_path"], "a.bin");
        assert_eq!(list[0]["uploaded"], 12);
        assert_eq!(list[0]["time_downloaded"], 1000);
        assert_eq!(list[0]["peer"], 1, "downloaded here = one seeder");
        assert_eq!(list[1]["uploaded"], 0);
        // Non-stamped files fell back to the file's mtime for "Finished".
        assert!(list[1]["time_downloaded"].as_i64().unwrap() > 0);
        assert!(
            list.iter().any(|f| f["inner_path"] == "data/users/alice/avatar.png"),
            "per-user optional file present with its full inner path"
        );

        // Sorting by size ascending flips the order; limit truncates.
        let by_size = state.optional_file_list(addr, "all", "size", 0).await.unwrap();
        assert_eq!(by_size[0]["inner_path"], "data/users/alice/avatar.png");
        assert_eq!(
            state.optional_file_list(addr, "all", "size", 1).await.unwrap().len(),
            1
        );
    }

    /// The Files tab checks presence by stat (exists at the declared
    /// size), never by hashing contents - one render over a media xite
    /// must not re-read gigabytes. Proven by a file whose bytes do NOT
    /// match the declared sha512: a hashing check would call it missing.
    #[tokio::test]
    async fn optional_file_list_stats_files_instead_of_hashing_them() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        // Right size, wrong content for the declared hash.
        storage.write("movie.bin", b"xxxx").unwrap();
        // Present but at the wrong size.
        storage.write("short.bin", b"yy").unwrap();
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        let content = json!({
            "address": addr, "modified": 1.0, "files": {},
            "files_optional": {
                "movie.bin": { "size": 4, "sha512": XiteStorage::hash_bytes(b"AAAA") },
                "short.bin": { "size": 8, "sha512": XiteStorage::hash_bytes(b"yy") },
                "absent.bin": { "size": 4, "sha512": XiteStorage::hash_bytes(b"zzzz") },
            },
        });
        let state = AppState::new("test");
        state.add_xite(addr, XiteEntry { storage, content: Some(content),
                },
            ).await;

        let list = state.optional_file_list(addr, "all", "", 0).await.unwrap();
        let by_path = |p: &str| list.iter().find(|f| f["inner_path"] == p).unwrap().clone();
        assert_eq!(
            by_path("movie.bin")["is_downloaded"], true,
            "present at the declared size lists as downloaded - contents are never read"
        );
        assert_eq!(by_path("short.bin")["is_downloaded"], false, "wrong size = missing");
        assert_eq!(by_path("absent.bin")["is_downloaded"], false, "absent = missing");
    }

    /// The Bigfiles section's node contract: `filter: "downloaded,bigfile"`
    /// restricts to downloaded piecemap-declared files, bigfile rows carry
    /// the `pieces`/`pieces_downloaded`/`is_downloading` fields its Status
    /// column renders, and `filter_inner_path` is the search box's
    /// case-insensitive LIKE against the inner_path.
    #[tokio::test]
    async fn optional_file_list_bigfile_filter_piece_fields_and_search() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let big = vec![7u8; 2 * 1024 * 1024 + 5]; // 3 pieces at 1 MB
        storage.write("Movie.mp4", &big).unwrap();
        storage.write("song.ogg", b"lalala").unwrap();
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        let content = json!({
            "address": addr, "modified": 1.0, "files": {},
            "files_optional": {
                "Movie.mp4": {
                    "size": big.len(), "sha512": XiteStorage::hash_bytes(&big),
                    "piecemap": "Movie.mp4.piecemap.msgpack", "piece_size": 1024 * 1024,
                },
                "song.ogg": { "size": 6, "sha512": XiteStorage::hash_bytes(b"lalala") },
                "absent.bin": { "size": 4, "sha512": XiteStorage::hash_bytes(b"zzzz") },
            },
        });
        let state = AppState::new("test");
        state.add_xite(addr, XiteEntry { storage, content: Some(content),
                },
            ).await;
        // A bigfile only counts as downloaded with its completion stamp (its
        // sparse file sits at full size from the first piece).
        {
            let mut xites = state.xites.write().await;
            let stat = xites
                .get_mut(addr.as_str())
                .unwrap()
                .settings
                .cache
                .optional_stats
                .entry("Movie.mp4".into())
                .or_default();
            stat.time_downloaded = 1000;
        }

        // "downloaded,bigfile" = downloaded AND declared with a piecemap.
        let bigs =
            state.optional_file_list(addr, "downloaded,bigfile", "", 0).await.unwrap();
        assert_eq!(bigs.len(), 1, "the small file and the absent file are filtered out");
        assert_eq!(bigs[0]["inner_path"], "Movie.mp4");
        // The Status column's fields: full piece count, complete, idle.
        assert_eq!(bigs[0]["pieces"], 3);
        assert_eq!(bigs[0]["pieces_downloaded"], 3);
        assert_eq!(bigs[0]["is_downloading"], false);

        // Non-bigfile rows carry no piece fields (the UI guards on absence).
        let all = state.optional_file_list(addr, "downloaded", "", 0).await.unwrap();
        let song = all.iter().find(|f| f["inner_path"] == "song.ogg").unwrap();
        assert!(song.get("pieces").is_none());
        assert!(song.get("is_downloading").is_none());

        // The search box's LIKE pattern: case-insensitive substring.
        let hits = state
            .optional_file_list_filtered(addr, "all", "", 0, Some("%movie%"))
            .await
            .unwrap();
        assert_eq!(hits.len(), 1);
        assert_eq!(hits[0]["inner_path"], "Movie.mp4");
        assert!(state
            .optional_file_list_filtered(addr, "all", "", 0, Some("%nothere%"))
            .await
            .unwrap()
            .is_empty());
    }

    /// `filter_inner_path` promises SQL LIKE semantics: `%` any run, `_`
    /// exactly one character, case-insensitive.
    #[test]
    fn sql_like_matches_sql_semantics() {
        assert!(sql_like("%mov%", "data/Movie.mp4"));
        assert!(sql_like("%MOV%", "data/movie.mp4"));
        assert!(sql_like("%.mp4", "a/b.mp4"));
        assert!(!sql_like("%.mp4", "a/b.mp3"));
        assert!(sql_like("data/%", "data/x"));
        assert!(sql_like("exact", "EXACT"));
        assert!(!sql_like("exact", "exactly"));
        assert!(sql_like("fil_.bin", "file.bin"));
        assert!(!sql_like("fil_.bin", "fill2.bin"));
        assert!(sql_like("%a%b%", "xxaxxbxx"));
        assert!(!sql_like("%a%b%", "xxbxxa"), "order matters across % runs");
        assert!(sql_like("%", "anything"));
        assert!(sql_like("", ""));
        assert!(!sql_like("", "x"));
    }

    /// The bulk pin/unpin path behind the dashboard's selectbar: one call
    /// pins a whole batch, one call unpins it.
    #[tokio::test]
    async fn set_pins_applies_a_whole_batch() {
        let dir = tempdir().unwrap();
        let addr = &epix_crypt::privatekey_to_address(&epix_crypt::new_seed()).unwrap();
        let content = json!({
            "address": addr,
            "files_optional": {
                "a.bin": { "size": 4, "sha512": "aa" },
                "b.bin": { "size": 4, "sha512": "bb" },
            },
        });
        let state = AppState::new("test");
        state
            .add_xite(addr, XiteEntry { storage: XiteStorage::new(dir.path()), content: Some(content),
                },
            )
            .await;

        let paths = vec!["a.bin".to_string(), "b.bin".to_string()];
        state.set_pins(addr, &paths, true).await;
        let list = state.optional_file_list(addr, "all", "", 0).await.unwrap();
        assert!(list.iter().all(|f| f["is_pinned"] == true), "both pinned in one call");

        state.set_pins(addr, &paths, false).await;
        let list = state.optional_file_list(addr, "all", "", 0).await.unwrap();
        assert!(list.iter().all(|f| f["is_pinned"] == false));
    }

    /// The bulk optional download behind "Download and help distribute all
    /// files": enumerates the root's and child content.jsons' optional
    /// declarations, skips files already present at their declared size, and
    /// honors the optionalHelp directory prefix. The toggle also has to
    /// persist the flag - it used to be write-only in memory.
    #[tokio::test]
    async fn optional_download_targets_missing_declarations_and_toggle_sticks() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        storage.write("have.bin", b"12345").unwrap();
        storage
            .write(
                "data/users/alice/content.json",
                &serde_json::to_vec(&json!({
                    "files_optional": { "video.mp4": { "size": 99, "sha512": "aa" } }
                }))
                .unwrap(),
            )
            .unwrap();
        let content = json!({
            "address": "1Opt",
            "modified": 1.0,
            "files": {},
            "files_optional": {
                "have.bin": { "size": 5, "sha512": "ab" },
                "missing.bin": { "size": 7, "sha512": "cd" },
            },
        });
        let state = AppState::new("test");
        state.add_xite("1Opt", XiteEntry { storage, content: Some(content),
                },
            ).await;

        let mut missing: Vec<String> = state
            .missing_optional_files("1Opt", None)
            .await
            .into_iter()
            .map(|(p, _)| p)
            .collect();
        missing.sort();
        assert_eq!(missing, vec!["data/users/alice/video.mp4", "missing.bin"]);
        // A stale partial file (wrong size) counts as missing again.
        XiteStorage::new(dir.path()).write("have.bin", b"123").unwrap();
        assert_eq!(state.missing_optional_files("1Opt", None).await.len(), 3);
        // optionalHelp narrows to the directory prefix.
        let helped: Vec<String> = state
            .missing_optional_files("1Opt", Some("data/users/alice"))
            .await
            .into_iter()
            .map(|(p, _)| p)
            .collect();
        assert_eq!(helped, vec!["data/users/alice/video.mp4"]);

        // The toggle sets (and would persist) the flag, and reports unknown
        // xites; with no transport the spawned fetch is a clean no-op.
        assert!(state.set_autodownloadoptional("1Opt", true).await);
        assert!(!state.set_autodownloadoptional("1Nope", true).await);
        assert!(
            state.xites.read().await.get("1Opt").unwrap().settings.autodownloadoptional,
            "toggle must stick on the settings"
        );
        assert_eq!(state.download_optional_files("1Opt", None).await, (0, 0));
    }

    #[tokio::test]
    async fn optional_pass_announces_retries_and_stops_when_no_peers_exist() {
        // A pass with a transport but NO peers/trackers must: run round 1
        // (every file fails - nobody to ask), force-announce, find nothing,
        // stop early (no pointless further rounds), report every file failed,
        // and clear the progress snapshot. This is the offline-seeder path;
        // with peers the same loop retries up to 3 rounds.
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let content = json!({
            "address": "1Opt", "modified": 1.0, "files": {},
            "files_optional": {
                "a.bin": { "size": 5, "sha512": "aa" },
                "b.bin": { "size": 7, "sha512": "bb" },
            },
        });
        let state = AppState::new("test");
        state.add_xite("1Opt", XiteEntry { storage, content: Some(content),
                },
            ).await;
        state.set_transport(Arc::new(epix_transport::TcpTransport)).await;

        // Offline helper is a clean no-op: no trackers, no DHT hook -> 0 peers.
        assert_eq!(state.ensure_optional_peers("1Opt", true).await, 0);
        // Phase setter without a live snapshot must not panic.
        state.set_optional_phase("1Opt", "Announcing…").await;

        // The pass needs a standing mandate - BOTH toggles - or it cancels
        // immediately.
        state.set_download_optional("1Opt", true, false).await;
        state.set_autodownloadoptional("1Opt", true).await;
        let (fetched, failed) = state.download_optional_files("1Opt", None).await;
        assert_eq!((fetched, failed), (0, 2), "both files fail, counted once each");
        // Files are still missing and the background loop keeps chasing them,
        // so the panel STAYS - in a waiting state - instead of going blank.
        let progress = state.xite_info("1Opt").await["optional_progress"].clone();
        assert!(!progress.is_null(), "waiting panel persists after a failed pass");
        assert!(
            progress["status"].as_str().unwrap_or("").contains("retrying in background"),
            "waiting status names the background retry"
        );
        // EITHER toggle going off withdraws the mandate: the pass is a bulk
        // prefetch, and both switches must read as off switches for it.
        state.set_download_optional("1Opt", false, false).await;
        assert!(
            state.xite_info("1Opt").await["optional_progress"].is_null(),
            "download toggle off -> mandate gone, panel clears"
        );
    }

    #[tokio::test]
    async fn optional_retry_flagged_tracks_toggle_serving_and_missing() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let content = json!({
            "address": "1Opt", "modified": 1.0, "files": {},
            "files_optional": { "a.bin": { "size": 5, "sha512": "aa" } },
        });
        let state = AppState::new("test");
        // Exercise the toggle-off path: disable the node-wide ON defaults.
        state.config_set("download_optional_default", Value::from("false")).await;
        state.config_set("autodownloadoptional_default", Value::from("false")).await;
        state.add_xite("1Opt", XiteEntry { storage: storage.clone(), content: Some(content),
                },
            ).await;

        // Toggle off (and no optionalHelp) -> not watched, even with files missing.
        assert!(state.optional_retry_flagged().await.is_empty());

        // Whole-xite watching needs BOTH toggles: the prefetch mandate plus
        // the on-demand download permission. One alone is not enough.
        state.set_download_optional("1Opt", true, false).await;
        assert!(state.optional_retry_flagged().await.is_empty());
        state.set_autodownloadoptional("1Opt", true).await;
        let flagged = state.optional_retry_flagged().await;
        assert_eq!(flagged, vec![("1Opt".to_string(), None)]);
        assert!(state.optional_scope_owed("1Opt", &None).await > 0);

        // Paused xites are left alone.
        if let Some(x) = state.xites.write().await.get_mut("1Opt") {
            x.settings.serving = false;
        }
        assert!(state.optional_retry_flagged().await.is_empty());
        if let Some(x) = state.xites.write().await.get_mut("1Opt") {
            x.settings.serving = true;
        }

        // File arrives at the declared size -> scope complete (the loop then
        // parks the xite on its slow re-verify interval).
        storage.write("a.bin", b"12345").unwrap();
        assert_eq!(state.optional_scope_owed("1Opt", &None).await, 0);

        // An optionalHelp commitment (whole-xite mandate off) is watched
        // dir-scoped.
        state.set_download_optional("1Opt", false, false).await;
        if let Some(x) = state.xites.write().await.get_mut("1Opt") {
            x.settings.optional_help.insert("data/users/alice".into(), "1".into());
        }
        let flagged = state.optional_retry_flagged().await;
        assert_eq!(
            flagged,
            vec![("1Opt".to_string(), Some(vec!["data/users/alice".to_string()]))]
        );
    }

    /// The dashboard row's countdown counts what THIS node will actually
    /// download, which is a question about the user's settings - not about how
    /// many optional files the xite declares.
    #[tokio::test]
    async fn optional_owed_counts_only_what_the_user_opted_into() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let content = json!({
            "address": "1Owed", "modified": 1.0, "files": {},
            "files_optional": {
                "a.bin": { "size": 5, "sha512": "aa" },
                "b.bin": { "size": 5, "sha512": "bb" },
                "media/c.bin": { "size": 5, "sha512": "cc" },
            },
        });
        let state = AppState::new("test");
        state.config_set("download_optional_default", Value::from("false")).await;
        state.config_set("autodownloadoptional_default", Value::from("false")).await;
        state.add_xite("1Owed", XiteEntry { storage: storage.clone(), content: Some(content),
                },
            ).await;

        // Three optional files declared, none on disk - but the user never
        // asked for any of them, so the row has nothing to count down.
        assert_eq!(state.refresh_optional_owed("1Owed").await, 0);
        assert_eq!(state.xite_info("1Owed").await["optional_left"], 0);

        // Opting the whole xite in (both toggles - the prefetch mandate plus
        // the download permission) owes all three.
        state.set_download_optional("1Owed", true, false).await;
        state.set_autodownloadoptional("1Owed", true).await;
        assert_eq!(state.refresh_optional_owed("1Owed").await, 3);
        assert_eq!(state.xite_info("1Owed").await["optional_left"], 3);

        // Files landing count down.
        storage.write("a.bin", b"12345").unwrap();
        assert_eq!(state.refresh_optional_owed("1Owed").await, 2);

        // A directory commitment is scoped to that directory, not the xite.
        state.set_autodownloadoptional("1Owed", false).await;
        state.set_download_optional("1Owed", false, false).await;
        if let Some(x) = state.xites.write().await.get_mut("1Owed") {
            x.settings.optional_help.insert("media".into(), "1".into());
        }
        assert_eq!(state.refresh_optional_owed("1Owed").await, 1, "only media/c.bin");

        // Withdrawing the promise empties the countdown even though the file is
        // still missing - nothing is going to fetch it now.
        assert!(state.optional_help_remove("1Owed", "media").await);
        assert_eq!(state.xite_info("1Owed").await["optional_left"], 0);

        // A paused xite runs no passes, so it owes nothing either.
        state.set_download_optional("1Owed", true, false).await;
        state.set_autodownloadoptional("1Owed", true).await;
        assert_eq!(state.refresh_optional_owed("1Owed").await, 2);
        if let Some(x) = state.xites.write().await.get_mut("1Owed") {
            x.settings.serving = false;
        }
        assert_eq!(state.refresh_optional_owed("1Owed").await, 0);
    }

    #[tokio::test]
    async fn new_xites_inherit_the_node_wide_optional_defaults() {
        let content = json!({
            "address": "1New", "modified": 1.0, "files": {},
            "files_optional": { "a.bin": { "size": 5, "sha512": "aa" } },
        });

        // Defaults untouched -> download on demand yes, bulk prefetch NO.
        // Prefetch defaulting on meant opening a multi-GB xite silently
        // pulled its whole optional set.
        let state = AppState::new("test");
        let dir = tempdir().unwrap();
        state
            .add_xite(
                "1New",
                XiteEntry { storage: XiteStorage::new(dir.path()), content: Some(content.clone()),
                },
            )
            .await;
        {
            let xites = state.xites.read().await;
            let s = &xites.get("1New").unwrap().settings;
            assert!(s.download_optional, "download on by default");
            assert!(!s.autodownloadoptional, "prefetch off by default");
        }
        assert!(state.optional_fetch_allowed("1New").await);

        // Operator turned the prefetch default on.
        let state = AppState::new("test");
        let dir = tempdir().unwrap();
        state.config_set("autodownloadoptional_default", Value::from("true")).await;
        state
            .add_xite(
                "1New",
                XiteEntry { storage: XiteStorage::new(dir.path()), content: Some(content.clone()),
                },
            )
            .await;
        {
            let xites = state.xites.read().await;
            let s = &xites.get("1New").unwrap().settings;
            assert!(s.download_optional, "download default still on");
            assert!(s.autodownloadoptional, "prefetch default honored");
        }

        // Prefetch default ON implies downloading even if the download
        // default was turned off.
        let state = AppState::new("test");
        let dir = tempdir().unwrap();
        state.config_set("autodownloadoptional_default", Value::from("true")).await;
        state.config_set("download_optional_default", Value::from("false")).await;
        state
            .add_xite(
                "1New",
                XiteEntry { storage: XiteStorage::new(dir.path()), content: Some(content),
                },
            )
            .await;
        {
            let xites = state.xites.read().await;
            let s = &xites.get("1New").unwrap().settings;
            assert!(s.download_optional, "prefetch implies download");
            assert!(s.autodownloadoptional);
        }

        // The xite's own content.json can opt visitors OUT of prefetch even
        // when the node default is on.
        let optout = json!({
            "address": "1New", "modified": 1.0, "files": {},
            "files_optional": { "a.bin": { "size": 5, "sha512": "aa" } },
            "autodownloadoptional_default": false,
        });
        let state = AppState::new("test");
        let dir = tempdir().unwrap();
        state.config_set("autodownloadoptional_default", Value::from("true")).await;
        state
            .add_xite(
                "1New",
                XiteEntry { storage: XiteStorage::new(dir.path()), content: Some(optout),
                },
            )
            .await;
        {
            let xites = state.xites.read().await;
            let s = &xites.get("1New").unwrap().settings;
            assert!(!s.autodownloadoptional, "author opt-out beats the node default");
        }

        // The FRESH-CLONE path: the xite is added with NO content (the
        // manifest has not been fetched yet), inherits the operator's
        // prefetch-on default, and the author opt-out must then apply when
        // the first content.json commits.
        let state = AppState::new("test");
        let dir = tempdir().unwrap();
        state.config_set("autodownloadoptional_default", Value::from("true")).await;
        state
            .add_xite("1New", XiteEntry { storage: XiteStorage::new(dir.path()), content: None,
                },
            )
            .await;
        assert!(
            state.xites.read().await.get("1New").unwrap().settings.autodownloadoptional,
            "no manifest yet, operator default applies"
        );
        let cloned = json!({
            "address": "1New", "modified": 2.0, "files": {},
            "files_optional": { "a.bin": { "size": 5, "sha512": "aa" } },
            "autodownloadoptional_default": false,
        });
        state.update_content("1New", Some(cloned.clone())).await;
        assert!(
            !state.xites.read().await.get("1New").unwrap().settings.autodownloadoptional,
            "author opt-out applies when the cloned manifest lands"
        );
        // A LATER update must not undo the user's deliberate choice.
        state.set_autodownloadoptional("1New", true).await;
        state.update_content("1New", Some(cloned)).await;
        assert!(
            state.xites.read().await.get("1New").unwrap().settings.autodownloadoptional,
            "user toggle survives subsequent content updates"
        );

        // The author key can only lower the default: `true` in content.json
        // must NOT switch prefetch on against a node default of off.
        let optin = json!({
            "address": "1New", "modified": 1.0, "files": {},
            "files_optional": { "a.bin": { "size": 5, "sha512": "aa" } },
            "autodownloadoptional_default": true,
        });
        let state = AppState::new("test");
        let dir = tempdir().unwrap();
        state
            .add_xite(
                "1New",
                XiteEntry { storage: XiteStorage::new(dir.path()), content: Some(optin),
                },
            )
            .await;
        {
            let xites = state.xites.read().await;
            let s = &xites.get("1New").unwrap().settings;
            assert!(!s.autodownloadoptional, "author cannot force prefetch on");
        }
    }

