    #[tokio::test]
    async fn optional_progress_snapshot_surfaces_in_xite_info() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let content = json!({
            "address": "1Opt", "modified": 1.0, "files": {},
            "files_optional": { "a.bin": { "size": 10, "sha512": "aa" } },
        });
        let state = AppState::new("test");
        state.add_xite("1Opt", XiteEntry { storage, content: Some(content),
                },
            ).await;

        // Idle: no snapshot -> null in xite_info.
        assert!(state.xite_info("1Opt").await["optional_progress"].is_null());

        // Install a snapshot with one done + one active file mid-download.
        state
            .set_optional_progress(
                "1Opt",
                Some(OptionalProgress {
                    total_files: 2,
                    done_files: 0,
                    failed_files: 0,
                    bytes_total: 30,
                    bytes_done: 0,
                    current: String::new(),
                    status: String::new(),
                    files: vec![
                        OptionalProgressFile { path: "a.bin".into(), size: 10, state: OptFileState::Pending,
                        },
                        OptionalProgressFile { path: "b.bin".into(), size: 20, state: OptFileState::Pending,
                        },
                    ],
                }),
            )
            .await;
        state.mark_optional_file("1Opt", 0, OptFileState::Done, "b.bin").await;
        state.mark_optional_file("1Opt", 1, OptFileState::Active, "b.bin").await;
        state.bump_optional_progress("1Opt", 1, 0, 10).await;

        let info = state.xite_info("1Opt").await;
        let p = &info["optional_progress"];
        assert_eq!(p["total_files"], 2);
        assert_eq!(p["done_files"], 1);
        assert_eq!(p["current"], "b.bin");
        // 10 of 30 bytes -> ~33%.
        assert!((p["percent"].as_f64().unwrap() - 33.33).abs() < 0.1, "percent from bytes");
        assert_eq!(p["files"][0]["state"], "done");
        assert_eq!(p["files"][1]["state"], "active");

        // Clearing hides the panel again.
        state.set_optional_progress("1Opt", None).await;
        assert!(state.xite_info("1Opt").await["optional_progress"].is_null());
    }

    /// Build a xite of three 1000-byte optional files, with `retention` as
    /// the declared policy for all of them.
    async fn optional_cache_xite(
        dir: &std::path::Path,
        retention: &str,
    ) -> (Arc<AppState>, String) {
        let storage = XiteStorage::new(dir);
        for name in ["a.bin", "b.bin", "c.bin"] {
            storage.write(name, &vec![0u8; 1000]).unwrap();
        }
        let privatekey = epix_crypt::new_seed();
        let addr = epix_crypt::privatekey_to_address(&privatekey).unwrap();
        let sha512 = XiteStorage::hash_bytes(&vec![0u8; 1000]);
        let mut content = json!({
            "address": addr,
            "modified": 1.0,
            "distribution": { "default": {"unit": "package", "retention": retention} },
            "files": {},
            "files_optional": {
                "a.bin": { "size": 1000, "sha512": sha512.clone() },
                "b.bin": { "size": 1000, "sha512": sha512.clone() },
                "c.bin": { "size": 1000, "sha512": sha512 },
            }
        });
        epix_content::sign(&mut content, &privatekey).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&content).unwrap())
            .unwrap();
        let state = AppState::new("test");
        state.add_xite(&addr, XiteEntry { storage, content: Some(content),
                },
            ).await;
        (state, addr)
    }

    #[tokio::test]
    async fn optional_limit_evicts_oldest_unpinned_and_keeps_pinned() {
        let dir = tempdir().unwrap();
        // Declared `partial`: files fetched because you opened them, which is
        // exactly what this cap governs.
        let (state, addr) = optional_cache_xite(dir.path(), "partial").await;
        state.set_pin(&addr, "a.bin", true).await;

        // ~2791-byte cap: 3000 downloaded > cap, so eviction runs.
        state.set_optional_limit("0.0000026").await;
        let limit = state.optional_limit_bytes().await;
        assert!(limit > 1000 && limit < 3000, "limit was {limit}");

        let freed = state.enforce_optional_limit().await;
        assert!(freed > 0, "expected some bytes freed");
        // The pinned file is never evicted.
        assert!(dir.path().join("a.bin").exists());
        // Usage is back under the cap.
        let remaining: i64 = ["a.bin", "b.bin", "c.bin"]
            .iter()
            .filter(|n| dir.path().join(n).exists())
            .count() as i64
            * 1000;
        assert!(remaining <= limit, "remaining {remaining} > limit {limit}");
    }

    /// The cache cap governs CACHE. Content held under a retention
    /// commitment - which, since completing became the default, is most
    /// content - is not cache, and deleting it would only make the
    /// background completion pass fetch it straight back: the two would
    /// fight forever over the same files.
    #[tokio::test]
    async fn the_optional_cap_never_evicts_content_held_on_purpose() {
        let dir = tempdir().unwrap();
        let (state, _addr) = optional_cache_xite(dir.path(), "complete").await;

        // The same cap that evicted two files above.
        state.set_optional_limit("0.0000026").await;
        assert!(state.optional_limit_bytes().await < 3000);

        assert_eq!(state.enforce_optional_limit().await, 0, "committed content is not cache");
        for name in ["a.bin", "b.bin", "c.bin"] {
            assert!(dir.path().join(name).exists(), "{name} survives the cache cap");
        }
    }

    /// The same exemption via the reader's global setting rather than the
    /// owner's declaration: turning "keep a full copy" on must not leave the
    /// cache cap deleting the copies it is busy making.
    #[tokio::test]
    async fn full_retention_also_exempts_a_xite_that_declared_partial() {
        let dir = tempdir().unwrap();
        let (state, _addr) = optional_cache_xite(dir.path(), "partial").await;
        state.config_set("full_retention", Value::from("true")).await;

        state.set_optional_limit("0.0000026").await;
        assert_eq!(state.enforce_optional_limit().await, 0, "the reader chose to hold these");
        for name in ["a.bin", "b.bin", "c.bin"] {
            assert!(dir.path().join(name).exists());
        }
    }

    #[tokio::test]
    async fn muting_an_author_drops_their_rows_from_the_db() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        storage
            .write(
                "dbschema.json",
                br#"{ "db_name":"Blog","db_file":"db.db","version":2,
                     "maps": { "data/.*/data.json": { "to_table": [{"node":"posts","table":"post"}] } },
                     "tables": { "post": { "cols": [["post_id","INTEGER"],["title","TEXT"],["json_id","INTEGER"]] } } }"#,
            )
            .unwrap();
        storage.write("data/alice/data.json", br#"{ "posts": [ {"post_id":1,"title":"a"} ] }"#,
            ).unwrap();
        storage.write("data/mallory/data.json", br#"{ "posts": [ {"post_id":2,"title":"spam"} ] }"#,
            ).unwrap();

        let addr = "1MuteBlog";
        let state = AppState::new("test");
        state
            .add_xite(
                addr,
                XiteEntry {
                    storage,
                    content: Some(json!({
                        "files": {
                            "dbschema.json": {},
                            "data/alice/data.json": {},
                            "data/mallory/data.json": {}
                        }
                    })),
                },
            )
            .await;
        state.set_owned(addr, true).await;
        // Both authors' posts present initially.
        assert_eq!(state.db_query(addr, "SELECT COUNT(*) AS n FROM post", &Value::Null).await.unwrap()[0]["n"], 2);

        // Muting mallory rebuilds the db without their data file.
        state.mute_add("mallory", "mallory@cert", "spam").await;
        let rows = state.db_query(addr, "SELECT title FROM post", &Value::Null).await.unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0]["title"], "a");

        // Un-muting brings it back.
        state.mute_remove("mallory").await;
        assert_eq!(state.db_query(addr, "SELECT COUNT(*) AS n FROM post", &Value::Null).await.unwrap()[0]["n"], 2);
    }

