    #[tokio::test]
    async fn deleting_a_child_optional_edits_and_signs_the_exact_governing_manifest() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path().join("xite"));
        let key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&key).unwrap();
        let avatar = vec![0x51; 200 * 1024];
        let id = epix_blob::ObjId::of(&avatar);
        storage.write("child/avatar.jpg", &avatar).unwrap();
        let mut child = json!({
            "address": address,
            "inner_path": "child/content.json",
            "modified": 1.0,
            "files": {},
            "files_optional": {
                "avatar.jpg": {
                    "size": avatar.len(),
                    "sha512": XiteStorage::hash_bytes(&avatar),
                    "b3": id.to_string(),
                }
            },
        });
        epix_content::sign(&mut child, &key).unwrap();
        storage
            .write("child/content.json", &serde_json::to_vec(&child).unwrap())
            .unwrap();
        let mut root = json!({
            "address": address,
            "modified": 1.0,
            "files": {},
            "includes": { "child/content.json": {} },
        });
        epix_content::sign(&mut root, &key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root).unwrap())
            .unwrap();

        let state = AppState::new("test");
        state
            .add_xite(
                &address,
                XiteEntry {
                    storage: storage.clone(),
                    content: Some(root),
                },
            )
            .await;
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                dir.path().join("store"),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().to_path_buf()),
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        state.set_edx_store(store.clone()).await.unwrap();
        assert!(store.contains(id).unwrap());
        assert_eq!(
            state.content_inner_path(&address, "child/avatar.jpg").await,
            "child/content.json",
        );

        state
            .delete_file(&address, "child/avatar.jpg", None)
            .await
            .unwrap();
        let draft: Value = serde_json::from_slice(
            &storage.read("child/content.json").unwrap(),
        )
        .unwrap();
        assert!(draft["files_optional"].get("avatar.jpg").is_none());
        state
            .sign_user_content(
                &address,
                "child/content.json",
                Some(key),
                None,
            )
            .await
            .unwrap();
        let signed: Value = serde_json::from_slice(
            &storage.read("child/content.json").unwrap(),
        )
        .unwrap();
        assert!(signed["files_optional"].get("avatar.jpg").is_none());
        assert!(
            !store.contains(id).unwrap(),
            "revoked child optional object remained remotely servable",
        );
    }

    #[tokio::test]
    async fn root_sign_does_not_adopt_a_duplicate_canonical_on_another_storage_root() {
        let dir = tempdir().unwrap();
        let key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&key).unwrap();
        let storage_a = XiteStorage::new(dir.path().join("a"));
        let storage_b = XiteStorage::new(dir.path().join("b"));
        let mut root_a = json!({
            "address": address,
            "modified": 1.0,
            "title": "root a",
            "files": {},
        });
        epix_content::sign(&mut root_a, &key).unwrap();
        let mut root_b = json!({
            "address": address,
            "modified": 7.0,
            "title": "root b",
            "files": {},
        });
        epix_content::sign(&mut root_b, &key).unwrap();
        let root_b_bytes = serde_json::to_vec(&root_b).unwrap();
        storage_a
            .write("content.json", &serde_json::to_vec(&root_a).unwrap())
            .unwrap();
        storage_b.write("content.json", &root_b_bytes).unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                "a.epix",
                XiteEntry {
                    storage: storage_a,
                    content: Some(root_a),
                },
            )
            .await;
        state
            .add_xite(
                "b.epix",
                XiteEntry {
                    storage: storage_b.clone(),
                    content: Some(root_b.clone()),
                },
            )
            .await;

        state.sign_xite("a.epix", &key).await.unwrap();
        let managed_b = state
            .xites
            .read()
            .await
            .get("b.epix")
            .and_then(|xite| xite.content.clone())
            .unwrap();
        assert_eq!(managed_b, root_b);
        assert_eq!(storage_b.read("content.json").unwrap(), root_b_bytes);
    }

