    #[tokio::test]
    async fn bigfile_info_and_range_read() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let big = vec![7u8; 2 * 1024 * 1024 + 5]; // just over 2 MB
        let privatekey = &epix_crypt::new_seed();
        let addr = &epix_crypt::privatekey_to_address(privatekey).unwrap();
        let mut content = json!({
            "address": addr,
            "modified": 1.0,
            "files": {},
            "files_optional": { "movie.mp4": {
                "size": big.len(), "sha512": XiteStorage::hash_bytes(&big),
                "piecemap": "movie.mp4.piecemap.msgpack", "piece_size": 1024 * 1024,
            } },
        });
        epix_content::sign(&mut content, privatekey).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&content).unwrap())
            .unwrap();
        let state = AppState::new("test");
        state.add_xite(addr, XiteEntry { storage, content: Some(content),
                },
            ).await;
        state.write_file(addr, "movie.mp4", &big).await.unwrap();

        // optionalFileInfo carries the Bigfile piece layout.
        let info = state.optional_file_info(addr, "movie.mp4").await.unwrap();
        assert_eq!(info["is_bigfile"], true);
        assert_eq!(info["piece_size"], 1024 * 1024);
        assert_eq!(info["piece_num"], 3); // ceil((2MB+5)/1MB)
        assert_eq!(info["piecemap"], "movie.mp4.piecemap.msgpack");

        // Range read returns exactly the requested window from the right offset.
        let chunk = state.read_file_range(addr, "movie.mp4", 1024 * 1024, 128).await.unwrap();
        assert_eq!(chunk.len(), 128);
        assert!(chunk.iter().all(|&b| b == 7));

        // A small optional file is not a bigfile.
        let small = json!({ "files_optional": { "a.txt": { "size": 10, "sha512": "x" } } });
        state.add_xite("small", XiteEntry { storage: XiteStorage::new(dir.path().join("s")), content: Some(small),
                },
            ).await;
    }

    /// Optional-file bookkeeping over EDX: materializing an optional file (the
    /// verified-streaming path's terminal step) advertises it in our hashfield,
    /// counts its bytes toward optional_downloaded, and stamps its finished
    /// time - so an EDX-fetched optional file seeds exactly like a msgpack one.
    /// A re-materialize (resync/refetch) must not double-count the bytes.
    #[tokio::test]
    async fn edx_materialize_advertises_and_stamps_an_optional_file() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let key = epix_crypt::new_seed();
        let addr = epix_crypt::privatekey_to_address(&key).unwrap();
        let bytes = b"an avatar fetched over EDX".to_vec();
        let sha = XiteStorage::hash_bytes(&bytes);
        let id = epix_blob::ObjId::of(&bytes);
        let mut content = json!({
            "address": addr,
            "modified": 1,
            "files": {},
            "files_optional": { "avatar.png": {
                "size": bytes.len(), "sha512": sha, "b3": id.to_string()
            } },
        });
        epix_content::sign(&mut content, &key).unwrap();
        storage
            .write("content.json", epix_content::dumps_content(&content).as_bytes(),
            )
            .unwrap();
        let state = AppState::new("test");
        state.add_xite(&addr, XiteEntry { storage, content: Some(content),
                },
            ).await;

        state
            .edx_materialize_file(&addr, "avatar.png", id, &bytes, None)
            .await
            .unwrap();
        {
            let xites = state.xites.read().await;
            let x = xites.get(&addr).unwrap();
            assert_eq!(x.storage.read("avatar.png").unwrap(), bytes, "verified bytes on disk");
            assert!(x.hashfield.has_hash(&sha), "hashfield advertises the optional file");
            assert_eq!(x.settings.optional_downloaded, bytes.len() as i64, "bytes counted");
            assert!(
                x.settings.cache.optional_stats.get("avatar.png").unwrap().time_downloaded > 0,
                "finished time stamped",
            );
        }

        // Idempotent: a second materialize (a resync re-fetch) must not double
        // the downloaded-bytes counter.
        state
            .edx_materialize_file(&addr, "avatar.png", id, &bytes, None)
            .await
            .unwrap();
        {
            let xites = state.xites.read().await;
            let x = xites.get(&addr).unwrap();
            assert_eq!(
                x.settings.optional_downloaded,
                bytes.len() as i64,
                "re-materialize must not double-count",
            );
        }
    }

    /// A required (non-optional) file materialized over EDX does none of the
    /// optional bookkeeping - optional_downloaded stays zero and no finished
    /// stamp is written, so the Files tab does not show a core file as an
    /// "optional download".
    #[tokio::test]
    async fn edx_materialize_leaves_a_required_file_out_of_optional_bookkeeping() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let key = epix_crypt::new_seed();
        let addr = epix_crypt::privatekey_to_address(&key).unwrap();
        let bytes = b"<h1>index</h1>".to_vec();
        let id = epix_blob::ObjId::of(&bytes);
        let mut content = json!({
            "address": addr,
            "modified": 1,
            "files": { "index.html": {
                "size": bytes.len(), "sha512": XiteStorage::hash_bytes(&bytes),
                "b3": id.to_string()
            } },
            "files_optional": {},
        });
        epix_content::sign(&mut content, &key).unwrap();
        storage
            .write("content.json", epix_content::dumps_content(&content).as_bytes(),
            )
            .unwrap();
        let state = AppState::new("test");
        state.add_xite(&addr, XiteEntry { storage, content: Some(content),
                },
            ).await;

        state
            .edx_materialize_file(&addr, "index.html", id, &bytes, None)
            .await
            .unwrap();
        let xites = state.xites.read().await;
        let x = xites.get(&addr).unwrap();
        assert_eq!(x.storage.read("index.html").unwrap(), bytes);
        assert_eq!(x.settings.optional_downloaded, 0, "required file is not optional");
        assert!(x.settings.cache.optional_stats.get("index.html").is_none(), "no optional stamp");
    }

    #[tokio::test]
    async fn stale_root_materializer_cannot_overwrite_a_newer_manifest_file() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&key).unwrap();
        let old = b"old root bytes".to_vec();
        let new = b"new root bytes".to_vec();
        let old_id = epix_blob::ObjId::of(&old);
        let new_id = epix_blob::ObjId::of(&new);
        let mut old_content = json!({
            "address": address,
            "modified": 1,
            "files": { "asset.bin": {
                "size": old.len(), "sha512": XiteStorage::hash_bytes(&old),
                "b3": old_id.to_string()
            } }
        });
        epix_content::sign(&mut old_content, &key).unwrap();
        storage
            .write("content.json", epix_content::dumps_content(&old_content).as_bytes(),
            )
            .unwrap();
        storage.write("asset.bin", &old).unwrap();
        let state = AppState::new("test");
        state
            .add_xite(&address, XiteEntry { storage: storage.clone(), content: Some(old_content),
                },
            )
            .await;

        let guard = state
            .merge_path_lock(&address, "content.json")
            .lock_owned()
            .await;
        let task = {
            let state = state.clone();
            let old = old.clone();
            let address = address.clone();
            tokio::spawn(async move {
                state
                    .edx_materialize_file(&address, "asset.bin", old_id, &old, None)
                    .await
            })
        };
        tokio::task::yield_now().await;
        assert!(!task.is_finished(), "old materializer did not wait for the manifest lock");

        let mut new_content = json!({
            "address": address,
            "modified": 2,
            "files": { "asset.bin": {
                "size": new.len(), "sha512": XiteStorage::hash_bytes(&new),
                "b3": new_id.to_string()
            } }
        });
        epix_content::sign(&mut new_content, &key).unwrap();
        storage.write("asset.bin", &new).unwrap();
        storage
            .write("content.json", epix_content::dumps_content(&new_content).as_bytes(),
            )
            .unwrap();
        state.update_content(&address, Some(new_content)).await;
        state
            .refresh_verified_object_paths(&address, &address, &storage)
            .await
            .unwrap();
        drop(guard);

        assert!(task.await.unwrap().is_err(), "stale root object was accepted");
        assert_eq!(storage.read("asset.bin").unwrap(), new);
    }

    #[tokio::test]
    async fn stale_child_materializer_cannot_overwrite_a_newer_manifest_file() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&key).unwrap();
        let child = "data/users/alice/content.json";
        let file = "data/users/alice/avatar.bin";
        let old = b"old child bytes".to_vec();
        let new = b"new child bytes".to_vec();
        let old_id = epix_blob::ObjId::of(&old);
        let new_id = epix_blob::ObjId::of(&new);
        let mut root = json!({
            "address": address,
            "modified": 1,
            "files": {},
            "includes": { (child): { "signers": [address], "signers_required": 1 } }
        });
        epix_content::sign(&mut root, &key).unwrap();
        let mut old_content = json!({
            "address": address,
            "inner_path": child,
            "modified": 1,
            "files": { "avatar.bin": {
                "size": old.len(), "sha512": XiteStorage::hash_bytes(&old),
                "b3": old_id.to_string()
            } }
        });
        epix_content::sign(&mut old_content, &key).unwrap();
        storage
            .write("content.json", epix_content::dumps_content(&root).as_bytes(),
            )
            .unwrap();
        storage
            .write(child, epix_content::dumps_content(&old_content).as_bytes())
            .unwrap();
        storage.write(file, &old).unwrap();
        let state = AppState::new("test");
        state
            .add_xite(&address, XiteEntry { storage: storage.clone(), content: Some(root),
                },
            )
            .await;

        let guard = state.merge_path_lock(&address, child).lock_owned().await;
        let task = {
            let state = state.clone();
            let old = old.clone();
            let address = address.clone();
            tokio::spawn(async move {
                state.edx_materialize_file(&address, file, old_id, &old, None).await
            })
        };
        tokio::task::yield_now().await;
        assert!(!task.is_finished(), "old child materializer did not wait for the lock");

        let mut new_content = json!({
            "address": address,
            "inner_path": child,
            "modified": 2,
            "files": { "avatar.bin": {
                "size": new.len(), "sha512": XiteStorage::hash_bytes(&new),
                "b3": new_id.to_string()
            } }
        });
        epix_content::sign(&mut new_content, &key).unwrap();
        storage.write(file, &new).unwrap();
        storage
            .write(child, epix_content::dumps_content(&new_content).as_bytes())
            .unwrap();
        state
            .refresh_verified_object_paths(&address, &address, &storage)
            .await
            .unwrap();
        drop(guard);

        assert!(task.await.unwrap().is_err(), "stale child object was accepted");
        assert_eq!(storage.read(file).unwrap(), new);
    }

    #[tokio::test]
    async fn revoked_child_cannot_resolve_or_materialize_from_stale_manifest_bytes() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&key).unwrap();
        let child = "data/users/alice/content.json";
        let file = "data/users/alice/avatar.bin";
        let bytes = b"revoked avatar".to_vec();
        let id = epix_blob::ObjId::of(&bytes);
        let mut root_v1 = json!({
            "address": address,
            "modified": 1,
            "files": {},
            "includes": { (child): { "signers": [address], "signers_required": 1 } }
        });
        epix_content::sign(&mut root_v1, &key).unwrap();
        let mut child_content = json!({
            "address": address,
            "inner_path": child,
            "modified": 1,
            "files": { "avatar.bin": {
                "size": bytes.len(),
                "sha512": XiteStorage::hash_bytes(&bytes),
                "b3": id.to_string()
            } }
        });
        epix_content::sign(&mut child_content, &key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root_v1).unwrap())
            .unwrap();
        storage
            .write(child, &serde_json::to_vec(&child_content).unwrap())
            .unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                &address,
                XiteEntry {
                    storage: storage.clone(),
                    content: Some(root_v1),
                },
            )
            .await;
        assert_eq!(state.edx_resolve(&address, file).await, Some((id, bytes.len() as u64)));

        let child_guard = state.merge_path_lock(&address, child).lock_owned().await;
        let task = {
            let state = state.clone();
            let address = address.clone();
            let bytes = bytes.clone();
            tokio::spawn(async move {
                state
                    .edx_materialize_file(&address, file, id, &bytes, None)
                    .await
            })
        };
        tokio::task::yield_now().await;
        assert!(!task.is_finished());

        let mut root_v2 = json!({
            "address": address,
            "modified": 2,
            "files": {}
        });
        epix_content::sign(&mut root_v2, &key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root_v2).unwrap())
            .unwrap();
        state.update_content(&address, Some(root_v2)).await;
        state
            .refresh_verified_object_paths(&address, &address, &storage)
            .await
            .unwrap();
        assert!(storage.exists(child), "revoked manifest bytes remain on disk");
        assert_eq!(state.edx_resolve(&address, file).await, None);
        let _ = storage.delete(file);
        drop(child_guard);

        assert!(task.await.unwrap().is_err());
        assert!(!storage.exists(file), "revoked file was recreated");
    }

    #[tokio::test]
    async fn stale_shard_materializer_cannot_overwrite_a_newer_descriptor() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&key).unwrap();
        let path = "private/secret.txt";
        let old = b"old secret".to_vec();
        let new = b"new secret".to_vec();
        let old_entry = json!({ "size": old.len(), "mode": 0, "chunks": [{
            "ph": "11".repeat(32), "ca": "22".repeat(32), "len": old.len(), "cs": 32
        }] });
        let new_entry = json!({ "size": new.len(), "mode": 0, "chunks": [{
            "ph": "33".repeat(32), "ca": "44".repeat(32), "len": new.len(), "cs": 32
        }] });
        let mut old_content = json!({
            "address": address,
            "modified": 1,
            "files_shard": { (path): old_entry.clone() }
        });
        epix_content::sign(&mut old_content, &key).unwrap();
        storage
            .write("content.json", epix_content::dumps_content(&old_content).as_bytes(),
            )
            .unwrap();
        storage.write(path, &old).unwrap();
        let state = AppState::new("test");
        state
            .add_xite(&address, XiteEntry { storage: storage.clone(), content: Some(old_content),
                },
            )
            .await;

        let guard = state
            .merge_path_lock(&address, "content.json")
            .lock_owned()
            .await;
        let task = {
            let state = state.clone();
            let old = old.clone();
            let old_entry = old_entry.clone();
            let address = address.clone();
            tokio::spawn(async move {
                state
                    .edx_materialize_shard_file(&address, path, &old, &old_entry, None)
                    .await
            })
        };
        tokio::task::yield_now().await;
        assert!(!task.is_finished(), "old shard materializer did not wait for the lock");

        let mut new_content = json!({
            "address": address,
            "modified": 2,
            "files_shard": { (path): new_entry }
        });
        epix_content::sign(&mut new_content, &key).unwrap();
        storage.write(path, &new).unwrap();
        storage
            .write("content.json", epix_content::dumps_content(&new_content).as_bytes(),
            )
            .unwrap();
        state.update_content(&address, Some(new_content)).await;
        state
            .refresh_verified_object_paths(&address, &address, &storage)
            .await
            .unwrap();
        drop(guard);

        assert!(task.await.unwrap().is_err(), "stale shard descriptor was accepted");
        assert_eq!(storage.read(path).unwrap(), new);
    }

    /// A version-3 merger xite (schema + `Merger:EpixPost` permission, no own
    /// data). Returns the live temp dir (keep it in scope - dropping it deletes
    /// the files), the state, and the merger address.
    async fn new_v3_merger() -> (tempfile::TempDir, std::sync::Arc<AppState>, String) {
        let dir = tempdir().unwrap();
        let state = AppState::new("test");
        let key = epix_crypt::new_seed();
        let merger = epix_crypt::privatekey_to_address(&key).unwrap();
        let mstore = XiteStorage::new(dir.path().join("merger"));
        let schema = br#"{ "db_name":"Merger","db_file":"db.db","version":3,
                     "maps": {
                       ".+/data/.*/data.json": { "to_table": [{"node":"posts","table":"post"}] },
                       ".+/data/.*/posts.json": { "to_table": [{"node":"post","table":"post"}], "file_name":"data.json", "fold_crdt":"post" }
                     },
                     "tables": { "post": { "cols": [["post_id","INTEGER"],["title","TEXT"],["body","TEXT"],["json_id","INTEGER"]] } } }"#;
        mstore
            .write("dbschema.json", schema)
            .unwrap();
        let mut root = json!({
            "address": merger,
            "modified": 1.0,
            "files": { "dbschema.json": {
                "size": schema.len(), "sha512": XiteStorage::hash_bytes(schema)
            } }
        });
        epix_content::sign(&mut root, &key).unwrap();
        mstore
            .write("content.json", epix_content::dumps_content(&root).as_bytes())
            .unwrap();
        state.add_xite(&merger, XiteEntry { storage: mstore, content: Some(root),
                },
            ).await;
        state.add_permission(&merger, "Merger:EpixPost").await;
        (dir, state, merger)
    }

    /// [`new_v3_merger`] plus one merged xite holding a single post ("hello"),
    /// with the merger db rebuilt and asserted populated - the starting point
    /// for the tests that then perturb the merger and check its db refills.
    async fn merger_with_one_post() -> (tempfile::TempDir, std::sync::Arc<AppState>, String) {
        let (dir, state, merger) = new_v3_merger().await;
        let key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&key).unwrap();
        let s = XiteStorage::new(dir.path().join("source"));
        let data = br#"{ "posts": [ {"post_id":1,"title":"hello"} ] }"#;
        s.write("data/u/data.json", data).unwrap();
        let mut root = json!({
            "address": address,
            "modified": 1.0,
            "merged_type": "EpixPost",
            "files": { "data/u/data.json": {
                "size": data.len(), "sha512": XiteStorage::hash_bytes(data)
            } }
        });
        epix_content::sign(&mut root, &key).unwrap();
        s.write("content.json", epix_content::dumps_content(&root).as_bytes())
            .unwrap();
        state
            .add_xite(&address, XiteEntry { storage: s, content: Some(root),
                },
            )
            .await;
        state.rebuild_merger_dbs().await;
        let rows = state.db_query(&merger, "SELECT title FROM post", &Value::Null).await.unwrap();
        assert_eq!(rows.len(), 1, "merger db populated before the refill trigger");
        (dir, state, merger)
    }

    #[tokio::test]
    async fn v3_merger_db_aggregates_merged_xites() {
        let (dir, state, merger) = new_v3_merger().await;

        // Two merged xites of that type, each with a post.
        let mut expected = Vec::new();
        for title in ["from A", "from B"] {
            let key = epix_crypt::new_seed();
            let address = epix_crypt::privatekey_to_address(&key).unwrap();
            let s = XiteStorage::new(dir.path().join(&address));
            let data = format!(r#"{{ "posts": [ {{"post_id":1,"title":"{title}"}} ] }}"#);
            s.write(
                "data/u/data.json",
                data.as_bytes(),
            )
            .unwrap();
            let mut root = json!({
                "address": address,
                "modified": 1.0,
                "merged_type": "EpixPost",
                "files": { "data/u/data.json": {
                    "size": data.len(), "sha512": XiteStorage::hash_bytes(data.as_bytes())
                } }
            });
            epix_content::sign(&mut root, &key).unwrap();
            s.write("content.json", epix_content::dumps_content(&root).as_bytes())
                .unwrap();
            state
                .add_xite(&address, XiteEntry { storage: s, content: Some(root),
                    },
                )
                .await;
            expected.push((address, title.to_string()));
        }
        expected.sort();

        state.rebuild_merger_dbs().await;

        // One query over the merger db returns rows from BOTH xites, tagged with
        // their xite via the json table (the point of a version-3 merger db).
        let rows = state
            .db_query(
                &merger,
                "SELECT json.site AS site, post.title AS title FROM post LEFT JOIN json USING (json_id) ORDER BY json.site",
                &Value::Null,
            )
            .await
            .unwrap();
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0]["site"], expected[0].0);
        assert_eq!(rows[0]["title"], expected[0].1);
        assert_eq!(rows[1]["site"], expected[1].0);
        assert_eq!(rows[1]["title"], expected[1].1);
    }

    #[tokio::test]
    async fn rebuild_merger_dbs_excludes_rows_from_a_revoked_stale_child() {
        let dir = tempdir().unwrap();
        let state = AppState::new("test");
        let merger_key = epix_crypt::new_seed();
        let merger = epix_crypt::privatekey_to_address(&merger_key).unwrap();
        let merger_storage = XiteStorage::new(dir.path().join("merger"));
        let schema = br#"{ "db_name":"Merger","db_file":"db.db","version":3,
            "maps": { ".+/data/users/.+/data.json": {
                "to_table": [{"node":"posts","table":"post"}] } },
            "tables": { "post": { "cols": [
                ["post_id","INTEGER"],["title","TEXT"],["json_id","INTEGER"]] } } }"#;
        merger_storage.write("dbschema.json", schema).unwrap();
        let mut merger_root = json!({
            "address": merger,
            "modified": 1.0,
            "files": { "dbschema.json": {
                "size": schema.len(), "sha512": XiteStorage::hash_bytes(schema)
            } }
        });
        epix_content::sign(&mut merger_root, &merger_key).unwrap();
        merger_storage
            .write(
                "content.json",
                epix_content::dumps_content(&merger_root).as_bytes(),
            )
            .unwrap();
        state
            .add_xite(
                &merger,
                XiteEntry {
                    storage: merger_storage,
                    content: Some(merger_root),
                },
            )
            .await;
        state.add_permission(&merger, "Merger:EpixPost").await;

        let source_key = epix_crypt::new_seed();
        let source = epix_crypt::privatekey_to_address(&source_key).unwrap();
        let source_storage = XiteStorage::new(dir.path().join("source"));
        let child_path = "data/users/alice/content.json";
        let data = br#"{ "posts": [ {"post_id":1,"title":"revoked"} ] }"#;
        source_storage
            .write("data/users/alice/data.json", data)
            .unwrap();
        let mut child = json!({
            "address": source,
            "inner_path": child_path,
            "modified": 1.0,
            "files": { "data.json": {
                "size": data.len(), "sha512": XiteStorage::hash_bytes(data)
            } }
        });
        epix_content::sign(&mut child, &source_key).unwrap();
        source_storage
            .write(child_path, epix_content::dumps_content(&child).as_bytes())
            .unwrap();
        let mut source_v1 = json!({
            "address": source,
            "modified": 1.0,
            "merged_type": "EpixPost",
            "files": {},
            "includes": { (child_path): {
                "signers": [source], "signers_required": 1
            } }
        });
        epix_content::sign(&mut source_v1, &source_key).unwrap();
        source_storage
            .write(
                "content.json",
                epix_content::dumps_content(&source_v1).as_bytes(),
            )
            .unwrap();
        state
            .add_xite(
                &source,
                XiteEntry {
                    storage: source_storage.clone(),
                    content: Some(source_v1),
                },
            )
            .await;
        state.rebuild_merger_dbs().await;
        let rows = state
            .db_query(&merger, "SELECT title FROM post", &Value::Null)
            .await
            .unwrap();
        assert_eq!(rows.len(), 1);

        let started = Arc::new(tokio::sync::Notify::new());
        let release = Arc::new(tokio::sync::Semaphore::new(0));
        *MERGER_DB_BEFORE_INSTALL_PAUSE
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) =
            Some((started.clone(), release.clone()));
        let rebuild = {
            let state = state.clone();
            tokio::spawn(async move { state.rebuild_merger_dbs().await })
        };
        started.notified().await;
        MERGER_DB_BEFORE_INSTALL_PAUSE
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .take();
        let mut source_v2 = json!({
            "address": source,
            "modified": 2.0,
            "merged_type": "EpixPost",
            "files": {},
        });
        epix_content::sign(&mut source_v2, &source_key).unwrap();
        source_storage
            .write(
                "content.json",
                epix_content::dumps_content(&source_v2).as_bytes(),
            )
            .unwrap();
        state.update_content(&source, Some(source_v2)).await;
        state
            .refresh_verified_object_paths(&source, &source, &source_storage)
            .await
            .unwrap();
        assert!(source_storage.exists(child_path));
        assert!(source_storage.exists("data/users/alice/data.json"));
        let source_tree = state.tree_mutation_lock(&source).lock_owned().await;
        release.add_permits(1);
        tokio::time::sleep(std::time::Duration::from_millis(30)).await;
        assert!(!rebuild.is_finished(), "rebuild abandoned a contended authority tree");
        drop(source_tree);
        rebuild.await.unwrap();

        let rows = state
            .db_query(&merger, "SELECT title FROM post", &Value::Null)
            .await
            .unwrap();
        assert!(rows.is_empty(), "revoked child rows survived the merger rebuild");
        state
            .ingest_file_from(&source, "data/users/alice/data.json", None)
            .await;
        let rows = state
            .db_query(&merger, "SELECT title FROM post", &Value::Null)
            .await
            .unwrap();
        assert!(rows.is_empty(), "stale ingest reinserted a revoked merger row");
    }

    #[tokio::test]
    async fn db_rebuild_refills_a_merger_db() {
        let (_dir, state, merger) = merger_with_one_post().await;

        // dbRebuild/dbReload (and a mute change) call rebuild_xite_db, which
        // replaces a version-3 merger db with a fresh EMPTY one - it must be
        // refilled from the merged xites, not left empty until the next
        // restart (the merger page would show no posts).
        assert!(state.rebuild_xite_db(&merger).await);
        let rows =
            state.db_query(&merger, "SELECT title FROM post", &Value::Null).await.unwrap();
        assert_eq!(rows.len(), 1, "merger db refilled after dbRebuild");
        assert_eq!(rows[0]["title"], "hello");
    }

    #[tokio::test]
    async fn removing_merger_permission_clears_existing_rows() {
        let (_dir, state, merger) = merger_with_one_post().await;

        let grants = state.grants.write().await;
        let remove = {
            let state = state.clone();
            let merger = merger.clone();
            tokio::spawn(async move {
                state.remove_permission(&merger, "Merger:EpixPost").await;
            })
        };
        tokio::time::timeout(std::time::Duration::from_secs(1), async {
            while !state.merger_types(&merger).await.is_empty() {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("permission mutation completed before the persistence wait");
        remove.abort();
        let _ = remove.await;
        drop(grants);

        let rows = state
            .db_query(&merger, "SELECT title FROM post", &Value::Null)
            .await
            .unwrap();
        assert!(
            rows.is_empty(),
            "cancelled permission removal left revoked merger rows queryable"
        );

        state.rebuild_merger_dbs().await;
        let rows = state
            .db_query(&merger, "SELECT title FROM post", &Value::Null)
            .await
            .unwrap();
        assert!(
            rows.is_empty(),
            "an explicit rebuild restored rows after permission revocation"
        );
    }

    #[tokio::test]
    async fn db_query_discards_a_detached_pre_revocation_handle() {
        let (_dir, state, merger) = merger_with_one_post().await;
        let started = Arc::new(tokio::sync::Notify::new());
        let release = Arc::new(tokio::sync::Semaphore::new(0));
        *DB_QUERY_AFTER_RECEIPT_PAUSE
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) =
            Some((started.clone(), release.clone()));
        let query = {
            let state = state.clone();
            let merger = merger.clone();
            tokio::spawn(async move {
                state
                    .db_query(&merger, "SELECT title FROM post", &Value::Null)
                    .await
            })
        };
        started.notified().await;
        DB_QUERY_AFTER_RECEIPT_PAUSE
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .take();
        state.remove_permission(&merger, "Merger:EpixPost").await;
        release.add_permits(1);

        let result = query.await.unwrap();
        assert!(
            result.is_err() || result.as_ref().is_ok_and(Vec::is_empty),
            "query returned rows from a database retired by permission revocation"
        );
    }

