    #[tokio::test]
    async fn db_merge_snapshot_ignores_an_unrelated_lexical_parent() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let good_key = epix_crypt::new_seed();
        let canonical = epix_crypt::privatekey_to_address(&good_key).unwrap();
        let attacker_key = epix_crypt::new_seed();
        let attacker = epix_crypt::privatekey_to_address(&attacker_key).unwrap();
        let forged = signed_merge_record(&attacker_key, "forged");
        storage
            .write(
                "a/b/posts.json",
                &serde_json::to_vec(&epix_content::make_container(vec![forged])).unwrap(),
            )
            .unwrap();
        let authority = VerifiedDbAuthority {
            manifests: vec![
                VerifiedManifestUnit {
                    inner_path: "content.json".into(),
                    content: json!({
                        "includes": {
                            "a/b/content.json": { "signers": [canonical.clone()] }
                        }
                    }),
                },
                VerifiedManifestUnit {
                    inner_path: "a/content.json".into(),
                    content: json!({
                        "includes": {
                            "b/content.json": { "signers": [attacker.clone()] }
                        }
                    }),
                },
                VerifiedManifestUnit {
                    inner_path: "a/b/content.json".into(),
                    content: json!({
                        "files_merged": {
                            "posts.json": { "class": "epix-orset-1" }
                        }
                    }),
                },
            ],
            manifest_chains: HashMap::from([
                ("content.json".into(), Vec::new()),
                ("a/content.json".into(), vec!["a/content.json".into()]),
                (
                    "a/b/content.json".into(),
                    vec!["a/b/content.json".into()],
                ),
            ]),
        };

        let snapshot = AppState::db_snapshot_from_authority(
            &canonical,
            &storage,
            &authority,
        )
        .await
        .unwrap();
        let posts = snapshot
            .values
            .iter()
            .find(|(path, _)| path == "a/b/posts.json")
            .map(|(_, value)| value)
            .expect("sanitized merge value");
        assert!(
            epix_content::records_of(posts).is_empty(),
            "unrelated lexical parent authorized an attacker record"
        );
    }

    #[tokio::test]
    async fn xid_cache_clear_invalidates_db_handles_before_its_first_await() {
        let (_dir, state, merger) = merger_with_one_post().await;
        let xites = state.xites.write().await;
        let previous = state.db_filter_epoch();
        let clear = {
            let state = state.clone();
            tokio::spawn(async move { state.xid_clear_cache().await })
        };
        tokio::time::timeout(std::time::Duration::from_secs(1), async {
            while state.db_filter_epoch() == previous {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("xID clear invalidated DBs synchronously");
        assert!(
            state
                .current_db_query_receipt(&merger, xites.get(&merger).unwrap())
                .is_none(),
            "old signer-authorized database remained queryable during xID clear"
        );
        drop(xites);
        clear.await.unwrap();
    }

    #[tokio::test]
    async fn update_content_on_merger_refills_db() {
        let (_dir, state, merger) = merger_with_one_post().await;

        // Replacing the MERGER xite's own content.json (a republish, or an
        // inbound root update) rebuilds its db via build_xite_db, which leaves a
        // version-3 merger EMPTY. update_content must refill it from the merged
        // xites, else the feed goes blank until the next restart or dbRebuild -
        // the Epix Post "all posts missing except the users who posted since the
        // last restart" bug.
        let accepted = state.content(&merger).await.expect("accepted merger root");
        state.update_content(&merger, Some(accepted)).await;
        let rows =
            state.db_query(&merger, "SELECT title FROM post", &Value::Null).await.unwrap();
        assert_eq!(rows.len(), 1, "merger db refilled after its own content update");
        assert_eq!(rows[0]["title"], "hello");
    }

    /// A minimal already-downloaded user-content xite whose child manifest
    /// declares one signed OR-set merge file. The child is intentionally
    /// already at version 42, which is the metadata-first race the inline path
    /// must repair.
    async fn inline_merge_fixture_with_owner_key() -> (
        tempfile::TempDir,
        Arc<AppState>,
        String,
        XiteStorage,
        String,
        String,
        String,
        String,
    ) {
        let dir = tempdir().unwrap();
        let xite_key = epix_crypt::new_seed();
        let xite = epix_crypt::privatekey_to_address(&xite_key).unwrap();
        let author_key = epix_crypt::new_seed();
        let author = epix_crypt::privatekey_to_address(&author_key).unwrap();
        let child = format!("data/users/{author}/content.json");
        let posts = format!("data/users/{author}/posts.json");
        let storage = XiteStorage::new(dir.path().join("xite"));
        let mut root = json!({
            "address": xite,
            "modified": 1.0,
            "files": {},
            "includes": { "data/users/content.json": {} },
        });
        epix_content::sign(&mut root, &xite_key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root).unwrap())
            .unwrap();
        let mut parent = json!({
            "address": xite,
            "inner_path": "data/users/content.json",
            "modified": 2.0,
            "files": {},
            "user_contents": {
                "cert_signers": {},
                "permissions": {},
                "permission_rules": {
                    ".*": {
                        "max_size": 100_000,
                        "merge_files": {
                            "posts.json": { "class": "epix-orset-1", "max_size": 100_000 }
                        }
                    }
                }
            }
        });
        epix_content::sign(&mut parent, &xite_key).unwrap();
        storage
            .write(
                "data/users/content.json",
                &serde_json::to_vec(&parent).unwrap(),
            )
            .unwrap();
        let mut current_child = json!({
            "address": xite,
            "inner_path": child,
            "modified": 42.0,
            "files": {},
            "files_merged": {
                "posts.json": { "class": "epix-orset-1" }
            }
        });
        epix_content::sign(&mut current_child, &author_key).unwrap();
        storage
            .write(
                &child,
                &serde_json::to_vec(&current_child).unwrap(),
            )
            .unwrap();
        storage
            .write(
                &posts,
                &serde_json::to_vec(&epix_content::make_container(Vec::new())).unwrap(),
            )
            .unwrap();

        let state = AppState::new("test");
        state
            .add_xite(
                xite.clone(),
                XiteEntry {
                    storage: storage.clone(),
                    content: Some(root),
                },
            )
            .await;
        (
            dir,
            state,
            xite,
            storage,
            child,
            posts,
            author_key,
            xite_key,
        )
    }

    async fn inline_merge_fixture() -> (
        tempfile::TempDir,
        Arc<AppState>,
        String,
        XiteStorage,
        String,
        String,
        String,
    ) {
        let (dir, state, xite, storage, child, posts, author_key, _) =
            inline_merge_fixture_with_owner_key().await;
        (dir, state, xite, storage, child, posts, author_key)
    }

    fn signed_merge_record(author_key: &str, body: &str) -> Value {
        let author = epix_crypt::privatekey_to_address(author_key).unwrap();
        let nonce = epix_crypt::new_seed();
        let date_added = now_secs();
        let mut record = json!({
            "post_id": epix_content::derive_post_id(&author, &nonce, date_added),
            "nonce": nonce,
            "author": author,
            "clock": epix_core::now_ms(),
            "supersedes": 0,
            "deleted": false,
            "body": body,
            "date_added": date_added,
        });
        let signature =
            epix_crypt::sign(&epix_content::record_signed_data(&record), author_key).unwrap();
        record["sign"] = json!(signature);
        record
    }

    fn record_delta(record: Value) -> Vec<u8> {
        serde_json::to_vec(&epix_content::make_container(vec![record])).unwrap()
    }

    #[tokio::test]
    async fn edx_signed_reads_and_listing_exclude_a_revoked_stale_child() {
        let (_dir, state, xite, storage, child, posts, _author_key) =
            inline_merge_fixture().await;
        let listed = state
            .edx_verified_signed_list(&xite, 0.0, MAX_MERGE_DELTA_OBJECT_BYTES)
            .await;
        assert!(listed.iter().any(|(path, _, _)| path == &child));
        assert!(state
            .edx_read_verified_signed(&xite, &child, MAX_MERGE_DELTA_OBJECT_BYTES)
            .await
            .is_some());
        assert!(state
            .edx_read_verified_signed(&xite, &posts, MAX_MERGE_DELTA_OBJECT_BYTES)
            .await
            .is_some());

        // Keep the stale child bytes on disk while atomically replacing the
        // accepted authority index with the root alone, as a root revocation
        // does. Signed serving must never fall back to the lexical disk walk.
        let root: Value = serde_json::from_slice(&storage.read("content.json").unwrap()).unwrap();
        state.replace_verified_manifest_chains(
            &xite,
            HashMap::from([("content.json".to_string(), Vec::new())]),
        );
        state.replace_verified_manifest_contents(
            &xite,
            &[VerifiedManifestUnit {
                inner_path: "content.json".to_string(),
                content: root,
            }],
        );
        let listed = state
            .edx_verified_signed_list(&xite, 0.0, MAX_MERGE_DELTA_OBJECT_BYTES)
            .await;
        assert!(!listed.iter().any(|(path, _, _)| path == &child));
        assert!(storage.exists(&child), "revoked bytes deliberately remain on disk");
        assert!(state
            .edx_read_verified_signed(&xite, &child, MAX_MERGE_DELTA_OBJECT_BYTES)
            .await
            .is_none());
        assert!(state
            .edx_read_verified_signed(&xite, &posts, MAX_MERGE_DELTA_OBJECT_BYTES)
            .await
            .is_none());
    }

