    #[tokio::test]
    async fn same_version_inline_merges_are_serialized_verified_and_not_discarded() {
        let (_dir, state, xite, storage, child, posts, author_key) = inline_merge_fixture().await;
        let first = signed_merge_record(&author_key, "first");
        let second = signed_merge_record(&author_key, "second");
        let payload = |record| UpdatePayload {
            diffs: HashMap::new(),
            merge_deltas: HashMap::from([("posts.json".to_string(), record_delta(record))]),
            merge_objects: HashMap::new(),
            require_merge_delivery: true,
            defer_required_fetch: false,
        };

        // Both updates carry the content.json version already on disk. Before
        // the fast path they were returned as NotChanged before posts.json was
        // examined. Running them together also exercises read-union-write
        // serialization: neither record may clobber the other.
        let (a, b) = tokio::join!(
            state.apply_inbound_update(
                &xite,
                &child,
                None,
                Some(42.0),
                None,
                None,
                payload(first.clone()),
                Vec::new(),
            ),
            state.apply_inbound_update(
                &xite,
                &child,
                None,
                Some(42.0),
                None,
                None,
                payload(second),
                Vec::new(),
            ),
        );
        assert!(matches!(a.unwrap(), InboundUpdate::Applied));
        assert!(matches!(b.unwrap(), InboundUpdate::Applied));
        let merged: Value = serde_json::from_slice(&storage.read(&posts).unwrap()).unwrap();
        assert_eq!(epix_content::records_of(&merged).len(), 2);

        // A duplicate is idempotent, and a tampered record retaining the old
        // signature is rejected rather than written or re-gossiped.
        let duplicate = state
            .apply_inbound_update(
                &xite,
                &child,
                None,
                Some(42.0),
                None,
                None,
                payload(first.clone()),
                Vec::new(),
            )
            .await
            .unwrap();
        assert!(matches!(duplicate, InboundUpdate::NotChanged));
        let mut tampered = first;
        tampered["body"] = json!("forged");
        let invalid = state
            .apply_inbound_update(
                &xite,
                &child,
                None,
                Some(42.0),
                None,
                None,
                payload(tampered),
                Vec::new(),
            )
            .await;
        assert!(invalid.is_err(), "capable sender must not get an ACK for an invalid delta");
        let merged: Value = serde_json::from_slice(&storage.read(&posts).unwrap()).unwrap();
        assert_eq!(epix_content::records_of(&merged).len(), 2);
    }

    #[tokio::test]
    async fn failed_durable_inline_merge_preserves_the_existing_union_and_withholds_ack() {
        let (_dir, state, xite, storage, child, posts, author_key) =
            inline_merge_fixture().await;
        let existing = signed_merge_record(&author_key, "existing Q");
        storage.write(&posts, &record_delta(existing.clone())).unwrap();
        MERGE_DURABLE_WRITE_FAIL_ONCE
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(storage.path(&posts).unwrap());

        let incoming = signed_merge_record(&author_key, "incoming R");
        let result = state
            .apply_inbound_update(
                &xite,
                &child,
                None,
                Some(42.0),
                None,
                None,
                UpdatePayload {
                    merge_deltas: HashMap::from([(
                        "posts.json".to_string(),
                        record_delta(incoming),
                    )]),
                    require_merge_delivery: true,
                    ..UpdatePayload::default()
                },
                Vec::new(),
            )
            .await;

        assert!(result.is_err(), "a failed durable commit must not receive an ACK");
        let stored: Value = serde_json::from_slice(&storage.read(&posts).unwrap()).unwrap();
        let records = epix_content::records_of(&stored);
        assert_eq!(records.len(), 1);
        assert_eq!(records[0]["body"], existing["body"]);
    }

    #[tokio::test]
    async fn failed_durable_staged_child_merge_preserves_old_union_and_retry_payload() {
        let (_dir, state, xite, storage, child, posts, author_key) =
            inline_merge_fixture().await;
        let existing = signed_merge_record(&author_key, "existing staged Q");
        storage.write(&posts, &record_delta(existing.clone())).unwrap();
        let mut candidate: Value =
            serde_json::from_slice(&storage.read(&child).unwrap()).unwrap();
        candidate["modified"] = json!(43.0);
        candidate.as_object_mut().unwrap().remove("sign");
        candidate.as_object_mut().unwrap().remove("signs");
        epix_content::sign(&mut candidate, &author_key).unwrap();
        let candidate_bytes = serde_json::to_vec(&candidate).unwrap();
        let guard = state.acquire_manifest_guard(&xite, &child).await.unwrap();
        let transaction = AppState::bind_manifest_transaction(
            &storage,
            &xite,
            &child,
            &candidate_bytes,
            guard,
        )
        .unwrap();
        let staged_inner = format!("files/{posts}");
        MERGE_DURABLE_WRITE_FAIL_ONCE
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(
                XiteStorage::new(transaction.lease.stage_root.clone())
                    .path(&staged_inner)
                    .unwrap(),
            );
        let signers = vec![epix_crypt::privatekey_to_address(&author_key).unwrap()];
        let limits = HashMap::from([("posts.json".to_string(), Some(100_000))]);
        let incoming = record_delta(signed_merge_record(&author_key, "incoming staged R"));
        let mut payload = UpdatePayload {
            merge_deltas: HashMap::from([("posts.json".to_string(), incoming.clone())]),
            require_merge_delivery: true,
            ..UpdatePayload::default()
        };

        let result = state
            .stage_child_merge_commit(
                ChildMergeCommit {
                    canonical: &xite,
                    inner_path: &child,
                    storage: &storage,
                    content: &candidate,
                    signers: &signers,
                    merge_limits: &limits,
                    transaction: &transaction,
                },
                &mut payload,
            )
            .await;

        assert!(result.is_err());
        assert_eq!(payload.merge_deltas.get("posts.json"), Some(&incoming));
        let stored: Value = serde_json::from_slice(&storage.read(&posts).unwrap()).unwrap();
        let records = epix_content::records_of(&stored);
        assert_eq!(records.len(), 1);
        assert_eq!(records[0]["body"], existing["body"]);
        assert!(!XiteStorage::new(transaction.lease.stage_root.clone()).exists(&staged_inner));
    }

    #[tokio::test]
    async fn forged_existing_signature_does_not_suppress_valid_record_novelty() {
        let (_dir, state, xite, storage, child, posts, author_key) = inline_merge_fixture().await;
        let valid = signed_merge_record(&author_key, "authorized body");
        let mut forged = valid.clone();
        forged["body"] = json!("forged body");
        storage.write(&posts, &record_delta(forged)).unwrap();

        let outcome = state
            .apply_inbound_update(
                &xite,
                &child,
                None,
                Some(42.0),
                None,
                None,
                UpdatePayload {
                    merge_deltas: HashMap::from([("posts.json".to_string(), record_delta(valid))]),
                    require_merge_delivery: true,
                    ..UpdatePayload::default()
                },
                Vec::new(),
            )
            .await
            .unwrap();

        assert!(matches!(outcome, InboundUpdate::Applied));
        let merged: Value = serde_json::from_slice(&storage.read(&posts).unwrap()).unwrap();
        let records = epix_content::records_of(&merged);
        assert_eq!(records.len(), 1);
        assert_eq!(records[0]["body"], "authorized body");
    }

