    struct StaticInboundSource {
        signed: Vec<u8>,
        signed_calls: AtomicUsize,
    }

    #[async_trait::async_trait]
    impl InboundEdxSource for StaticInboundSource {
        async fn fetch_signed(
            &self,
            _xite: &str,
            _inner_path: &str,
        ) -> Result<Option<Vec<u8>>, String> {
            self.signed_calls.fetch_add(1, Ordering::Relaxed);
            Ok(Some(self.signed.clone()))
        }

        async fn fetch_files(
            &self,
            _address: &str,
            _want: Vec<EdxWant>,
            _staged: Option<Value>,
            _on_file: Option<EdxBatchProgress>,
        ) -> EdxBatch {
            EdxBatch {
                done: Vec::new(),
                missed: Vec::new(),
                bytes: 0,
            }
        }
    }

    struct ObjectInboundSource {
        bytes: Vec<u8>,
        object_calls: AtomicUsize,
        signed_calls: AtomicUsize,
    }

    #[async_trait::async_trait]
    impl InboundEdxSource for ObjectInboundSource {
        async fn fetch_signed(
            &self,
            _xite: &str,
            _inner_path: &str,
        ) -> Result<Option<Vec<u8>>, String> {
            self.signed_calls.fetch_add(1, Ordering::Relaxed);
            Err("object delivery must not fall back to GetSigned".into())
        }

        async fn fetch_object(
            &self,
            _id: epix_blob::ObjId,
            _size: u64,
        ) -> Result<Option<Vec<u8>>, String> {
            self.object_calls.fetch_add(1, Ordering::Relaxed);
            Ok(Some(self.bytes.clone()))
        }

        async fn fetch_files(
            &self,
            _address: &str,
            _want: Vec<EdxWant>,
            _staged: Option<Value>,
            _on_file: Option<EdxBatchProgress>,
        ) -> EdxBatch {
            EdxBatch {
                done: Vec::new(),
                missed: Vec::new(),
                bytes: 0,
            }
        }
    }

    #[tokio::test]
    async fn revoked_stale_parent_cannot_authorize_child_merge_staging() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path().join("xite"));
        let owner_key = epix_crypt::new_seed();
        let owner = epix_crypt::privatekey_to_address(&owner_key).unwrap();
        let child_key = epix_crypt::new_seed();
        let child_signer = epix_crypt::privatekey_to_address(&child_key).unwrap();
        let parent_path = "a/content.json";
        let child_path = "a/deep/content.json";

        let mut root_v1 = json!({
            "address": owner,
            "modified": 1.0,
            "files": {},
            "includes": { (parent_path): {} },
        });
        epix_content::sign(&mut root_v1, &owner_key).unwrap();
        let mut parent = json!({
            "address": owner,
            "inner_path": parent_path,
            "modified": 1.0,
            "files": {},
            "includes": {
                (child_path): {
                    "signers": [child_signer],
                    "signers_required": 1,
                }
            },
        });
        epix_content::sign(&mut parent, &owner_key).unwrap();
        let mut child_v1 = json!({
            "address": owner,
            "inner_path": child_path,
            "modified": 1.0,
            "files": {},
            "files_merged": { "posts.json": { "class": "epix-orset-1" } },
        });
        epix_content::sign(&mut child_v1, &child_key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root_v1).unwrap())
            .unwrap();
        storage
            .write(parent_path, &serde_json::to_vec(&parent).unwrap())
            .unwrap();
        storage
            .write(child_path, &serde_json::to_vec(&child_v1).unwrap())
            .unwrap();

        let state = AppState::new("test");
        state
            .add_xite(
                &owner,
                XiteEntry {
                    storage: storage.clone(),
                    content: Some(root_v1),
                },
            )
            .await;

        let mut root_v2 = json!({
            "address": owner,
            "modified": 2.0,
            "files": {},
        });
        epix_content::sign(&mut root_v2, &owner_key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root_v2).unwrap())
            .unwrap();
        state.update_content(&owner, Some(root_v2)).await;
        state
            .refresh_verified_object_paths(&owner, &owner, &storage)
            .await
            .unwrap();
        assert!(storage.exists(parent_path));
        assert!(storage.exists(child_path));

        let mut child_v2 = child_v1;
        child_v2["modified"] = json!(2.0);
        child_v2.as_object_mut().unwrap().remove("sign");
        child_v2.as_object_mut().unwrap().remove("signs");
        epix_content::sign(&mut child_v2, &child_key).unwrap();
        let delta = record_delta(signed_merge_record(&child_key, "must not fetch"));
        let source = Arc::new(ObjectInboundSource {
            bytes: delta.clone(),
            object_calls: AtomicUsize::new(0),
            signed_calls: AtomicUsize::new(0),
        });
        let result = state
            .apply_inbound_update(
                &owner,
                child_path,
                Some(serde_json::to_vec(&child_v2).unwrap()),
                Some(2.0),
                None,
                Some(source.clone()),
                UpdatePayload {
                    merge_objects: HashMap::from([(
                        "posts.json".to_string(),
                        EdxObjectRef {
                            id: epix_blob::ObjId::of(&delta),
                            size: delta.len() as u64,
                        },
                    )]),
                    require_merge_delivery: true,
                    ..UpdatePayload::default()
                },
                Vec::new(),
            )
            .await;

        assert!(result.is_err());
        assert_eq!(source.object_calls.load(Ordering::Relaxed), 0);
        assert!(!storage.exists("a/deep/posts.json"));
    }

    #[tokio::test]
    async fn revoked_closer_child_cannot_override_root_merge_governor() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path().join("xite"));
        let owner_key = epix_crypt::new_seed();
        let owner = epix_crypt::privatekey_to_address(&owner_key).unwrap();
        let path = "deep/posts.json";
        let first = signed_merge_record(&owner_key, "first");
        let first_id = first["post_id"].as_i64().unwrap();
        storage.write(path, &record_delta(first)).unwrap();
        storage
            .write(
                "deep/content.json",
                br#"{"inner_path":"deep/content.json","files":{}}"#,
            )
            .unwrap();
        let mut root = json!({
            "address": owner,
            "modified": 1.0,
            "files": {},
            "files_merged": {
                (path): { "class": "epix-orset-1" }
            }
        });
        epix_content::sign(&mut root, &owner_key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root).unwrap())
            .unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                &owner,
                XiteEntry {
                    storage: storage.clone(),
                    content: Some(root),
                },
            )
            .await;

        assert_eq!(state.content_inner_path(&owner, path).await, "content.json");
        assert!(state.is_declared_merge_file(&owner, path).await);
        let second = signed_merge_record(&owner_key, "second");
        let second_id = second["post_id"].as_i64().unwrap();
        state
            .write_file(&owner, path, &record_delta(second))
            .await
            .unwrap();
        let stored: Value = serde_json::from_slice(&storage.read(path).unwrap()).unwrap();
        let ids = epix_content::records_of(&stored)
            .into_iter()
            .filter_map(|record| record.get("post_id").and_then(Value::as_i64))
            .collect::<std::collections::BTreeSet<_>>();
        assert_eq!(ids, std::collections::BTreeSet::from([first_id, second_id]));
    }

    #[tokio::test]
    async fn merge_object_fetch_waits_for_path_authorization_and_verifies_hash() {
        let (_dir, state, xite, storage, child, posts, author_key) = inline_merge_fixture().await;
        let bytes = record_delta(signed_merge_record(&author_key, "object-backed delta"));
        let source = Arc::new(ObjectInboundSource {
            bytes: bytes.clone(),
            object_calls: AtomicUsize::new(0),
            signed_calls: AtomicUsize::new(0),
        });
        let object = EdxObjectRef {
            id: epix_blob::ObjId::of(&bytes),
            size: bytes.len() as u64,
        };

        let unnegotiated = state
            .apply_inbound_update(
                &xite,
                &child,
                None,
                Some(42.0),
                None,
                Some(source.clone()),
                UpdatePayload {
                    diffs: HashMap::new(),
                    merge_deltas: HashMap::new(),
                    merge_objects: HashMap::from([("posts.json".to_string(), object)]),
                    require_merge_delivery: false,
                    defer_required_fetch: false,
                },
                Vec::new(),
            )
            .await;
        assert!(unnegotiated.is_err());
        assert_eq!(source.object_calls.load(Ordering::Relaxed), 0);

        let unauthorized = state
            .apply_inbound_update(
                &xite,
                &child,
                None,
                Some(42.0),
                None,
                Some(source.clone()),
                UpdatePayload {
                    diffs: HashMap::new(),
                    merge_deltas: HashMap::new(),
                    merge_objects: HashMap::from([("not-declared.json".to_string(), object)]),
                    require_merge_delivery: true,
                    defer_required_fetch: false,
                },
                Vec::new(),
            )
            .await;
        assert!(unauthorized.is_err());
        assert_eq!(source.object_calls.load(Ordering::Relaxed), 0);

        let duplicate_path = state
            .apply_inbound_update(
                &xite,
                &child,
                None,
                Some(42.0),
                None,
                Some(source.clone()),
                UpdatePayload {
                    diffs: HashMap::new(),
                    merge_deltas: HashMap::from([("posts.json".to_string(), bytes.clone())]),
                    merge_objects: HashMap::from([("posts.json".to_string(), object)]),
                    require_merge_delivery: true,
                    defer_required_fetch: false,
                },
                Vec::new(),
            )
            .await;
        assert!(duplicate_path.is_err());
        assert_eq!(source.object_calls.load(Ordering::Relaxed), 0);

        let oversized = state
            .apply_inbound_update(
                &xite,
                &child,
                None,
                Some(42.0),
                None,
                Some(source.clone()),
                UpdatePayload {
                    diffs: HashMap::new(),
                    merge_deltas: HashMap::new(),
                    merge_objects: HashMap::from([(
                        "posts.json".to_string(),
                        EdxObjectRef {
                            id: object.id,
                            size: MAX_MERGE_DELTA_OBJECT_BYTES + 1,
                        },
                    )]),
                    require_merge_delivery: true,
                    defer_required_fetch: false,
                },
                Vec::new(),
            )
            .await;
        assert!(oversized.is_err());
        assert_eq!(source.object_calls.load(Ordering::Relaxed), 0);

        let aggregate_oversized = state
            .apply_inbound_update(
                &xite,
                &child,
                None,
                Some(42.0),
                None,
                Some(source.clone()),
                UpdatePayload {
                    diffs: HashMap::new(),
                    merge_deltas: HashMap::new(),
                    merge_objects: HashMap::from([
                        (
                            "posts.json".to_string(),
                            EdxObjectRef {
                                id: object.id,
                                size: MAX_MERGE_DELTA_OBJECT_BYTES / 2 + 1,
                            },
                        ),
                        (
                            "second.json".to_string(),
                            EdxObjectRef {
                                id: object.id,
                                size: MAX_MERGE_DELTA_OBJECT_BYTES / 2 + 1,
                            },
                        ),
                    ]),
                    require_merge_delivery: true,
                    defer_required_fetch: false,
                },
                Vec::new(),
            )
            .await;
        assert!(aggregate_oversized.is_err());
        assert_eq!(
            source.object_calls.load(Ordering::Relaxed),
            0,
            "aggregate cap must reject before path authorization or object fetch"
        );

        let bad_hash = state
            .apply_inbound_update(
                &xite,
                &child,
                None,
                Some(42.0),
                None,
                Some(source.clone()),
                UpdatePayload {
                    diffs: HashMap::new(),
                    merge_deltas: HashMap::new(),
                    merge_objects: HashMap::from([(
                        "posts.json".to_string(),
                        EdxObjectRef {
                            id: epix_blob::ObjId::of(b"wrong object"),
                            size: bytes.len() as u64,
                        },
                    )]),
                    require_merge_delivery: true,
                    defer_required_fetch: false,
                },
                Vec::new(),
            )
            .await;
        assert!(bad_hash.is_err());
        assert_eq!(source.object_calls.load(Ordering::Relaxed), 1);
        let merged: Value = serde_json::from_slice(&storage.read(&posts).unwrap()).unwrap();
        assert!(epix_content::records_of(&merged).is_empty());

        let applied = state
            .apply_inbound_update(
                &xite,
                &child,
                None,
                Some(42.0),
                None,
                Some(source.clone()),
                UpdatePayload {
                    diffs: HashMap::new(),
                    merge_deltas: HashMap::new(),
                    merge_objects: HashMap::from([("posts.json".to_string(), object)]),
                    require_merge_delivery: true,
                    defer_required_fetch: false,
                },
                Vec::new(),
            )
            .await
            .unwrap();
        assert!(matches!(applied, InboundUpdate::Applied));
        assert_eq!(source.object_calls.load(Ordering::Relaxed), 2);
        assert_eq!(source.signed_calls.load(Ordering::Relaxed), 0);
        let merged: Value = serde_json::from_slice(&storage.read(&posts).unwrap()).unwrap();
        assert_eq!(epix_content::records_of(&merged).len(), 1);
    }

