    #[tokio::test]
    async fn rehome_under_the_held_governing_manifest_does_not_deadlock() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path().join("xite"));
        let key = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&key).unwrap();
        let bytes = vec![0x5a; 200 * 1024];
        let id = epix_blob::ObjId::of(&bytes);
        storage.write("shared.bin", &bytes).unwrap();
        let mut root = json!({
            "address": address,
            "modified": 1.0,
            "files": {
                "shared.bin": {
                    "size": bytes.len(),
                    "sha512": XiteStorage::hash_bytes(&bytes),
                    "b3": id.to_string(),
                }
            },
        });
        epix_content::sign(&mut root, &key).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root).unwrap())
            .unwrap();
        let state = AppState::new("test");
        let store_dir = tempdir().unwrap();
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                store_dir.path(),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().to_path_buf()),
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        let guard = state
            .acquire_manifest_guard(&address, "content.json")
            .await
            .unwrap();
        let signed = storage.read("content.json").unwrap();
        let transaction = AppState::bind_manifest_transaction(
            &storage,
            &address,
            "content.json",
            &signed,
            guard,
        )
        .unwrap();
        let held = HeldManifestAuthority {
            lease: transaction.lease.clone(),
        };
        let candidate = ObjectDeclarationCandidate {
            id,
            kind: ObjectDeclarationKind::File,
            accounting_key: address.clone(),
            canonical: address,
            storage: storage.clone(),
            governing: "content.json".to_string(),
            authority_chain: Vec::new(),
            inner_path: "shared.bin".to_string(),
        };
        tokio::time::timeout(
            std::time::Duration::from_secs(2),
            state.try_rehome_object(store.clone(), &candidate, Some(&held)),
        )
        .await
        .expect("rehome tried to reacquire its held manifest mutex")
        .unwrap();
        drop(transaction);
        assert!(store.is_complete(id).unwrap());
        assert_eq!(store.ref_delta(id, 0).unwrap(), 1, "rehome restores the declaration pin");
    }

    #[tokio::test]
    async fn postcommit_rehomes_do_not_hold_crossed_manifest_mutexes() {
        let dir = tempdir().unwrap();
        let state = AppState::new("test");
        let store = Arc::new(
            epix_blob::store::Store::open_with(
                dir.path().join("store"),
                epix_blob::store::StoreConfig {
                    xite_root: Some(dir.path().to_path_buf()),
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        state.set_edx_store(store.clone()).await.unwrap();

        let mut fixtures = Vec::new();
        for byte in [0x61, 0x62] {
            let key = epix_crypt::new_seed();
            let address = epix_crypt::privatekey_to_address(&key).unwrap();
            let storage = XiteStorage::new(dir.path().join(&address));
            let payload = vec![byte; 200 * 1024];
            let id = epix_blob::ObjId::of(&payload);
            storage.write("asset.bin", &payload).unwrap();
            let mut root = json!({
                "address": address,
                "modified": 1.0,
                "files": {
                    "asset.bin": {
                        "size": payload.len(),
                        "sha512": XiteStorage::hash_bytes(&payload),
                        "b3": id.to_string(),
                    }
                },
            });
            epix_content::sign(&mut root, &key).unwrap();
            let signed = serde_json::to_vec(&root).unwrap();
            storage.write("content.json", &signed).unwrap();
            state
                .add_xite(
                    &address,
                    XiteEntry { storage: storage.clone(), content: Some(root) },
                )
                .await;
            fixtures.push((address, storage, signed, id));
        }

        let guard_a = state
            .acquire_manifest_guard(&fixtures[0].0, "content.json")
            .await
            .unwrap();
        let transaction_a = AppState::bind_manifest_transaction(
            &fixtures[0].1,
            &fixtures[0].0,
            "content.json",
            &fixtures[0].2,
            guard_a,
        )
        .unwrap();
        let guard_b = state
            .acquire_manifest_guard(&fixtures[1].0, "content.json")
            .await
            .unwrap();
        let transaction_b = AppState::bind_manifest_transaction(
            &fixtures[1].1,
            &fixtures[1].0,
            "content.json",
            &fixtures[1].2,
            guard_b,
        )
        .unwrap();
        let (candidate_a, candidate_b) = {
            let declarations = state.edx_paths.read().unwrap();
            (
                declarations[&fixtures[0].3][0].clone(),
                declarations[&fixtures[1].3][0].clone(),
            )
        };
        transaction_a.lease.release_manifest_mutex();
        transaction_b.lease.release_manifest_mutex();
        let held_a = HeldManifestAuthority { lease: transaction_a.lease.clone() };
        let held_b = HeldManifestAuthority { lease: transaction_b.lease.clone() };
        let first = state.try_rehome_object(store.clone(), &candidate_b, Some(&held_a));
        let second = state.try_rehome_object(store, &candidate_a, Some(&held_b));
        let (first, second) = tokio::time::timeout(
            std::time::Duration::from_secs(3),
            futures_util::future::join(first, second),
        )
        .await
        .expect("crossed postcommit rehomes deadlocked on their origin manifests");
        first.unwrap();
        second.unwrap();
    }

