    #[tokio::test]
    async fn owned_xites_are_never_html_gated() {
        struct AlwaysClone;
        #[async_trait::async_trait]
        impl OnDemandResolver for AlwaysClone {
            async fn ensure(&self, _host: &str) -> Result<(), String> {
                Ok(())
            }
            async fn resolve(&self, host: &str) -> Option<String> {
                host.starts_with("epix1").then(|| host.to_string())
            }
        }
        let dir = tempfile::tempdir().unwrap();
        let s = AppState::new("test");
        s.add_xite(
            "epix1x",
            XiteEntry { storage: XiteStorage::new(dir.path()), content: None,
            },
        )
        .await;
        // No resolver: nothing can complete a download, so nothing is gated.
        assert!(!s.html_doc_gated("epix1x").await);
        s.set_on_demand(Arc::new(AlwaysClone)).await;
        // Incomplete on disk (no verified core set): the document waits.
        assert!(s.html_doc_gated("epix1x").await);
        // But never for an owned xite - local edits must keep serving.
        s.set_owned("epix1x", true).await;
        assert!(!s.html_doc_gated("epix1x").await);
    }

    #[tokio::test]
    async fn lag_recovery_resends_closing_updates_for_finished_xites_only() {
        let dir = tempfile::tempdir().unwrap();
        let s = AppState::new("test");
        s.add_xite(
            "epix1done",
            XiteEntry { storage: XiteStorage::new(dir.path().join("a")), content: None,
            },
        )
        .await;
        s.add_xite(
            "epix1busy",
            XiteEntry { storage: XiteStorage::new(dir.path().join("b")), content: None,
            },
        )
        .await;
        s.begin_xite_update("epix1busy");
        let mut events = s.subscribe_events();

        // Only the finished xite gets its closing event re-sent, and only to
        // the asking connection - the busy one's real outcome is still coming.
        s.push_missed_update_results(7).await;
        let ev = events.try_recv().unwrap();
        assert_eq!(ev.only, Some(7));
        let payload: Value = serde_json::from_str(&ev.payload).unwrap();
        assert_eq!(payload["cmd"], "setSiteInfo");
        assert_eq!(payload["params"]["address"], "epix1done");
        assert_eq!(payload["params"]["event"][0], "updated");
        // Recovery retires a stranded pill; it must not claim an update landed.
        assert_eq!(payload["params"]["update_applied"], json!(false));
        assert!(events.try_recv().is_err(), "no event for the in-flight site");

        // Once its pass ends, a later recovery covers it too.
        s.end_xite_update("epix1busy");
        s.push_missed_update_results(7).await;
        let mut addrs = Vec::new();
        while let Ok(ev) = events.try_recv() {
            let p: Value = serde_json::from_str(&ev.payload).unwrap();
            addrs.push(p["params"]["address"].as_str().unwrap().to_string());
        }
        addrs.sort();
        assert_eq!(addrs, ["epix1busy", "epix1done"]);
    }

    /// The dashboard's row pill is driven by two things: `update_phase` on
    /// every siteInfo (so a page that loads mid-pass shows the same pill as one
    /// that watched it start) and `update_applied` on the closing event (so
    /// only a pass that brought something flashes "Updated!").
    #[tokio::test]
    async fn update_phase_and_outcome_reach_xite_info() {
        let dir = tempfile::tempdir().unwrap();
        let s = AppState::new("test");
        s.add_xite(
            "epix1p",
            XiteEntry { storage: XiteStorage::new(dir.path().join("a")), content: None,
            },
        )
        .await;

        // Idle: no phase at all, so no pill.
        assert_eq!(s.xite_info("epix1p").await["update_phase"], Value::Null);

        // A pass opens on the quiet checking phase. No peers probed yet, so no
        // progress either - the row shows a bar only for something countable.
        s.begin_xite_update("epix1p");
        assert_eq!(s.xite_info("epix1p").await["update_phase"], UPDATE_PHASE_CHECKING);
        assert_eq!(s.xite_info("epix1p").await["progress"], Value::Null);

        // The check walks its candidate peers; its position is the progress.
        s.set_check_progress("epix1p", 3, 10).await;
        assert_eq!(
            s.xite_info("epix1p").await["progress"],
            json!({ "done": 3, "total": 10 })
        );

        // A peer answered with something newer: the pass escalates, and the
        // peer-walk progress no longer applies (it belongs to checking).
        assert!(s.mark_xite_update_applying("epix1p"), "bracketed pass escalates");
        assert_eq!(s.xite_info("epix1p").await["update_phase"], UPDATE_PHASE_UPDATING);
        assert_eq!(s.xite_info("epix1p").await["progress"], Value::Null);

        // A file batch primes the worker counters; progress = done/total files.
        s.set_worker_stats("epix1p", 8, 1, 8).await;
        assert_eq!(
            s.xite_info("epix1p").await["progress"],
            json!({ "done": 0, "total": 8 })
        );
        s.set_worker_stats("epix1p", 2, 1, 0).await;
        assert_eq!(
            s.xite_info("epix1p").await["progress"],
            json!({ "done": 6, "total": 8 })
        );
        // Batch drained: total clears with it.
        s.set_worker_stats("epix1p", 0, 0, 0).await;
        assert_eq!(s.xite_info("epix1p").await["progress"], Value::Null);

        // A caller that never bracketed gets no phase - nothing would push the
        // outcome that retires its pill, so it must not raise one.
        assert!(!s.mark_xite_update_applying("epix1other"), "unbracketed pass is ignored");

        s.end_xite_update("epix1p");
        assert_eq!(s.xite_info("epix1p").await["update_phase"], Value::Null);

        // The three outcomes, as the row renders them.
        let mut events = s.subscribe_events();
        let outcome = |ev: &UiEvent| -> Value {
            serde_json::from_str::<Value>(&ev.payload).unwrap()["params"].clone()
        };

        s.push_update_result("epix1p", UpdateOutcome::Applied).await;
        let p = outcome(&events.try_recv().unwrap());
        assert_eq!(p["event"][0], "updated");
        assert_eq!(p["update_applied"], json!(true), "Applied flashes Updated!");
        assert_ne!(p["content_updated"], json!(false));

        s.push_update_result("epix1p", UpdateOutcome::NoChange).await;
        let p = outcome(&events.try_recv().unwrap());
        assert_eq!(p["event"][0], "updated");
        assert_eq!(p["update_applied"], json!(false), "NoChange retires the pill quietly");
        assert_ne!(p["content_updated"], json!(false), "not an error");

        s.push_update_result("epix1p", UpdateOutcome::Failed).await;
        let p = outcome(&events.try_recv().unwrap());
        assert_eq!(p["update_applied"], json!(false));
        assert_eq!(p["content_updated"], json!(false), "Failed keeps the error marker");
    }

    #[tokio::test]
    async fn server_info_push_targets_server_changed() {
        let s = AppState::new("test");
        let mut events = s.subscribe_events();
        s.push_server_info().await;
        let ev = events.try_recv().unwrap();
        assert_eq!(ev.channel.as_deref(), Some("serverChanged"));
        let payload: Value = serde_json::from_str(&ev.payload).unwrap();
        assert_eq!(payload["cmd"], "setServerInfo");
        assert!(payload["params"]["version"].is_string());
    }

    #[tokio::test]
    async fn error_log_pushes_server_errors() {
        let s = AppState::new("test");
        let mut events = s.subscribe_events();

        s.log("INFO", "routine activity").await;
        assert!(events.try_recv().is_err(), "INFO is not worth a push");

        s.log("ERROR", "sync failed").await;
        let ev = events.try_recv().unwrap();
        assert_eq!(ev.channel.as_deref(), Some("serverChanged"));
        let payload: Value = serde_json::from_str(&ev.payload).unwrap();
        assert_eq!(payload["cmd"], "setServerErrors");
        let errors = payload["params"].as_array().unwrap();
        assert_eq!(errors.len(), 1, "only the error line, not the INFO one");
        assert_eq!(errors[0][2], "sync failed");
    }

    #[tokio::test]
    async fn i2p_status_pushes_only_on_reachability_change() {
        let s = AppState::new("test");
        let mut events = s.subscribe_events();

        s.set_i2p_status(json!({ "mode": "both", "phase": "Starting…", "b32": "" })).await;
        let ev = events.try_recv().unwrap();
        assert_eq!(ev.channel.as_deref(), Some("serverChanged"));

        // Same phase, moved counters: the poll loop's normal case.
        s.set_i2p_status(json!({ "mode": "both", "phase": "Starting…", "b32": "", "tunnels_built": 3 }),
        )
            .await;
        assert!(events.try_recv().is_err(), "counters alone do not push");

        s.set_i2p_status(json!({ "mode": "both", "phase": "ready", "b32": "xyz.b32.i2p" })).await;
        let ev = events.try_recv().unwrap();
        let payload: Value = serde_json::from_str(&ev.payload).unwrap();
        assert_eq!(payload["cmd"], "setServerInfo");
        assert_eq!(payload["params"]["network_status"]["i2p"]["reachable"], json!(true));
    }

    #[tokio::test]
    async fn file_info_any_finds_user_content_optional_files() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let privatekey = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&privatekey).unwrap();
        let child_path = "data/users/u1/content.json";
        let mut child = json!({
            "address": address,
            "inner_path": child_path,
            "modified": 1.0,
            "files": { "data.json": { "size": 2, "sha512": "dd".repeat(32) } },
            "files_optional": { "1.jpg": { "size": 7, "sha512": "aa".repeat(32) } },
        });
        epix_content::sign(&mut child, &privatekey).unwrap();
        storage
            .write(
                child_path,
                &serde_json::to_vec(&child).unwrap(),
            )
            .unwrap();
        let mut root = json!({
            "address": address,
            "modified": 1.0,
            "files": { "index.html": { "size": 1, "sha512": "ff".repeat(32) } },
            "includes": { child_path: {} },
        });
        epix_content::sign(&mut root, &privatekey).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&root).unwrap())
            .unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                &address,
                XiteEntry {
                    storage,
                    content: Some(root),
                },
            )
            .await;

        // The root content.json does not declare the user's image, so the
        // root-only lookup misses...
        let root = state.content(&address).await.unwrap();
        assert!(root["files"].get("data/users/u1/1.jpg").is_none());
        assert!(root.get("files_optional").is_none());
        // ...but its governing child content.json does, as optional, with the
        // xite-relative inner path kept.
        let (info, optional) =
            state.file_info_any(&address, "data/users/u1/1.jpg").await.unwrap();
        assert!(optional);
        assert_eq!(info.inner_path, "data/users/u1/1.jpg");
        assert_eq!(info.size, 7);
        assert_eq!(info.sha512, "aa".repeat(32));
        // Required child files come back optional=false; root files still hit.
        let (_, optional) =
            state.file_info_any(&address, "data/users/u1/data.json").await.unwrap();
        assert!(!optional);
        let (info, optional) = state.file_info_any(&address, "index.html").await.unwrap();
        assert!(!optional);
        assert_eq!(info.size, 1);
        // Undeclared paths miss.
        assert!(state.file_info_any("epix1hub", "data/users/u1/2.jpg").await.is_none());
    }

    #[tokio::test]
    async fn resolve_merged_enforces_the_permission_matrix() {
        let dir = tempdir().unwrap();
        let state = AppState::new("test");
        state
            .add_xite(
                "epix1merger",
                XiteEntry {
                    storage: XiteStorage::new(dir.path().join("merger")),
                    content: Some(json!({ "address": "epix1merger", "files": {} })),
                },
            )
            .await;
        state
            .add_xite(
                "epix1hub",
                XiteEntry {
                    storage: XiteStorage::new(dir.path().join("hub")),
                    content: Some(json!({
                        "address": "epix1hub",
                        "merged_type": "EpixTalk",
                        "files": {},
                    })),
                },
            )
            .await;

        // Not a merged path at all.
        assert_eq!(state.resolve_merged("epix1merger", "index.html").await, Ok(None));

        // The merger holds no Merger:EpixTalk permission yet.
        assert!(state
            .resolve_merged("epix1merger", "merged-EpixTalk/epix1hub/avatar.jpg")
            .await
            .is_err());

        state.add_permission("epix1merger", "Merger:EpixTalk").await;

        // Happy path.
        assert_eq!(
            state.resolve_merged("epix1merger", "merged-EpixTalk/epix1hub/avatar.jpg").await,
            Ok(Some(("epix1hub".to_string(), "avatar.jpg".to_string())))
        );

        // The target must be a registered xite.
        assert!(state
            .resolve_merged("epix1merger", "merged-EpixTalk/epix1nowhere/avatar.jpg")
            .await
            .is_err());

        // The target must declare the requested merged_type.
        state.add_permission("epix1merger", "Merger:GitCenter").await;
        assert!(state
            .resolve_merged("epix1merger", "merged-GitCenter/epix1hub/x")
            .await
            .is_err());

        // Exception: a target still cloning has no content.json to declare its
        // merged_type yet - it resolves so its files serve during the clone.
        state
            .add_xite(
                "epix1cloning",
                XiteEntry { storage: XiteStorage::new(dir.path().join("cloning")), content: None,
                },
            )
            .await;
        state.begin_clone("epix1cloning");
        assert_eq!(
            state.resolve_merged("epix1merger", "merged-EpixTalk/epix1cloning/avatar.jpg").await,
            Ok(Some(("epix1cloning".to_string(), "avatar.jpg".to_string())))
        );
        // Once the clone ends without declaring the type, it is refused again.
        state.end_clone("epix1cloning");
        assert!(state
            .resolve_merged("epix1merger", "merged-EpixTalk/epix1cloning/avatar.jpg")
            .await
            .is_err());
    }

    #[tokio::test]
    async fn a_cancelled_file_need_removes_its_lock_map_entry() {
        let dir = tempdir().unwrap();
        let storage = XiteStorage::new(dir.path());
        let state = AppState::new("test");
        let privatekey = epix_crypt::new_seed();
        let address = epix_crypt::privatekey_to_address(&privatekey).unwrap();
        let sha512 = XiteStorage::hash_bytes(b"abc");
        let mut content = json!({
            "address": address,
            "modified": 1.0,
            "files": {},
            "files_optional": { "a.bin": { "size": 3, "sha512": sha512 } },
        });
        epix_content::sign(&mut content, &privatekey).unwrap();
        storage
            .write("content.json", &serde_json::to_vec(&content).unwrap())
            .unwrap();
        state
            .add_xite(&address, XiteEntry {
                storage,
                content: Some(content),
            },
            )
            .await;
        std::mem::forget(dir);

        // Hold the per-file lock so the fetch blocks at an await point, then
        // cancel it - serve_file's 45s timeout does exactly this - and the
        // dropped future's map entry must still be removed.
        let lock_key = (address.clone(), "a.bin".to_string());
        let lock = state
            .file_need_locks
            .lock()
            .unwrap()
            .entry(lock_key.clone())
            .or_default()
            .clone();
        let _guard = lock.lock().await;
        let cancelled = tokio::time::timeout(
            std::time::Duration::from_millis(50),
            state.file_need(&address, "a.bin"),
        )
        .await;
        assert!(cancelled.is_err(), "the fetch must still be blocked when the timeout fires");
        assert!(!state.file_need_locks.lock().unwrap().contains_key(&lock_key));
    }

