    /// A record landing in an already sealed interval re-derives that interval
    /// under a NEW root, so pinning every derivation would keep every
    /// superseded copy on disk forever (eviction only reclaims refcount-0).
    /// Also pins the skip-filter sibling, which is keyed by the hash of its own
    /// bytes because that is the only key `insert_bytes` accepts.
    #[test]
    fn feed_objects_hold_one_distinct_global_store_reference() {
        let dir = tempdir().unwrap();
        let store = Arc::new(epix_blob::store::Store::open(dir.path()).unwrap());
        let state = AppState::new("test");
        let rec = |id: &str, body: &str, clock: u64| epix_feed::Record {
            canonical: json!({ "id": id, "body": body }).to_string().into_bytes(),
            id: id.to_string(),
            author: "epix1author".to_string(),
            target: String::new(),
            clock,
            kind: epix_feed::Kind::Post,
        };
        // Well past both the interval and its pin grace, so the segment counts
        // as settled and gets pinned.
        let ts = 10 * crate::feed::SEGMENT_INTERVAL_MS;

        let first = Arc::new(crate::feed::derive_feed(vec![rec("a", "alpha bravo", 1_000)]));
        let root = first.sealed[0].root;
        let filter_id = epix_blob::ObjId::of(&first.filters[0].to_bytes());
        let first_feeds = HashMap::from([("posts".to_string(), first.clone())]);
        let desired = AppState::insert_feed_objects(&store, &first_feeds, ts);
        let first_owned = state.transition_feed_object_owners(
            &store,
            &std::collections::HashSet::new(),
            &desired,
        );
        assert!(store.contains(root).unwrap(), "the segment blob is stored");
        assert!(store.contains(filter_id).unwrap(), "the skip-filter sibling is stored");
        assert_eq!(store.ref_delta(root, 0).unwrap(), 1, "a settled segment is pinned");
        assert_eq!(store.ref_delta(filter_id, 0).unwrap(), 1);

        // A second address advertising identical artifacts shares the one
        // feed-owned Store reference instead of incrementing it again.
        let second_owner = state.transition_feed_object_owners(
            &store,
            &std::collections::HashSet::new(),
            &desired,
        );
        assert_eq!(store.ref_delta(root, 0).unwrap(), 1);
        let first_released = state.transition_feed_object_owners(
            &store,
            &first_owned,
            &std::collections::HashSet::new(),
        );
        assert!(first_released.is_empty());
        assert_eq!(store.ref_delta(root, 0).unwrap(), 1, "the second address still owns it");

        // A second record in the SAME interval re-seals it under a new root.
        let second = Arc::new(crate::feed::derive_feed(vec![
            rec("a", "alpha bravo", 1_000),
            rec("b", "charlie delta", 2_000),
        ]));
        assert_ne!(second.sealed[0].root, root, "the interval re-sealed");
        let second_feeds = HashMap::from([("posts".to_string(), second.clone())]);
        let second_desired = AppState::insert_feed_objects(&store, &second_feeds, ts);
        let second_owned = state.transition_feed_object_owners(
            &store,
            &second_owner,
            &second_desired,
        );
        assert_eq!(store.ref_delta(root, 0).unwrap(), 0, "the superseded root is evictable");
        assert_eq!(store.ref_delta(filter_id, 0).unwrap(), 0);
        assert_eq!(
            store.ref_delta(second.sealed[0].root, 0).unwrap(),
            1,
            "the current root stays pinned"
        );

        // The live tail (an interval still inside the grace window) churns on
        // every merge, so it goes in unpinned - superseded copies must stay
        // evictable.
        let live = Arc::new(crate::feed::derive_feed(vec![rec("c", "echo foxtrot", ts)]));
        let live_feeds = HashMap::from([("posts".to_string(), live.clone())]);
        let live_desired = AppState::insert_feed_objects(&store, &live_feeds, ts);
        let live_owned = state.transition_feed_object_owners(&store, &second_owned, &live_desired);
        assert!(live_owned.is_empty());
        assert!(store.contains(live.sealed[0].root).unwrap(), "still stored, just not pinned");
        assert_eq!(store.ref_delta(live.sealed[0].root, 0).unwrap(), 0, "live tail is unpinned");
    }

    #[test]
    fn feed_reference_is_distinct_from_an_identical_manifest_reference() {
        let dir = tempdir().unwrap();
        let store = epix_blob::store::Store::open(dir.path()).unwrap();
        let state = AppState::new("test");
        let artifacts = Arc::new(crate::feed::derive_feed(vec![epix_feed::Record {
            canonical: json!({ "id": "same", "body": "manifest collision" })
                .to_string()
                .into_bytes(),
            id: "same".to_string(),
            author: "epix1author".to_string(),
            target: String::new(),
            clock: 1_000,
            kind: epix_feed::Kind::Post,
        }]));
        let root = artifacts.sealed[0].root;
        let feeds = HashMap::from([("posts".to_string(), artifacts)]);
        let desired = AppState::insert_feed_objects(
            &store,
            &feeds,
            10 * crate::feed::SEGMENT_INTERVAL_MS,
        );
        store.pin(root).unwrap();
        store.claim_manifest(root).unwrap();
        assert_eq!(store.ref_delta(root, 0).unwrap(), 1, "manifest owns one reference");
        let owned = state.transition_feed_object_owners(
            &store,
            &std::collections::HashSet::new(),
            &desired,
        );
        assert_eq!(store.ref_delta(root, 0).unwrap(), 2, "feed owns a distinct reference");
        let retained = state.transition_feed_object_owners(
            &store,
            &owned,
            &std::collections::HashSet::new(),
        );
        assert!(retained.is_empty());
        assert_eq!(
            store.ref_delta(root, 0).unwrap(),
            1,
            "clearing the feed preserves manifest ownership"
        );
        store.release_manifest(root).unwrap();
        assert_eq!(store.ref_delta(root, 0).unwrap(), 0);
    }

    #[test]
    fn manifest_reference_is_distinct_when_a_feed_owned_the_object_first() {
        let dir = tempdir().unwrap();
        let store = epix_blob::store::Store::open(dir.path()).unwrap();
        let state = AppState::new("test");
        let bytes = vec![7u8; 1024];
        let id = epix_blob::ObjId::of(&bytes);
        store
            .insert_bytes(id, epix_blob::Ns::Plain, &bytes, 1)
            .unwrap();
        let desired = std::collections::HashSet::from([id]);
        let feed_owned = state.transition_feed_object_owners(
            &store,
            &std::collections::HashSet::new(),
            &desired,
        );
        assert_eq!(store.ref_delta(id, 0).unwrap(), 1);

        assert!(state.transition_manifest_object_owners(&store, &desired).is_empty());
        assert_eq!(store.ref_delta(id, 0).unwrap(), 2);
        assert!(state
            .transition_manifest_object_owners(&store, &std::collections::HashSet::new())
            .is_empty());
        assert_eq!(store.ref_delta(id, 0).unwrap(), 1);

        assert!(state
            .transition_feed_object_owners(
                &store,
                &feed_owned,
                &std::collections::HashSet::new(),
            )
            .is_empty());
        assert_eq!(store.ref_delta(id, 0).unwrap(), 0);
    }

    #[test]
    fn unchanged_feed_reclaims_its_marker_after_object_recreation() {
        let dir = tempdir().unwrap();
        let store = epix_blob::store::Store::open(dir.path()).unwrap();
        let state = AppState::new("test");
        let bytes = vec![9u8; 1024];
        let id = epix_blob::ObjId::of(&bytes);
        store
            .insert_bytes(id, epix_blob::Ns::Plain, &bytes, 1)
            .unwrap();
        let desired = std::collections::HashSet::from([id]);
        let owned = state.transition_feed_object_owners(
            &store,
            &std::collections::HashSet::new(),
            &desired,
        );
        store.remove(id).unwrap();
        store
            .insert_bytes(id, epix_blob::Ns::Plain, &bytes, 2)
            .unwrap();
        let restored = state.transition_feed_object_owners(&store, &owned, &desired);
        assert_eq!(restored, desired);
        assert_eq!(store.ref_delta(id, 0).unwrap(), 1);
        assert!(state
            .transition_feed_object_owners(
                &store,
                &restored,
                &std::collections::HashSet::new(),
            )
            .is_empty());
        assert_eq!(store.ref_delta(id, 0).unwrap(), 0);
    }

    #[tokio::test]
    async fn cancelling_a_contended_feed_install_cannot_split_cache_and_store_state() {
        let dir = tempdir().unwrap();
        let store = Arc::new(epix_blob::store::Store::open(dir.path()).unwrap());
        let state = AppState::new("test");
        let record = |id: &str, body: &str| epix_feed::Record {
            canonical: json!({ "id": id, "body": body }).to_string().into_bytes(),
            id: id.to_string(),
            author: "epix1author".to_string(),
            target: String::new(),
            clock: 1_000,
            kind: epix_feed::Kind::Post,
        };
        let first = Arc::new(crate::feed::derive_feed(vec![record("one", "first")]));
        let second = Arc::new(crate::feed::derive_feed(vec![record("two", "second")]));
        let first_root = first.sealed[0].root;
        let second_root = second.sealed[0].root;
        let timestamp = 10 * crate::feed::SEGMENT_INTERVAL_MS;
        state
            .install_feed_cache("epix1feed", FeedCacheInstall {
                canonical: "epix1feed".to_string(),
                verified_index: 1,
                source: 1,
                feeds: HashMap::from([("posts".to_string(), first)]),
                store: Some(store.clone()),
                timestamp,
            })
            .await;
        assert_eq!(store.ref_delta(first_root, 0).unwrap(), 1);

        let cache_guard = state.feed_cache.write().await;
        let task_state = state.clone();
        let task_store = store.clone();
        let install = tokio::spawn(async move {
            task_state
                .install_feed_cache("epix1feed", FeedCacheInstall {
                    canonical: "epix1feed".to_string(),
                    verified_index: 1,
                    source: 2,
                    feeds: HashMap::from([("posts".to_string(), second)]),
                    store: Some(task_store),
                    timestamp,
                })
                .await;
        });
        tokio::task::yield_now().await;
        install.abort();
        assert!(install.await.is_err());
        assert_eq!(store.ref_delta(first_root, 0).unwrap(), 1);
        assert!(!store.contains(second_root).unwrap(), "Store changes start after cache locks");
        drop(cache_guard);
        let cache = state.feed_cache.read().await;
        assert_eq!(cache["epix1feed"]["posts"].sealed[0].root, first_root);
        let epoch = state.feed_cache_epochs.read().await;
        assert_eq!(epoch["epix1feed"].source, 1);
    }

    #[tokio::test]
    async fn feed_cache_store_swap_moves_its_distinct_reference() {
        let dir_a = tempdir().unwrap();
        let dir_b = tempdir().unwrap();
        let store_a = Arc::new(epix_blob::store::Store::open(dir_a.path()).unwrap());
        let store_b = Arc::new(epix_blob::store::Store::open(dir_b.path()).unwrap());
        let state = AppState::new("test");
        let artifacts = Arc::new(crate::feed::derive_feed(vec![epix_feed::Record {
            canonical: json!({ "id": "swap", "body": "same bytes" })
                .to_string()
                .into_bytes(),
            id: "swap".to_string(),
            author: "epix1author".to_string(),
            target: String::new(),
            clock: 1_000,
            kind: epix_feed::Kind::Post,
        }]));
        let root = artifacts.sealed[0].root;
        let feeds = HashMap::from([("posts".to_string(), artifacts)]);
        let timestamp = 10 * crate::feed::SEGMENT_INTERVAL_MS;
        let _ = AppState::insert_feed_objects(&store_b, &feeds, timestamp);
        store_b.pin(root).unwrap();

        state
            .install_feed_cache("epix1feed", FeedCacheInstall {
                canonical: "epix1feed".to_string(),
                verified_index: 1,
                source: 1,
                feeds: feeds.clone(),
                store: Some(store_a.clone()),
                timestamp,
            })
            .await;
        assert_eq!(store_a.ref_delta(root, 0).unwrap(), 1);
        state
            .install_feed_cache("epix1feed", FeedCacheInstall {
                canonical: "epix1feed".to_string(),
                verified_index: 1,
                source: 1,
                feeds,
                store: Some(store_b.clone()),
                timestamp,
            })
            .await;
        assert_eq!(store_a.ref_delta(root, 0).unwrap(), 0, "old Store ownership is released");
        assert_eq!(store_b.ref_delta(root, 0).unwrap(), 2, "new Store has manifest plus feed refs");
        state.clear_feed_cache("epix1feed").await;
        assert_eq!(
            store_b.ref_delta(root, 0).unwrap(),
            1,
            "clearing after the swap preserves the new Store's manifest ref"
        );
    }

    #[tokio::test]
